INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Ec', 12, 'pt', '[{"numero": 1, "texto": "Portanto lembra-te de teu Criador nos dias de tua juventude, antes que venham os dias ruins, e cheguem os anos, dos quais venhas a dizer: Não tenho neles contentamento;"}, {"numero": 2, "texto": "Antes que se escureçam o sol, a luz, a lua e as estrelas; e voltem as nuvens após a chuva."}, {"numero": 3, "texto": "No dia em que os guardas da casa tremerem, e os homens fortes se encurvarem; e cessarem os moedores, por terem diminuído, e se escurecerem os que olham pelas janelas;"}, {"numero": 4, "texto": "E as portas da rua se fecharem, enquanto se abaixa o ruído da moedura; e se levantar a voz das aves, e todas as vozes do canto se encurvarem."}, {"numero": 5, "texto": "Como também [quando] temerem as coisas altas, e houver espantos no caminho; e florescer a amendoeira, e o gafanhoto se tornar pesado, e acabar o apetite; porque o homem vai para sua casa eterna, e os que choram andarão ao redor da praça;"}, {"numero": 6, "texto": "Antes que se afrouxe a correia de prata, e de despedace a vasilha de ouro; e se quebre o vaso junto à fonte, e se despedace a roda junto ao poço."}, {"numero": 7, "texto": "E o pó volte à terra, assim como era; e o espírito volte a Deus, que o deu."}, {"numero": 8, "texto": "Futilidade das futilidades! - diz o pregador - Tudo é futilidade."}, {"numero": 9, "texto": "Além do Pregador ter sido sábio, ele também ensinou conhecimento ao povo. Ele ouviu, investigou e pôs em ordem muitos provérbios."}, {"numero": 10, "texto": "O Pregador procurou achar palavras agradáveis, e escreveu coisas corretas, palavras de verdade."}, {"numero": 11, "texto": "As palavras dos sábios são como aguilhões, e como pregos bem fixados [pelos] mestres das congregações, [que] foram dadas pelo único Pastor."}, {"numero": 12, "texto": "Além destas coisas, filho meu, tem cuidado; fazer muitos livros é [algo que] não tem fim; e estudar muito cansa a carne."}, {"numero": 13, "texto": "De tudo o que foi ouvido, a conclusão é: teme a Deus, e guarda os mandamentos dele; porque isto é [o dever de] todo homem."}, {"numero": 14, "texto": "Porque Deus trará a julgamento toda obra, até mesmo tudo o que está encoberto, seja bom ou mal."}]'::jsonb, 'Almeida Livre'),
  ('Ec', 12, 'en', '[{"numero": 1, "texto": "Remember now thy Creator in the days of thy youth, while the evil days come not, nor the years draw nigh, when thou shalt say, I have no pleasure in them;"}, {"numero": 2, "texto": "While the sun, or the light, or the moon, or the stars, be not darkened, nor the clouds return after the rain:"}, {"numero": 3, "texto": "In the day when the keepers of the house shall tremble, and the strong men shall bow themselves, and the grinders cease because they are few, and those that look out of the windows be darkened,"}, {"numero": 4, "texto": "And the doors shall be shut in the streets, when the sound of the grinding is low, and he shall rise up at the voice of the bird, and all the daughters of musick shall be brought low;"}, {"numero": 5, "texto": "Also when they shall be afraid of that which is high, and fears shall be in the way, and the almond tree shall flourish, and the grasshopper shall be a burden, and desire shall fail: because man goeth to his long home, and the mourners go about the streets:"}, {"numero": 6, "texto": "Or ever the silver cord be loosed, or the golden bowl be broken, or the pitcher be broken at the fountain, or the wheel broken at the cistern."}, {"numero": 7, "texto": "Then shall the dust return to the earth as it was: and the spirit shall return unto God who gave it."}, {"numero": 8, "texto": "Vanity of vanities, saith the preacher; all is vanity."}, {"numero": 9, "texto": "And moreover, because the preacher was wise, he still taught the people knowledge; yea, he gave good heed, and sought out, and set in order many proverbs."}, {"numero": 10, "texto": "The preacher sought to find out acceptable words: and that which was written was upright, even words of truth."}, {"numero": 11, "texto": "The words of the wise are as goads, and as nails fastened by the masters of assemblies, which are given from one shepherd."}, {"numero": 12, "texto": "And further, by these, my son, be admonished: of making many books there is no end; and much study is a weariness of the flesh."}, {"numero": 13, "texto": "Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man."}, {"numero": 14, "texto": "For God shall bring every work into judgment, with every secret thing, whether it be good, or whether it be evil."}]'::jsonb, 'King James Version'),
  ('Ec', 12, 'fr', '[{"numero": 1, "texto": "Mais souviens-toi de ton créateur pendant les jours de ta jeunesse, avant que les jours mauvais arrivent et que les années s''''approchent où tu diras: Je n''''y prends point de plaisir;"}, {"numero": 2, "texto": "avant que s''''obscurcissent le soleil et la lumière, la lune et les étoiles, et que les nuages reviennent après la pluie,"}, {"numero": 3, "texto": "temps où les gardiens de la maison tremblent, où les hommes forts se courbent, où celles qui moulent s''''arrêtent parce qu''''elles sont diminuées, où ceux qui regardent par les fenêtres sont obscurcis,"}, {"numero": 4, "texto": "où les deux battants de la porte se ferment sur la rue quand s''''abaisse le bruit de la meule, où l''''on se lève au chant de l''''oiseau, où s''''affaiblissent toutes les filles du chant,"}, {"numero": 5, "texto": "où l''''on redoute ce qui est élevé, où l''''on a des terreurs en chemin, où l''''amandier fleurit, où la sauterelle devient pesante, et où la câpre n''''a plus d''''effet, car l''''homme s''''en va vers sa demeure éternelle, et les pleureurs parcourent les rues;"}, {"numero": 6, "texto": "avant que le cordon d''''argent se détache, que le vase d''''or se brise, que le seau se rompe sur la source, et que la roue se casse sur la citerne;"}, {"numero": 7, "texto": "avant que la poussière retourne à la terre, comme elle y était, et que l''''esprit retourne à Dieu qui l''''a donné."}, {"numero": 8, "texto": "Vanité des vanités, dit l''''Ecclésiaste, tout est vanité."}, {"numero": 9, "texto": "Outre que l''''Ecclésiaste fut un sage, il a encore enseigné la science au peuple, et il a examiné, sondé, mis en ordre un grand nombre de sentences."}, {"numero": 10, "texto": "L''''Ecclésiaste s''''est efforcé de trouver des paroles agréables; et ce qui a été écrit avec droiture, ce sont des paroles de vérité."}, {"numero": 11, "texto": "Les paroles des sages sont comme des aiguillons; et, rassemblées en un recueil, elles sont comme des clous plantés, données par un seul maître."}, {"numero": 12, "texto": "Du reste, mon fils, tire instruction de ces choses; on ne finirait pas, si l''''on voulait faire un grand nombre de livres, et beaucoup d''''étude est une fatigue pour le corps."}, {"numero": 13, "texto": "Ecoutons la fin du discours: Crains Dieu et observe ses commandements. C''''est là ce que doit faire tout homme."}, {"numero": 14, "texto": "Car Dieu amènera toute oeuvre en jugement, au sujet de tout ce qui est caché, soit bien, soit mal."}]'::jsonb, 'Louis Segond 1910'),
  ('Ec', 12, 'es', '[{"numero": 1, "texto": "Y ACUÉRDATE de tu Criador en los días de tu juventud, antes que vengan los malos días, y lleguen los años, de los cuales digas, No tengo en ellos contentamiento;"}, {"numero": 2, "texto": "Antes que se oscurezca el sol, y la luz, y la luna y las estrellas, y las nubes se tornen tras la lluvia:"}, {"numero": 3, "texto": "Cuando temblarán los guardas de la casa, y se encorvarán los hombres fuertes, y cesarán las muelas, porque han disminuído, y se oscurecerán los que miran por las ventanas;"}, {"numero": 4, "texto": "Y las puertas de afuera se cerrarán, por la bajeza de la voz de la muela; y levantaráse á la voz del ave, y todas las hijas de canción serán humilladas;"}, {"numero": 5, "texto": "Cuando también temerán de lo alto, y los tropezones en el camino; y florecerá el almendro, y se agravará la langosta, y perderáse el apetito: porque el hombre va á la casa de su siglo, y los endechadores andarán en derredor por la plaza:"}, {"numero": 6, "texto": "Antes que la cadena de plata se quiebre, y se rompa el cuenco de oro, y el cántaro se quiebre junto á la fuente, y la rueda sea rota sobre el pozo;"}, {"numero": 7, "texto": "Y el polvo se torne á la tierra, como era, y el espíritu se vuelva á Dios que lo dió."}, {"numero": 8, "texto": "Vanidad de vanidades, dijo el Predicador, todo vanidad."}, {"numero": 9, "texto": "Y cuanto más sabio fué el Predicador, tanto más enseñó sabiduría al pueblo; é hizo escuchar, é hizo escudriñar, y compuso muchos proverbios."}, {"numero": 10, "texto": "Procuró el Predicador hallar palabras agradables, y escritura recta, palabras de verdad."}, {"numero": 11, "texto": "Las palabras de los sabios son como aguijones; y como clavos hincados, las de los maestros de las congregaciones, dadas por un Pastor."}, {"numero": 12, "texto": "Ahora, hijo mío, á más de esto, sé avisado. No hay fin de hacer muchos libros; y el mucho estudio aflicción es de la carne."}, {"numero": 13, "texto": "El fin de todo el discurso oído es este: Teme á Dios, y guarda sus mandamientos; porque esto es el todo del hombre."}, {"numero": 14, "texto": "Porque Dios traerá toda obra á juicio, el cual se hará sobre toda cosa oculta, buena ó mala."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ed', 1, 'pt', '[{"numero": 1, "texto": "No primeiro ano de Ciro rei da Pérsia, para que se cumprisse a palavra do SENHOR pela boca de Jeremias, o SENHOR despertou o espírito de Ciro rei da Pérsia, o qual mandou proclamar por todo o seu reino, e também por escrito, dizendo:"}, {"numero": 2, "texto": "Assim diz Ciro, rei da Pérsia: O SENHOR, Deus dos céus, me deu todos os reinos da terra; e ele me mandou que lhe edificasse uma casa em Jerusalém, que está em Judá."}, {"numero": 3, "texto": "Quem há entre vós de todo seu povo, seu Deus seja com ele, e suba a Jerusalém que está em Judá, e edifique a casa ao SENHOR Deus de Israel; ele é o Deus que [habita] em Jerusalém."}, {"numero": 4, "texto": "E todo aquele que tiver restado em qualquer lugar onde estiver morando, os homens de seu lugar o ajudem com prata, ouro, bens, e animais; além das doações voluntárias para a casa de Deus, que está em Jerusalém."}, {"numero": 5, "texto": "Então se levantaram os chefes das famílias de Judá e de Benjamim, os sacerdotes e os Levitas, e todos [aqueles] cujo espírito Deus despertou, para subirem a edificar a casa do SENHOR, que está em Jerusalém."}, {"numero": 6, "texto": "E todos os que estavam em seus arredores fortaleceram suas mãos com objetos de prata e de ouro, com bens e animais, e com coisas preciosas, além de tudo o que foi dado voluntariamente."}, {"numero": 7, "texto": "Também o rei Ciro tirou os utensílios da casa do SENHOR, que Nabucodonosor tinha trazido de Jerusalém, e posto na casa de seus deuses."}, {"numero": 8, "texto": "E Ciro, rei da Pérsia, tirou-os por meio do tesoureiro Mitridate, o qual os deu contados a Sesbazar, príncipe de Judá."}, {"numero": 9, "texto": "E esta é o seu número: trinta bacias de ouro, mil bacias de prata, vinte e nove facas,"}, {"numero": 10, "texto": "Trinta taças de ouro, quatrocentas e dez taças de prata, e mil outros utensílios."}, {"numero": 11, "texto": "Todos os utensílios de ouro e de prata foram cinco mil e quatrocentos. Sesbazar trouxe todos estes com os do cativeiro que subiram da Babilônia a Jerusalém."}]'::jsonb, 'Almeida Livre'),
  ('Ed', 1, 'en', '[{"numero": 1, "texto": "Now in the first year of Cyrus king of Persia, that the word of the Lord by the mouth of Jeremiah might be fulfilled, the Lord stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}, {"numero": 2, "texto": "Thus saith Cyrus king of Persia, The Lord God of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which is in Judah."}, {"numero": 3, "texto": "Who is there among you of all his people? his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of the Lord God of Israel, (he is the God,) which is in Jerusalem."}, {"numero": 4, "texto": "And whosoever remaineth in any place where he sojourneth, let the men of his place help him with silver, and with gold, and with goods, and with beasts, beside the freewill offering for the house of God that is in Jerusalem."}, {"numero": 5, "texto": "Then rose up the chief of the fathers of Judah and Benjamin, and the priests, and the Levites, with all them whose spirit God had raised, to go up to build the house of the Lord which is in Jerusalem."}, {"numero": 6, "texto": "And all they that were about them strengthened their hands with vessels of silver, with gold, with goods, and with beasts, and with precious things, beside all that was willingly offered."}, {"numero": 7, "texto": "Also Cyrus the king brought forth the vessels of the house of the Lord, which Nebuchadnezzar had brought forth out of Jerusalem, and had put them in the house of his gods;"}, {"numero": 8, "texto": "Even those did Cyrus king of Persia bring forth by the hand of Mithredath the treasurer, and numbered them unto Sheshbazzar, the prince of Judah."}, {"numero": 9, "texto": "And this is the number of them: thirty chargers of gold, a thousand chargers of silver, nine and twenty knives,"}, {"numero": 10, "texto": "Thirty basons of gold, silver basons of a second sort four hundred and ten, and other vessels a thousand."}, {"numero": 11, "texto": "All the vessels of gold and of silver were five thousand and four hundred. All these did Sheshbazzar bring up with them of the captivity that were brought up from Babylon unto Jerusalem."}]'::jsonb, 'King James Version'),
  ('Ed', 1, 'fr', '[{"numero": 1, "texto": "La première année de Cyrus, roi de Perse, afin que s''''accomplît la parole de l''''Eternel prononcée par la bouche de Jérémie, l''''Eternel réveilla l''''esprit de Cyrus, roi de Perse, qui fit faire de vive voix et par écrit cette publication dans tout son royaume:"}, {"numero": 2, "texto": "Ainsi parle Cyrus, roi des Perses: L''''Eternel, le Dieu des cieux, m''''a donné tous les royaumes de la terre, et il m''''a commandé de lui bâtir une maison à Jérusalem en Juda."}, {"numero": 3, "texto": "Qui d''''entre vous est de son peuple? Que son Dieu soit avec lui, et qu''''il monte à Jérusalem en Juda et bâtisse la maison de l''''Eternel, le Dieu d''''Israël! C''''est le Dieu qui est à Jérusalem."}, {"numero": 4, "texto": "Dans tout lieu où séjournent des restes du peuple de l''''Eternel, les gens du lieu leur donneront de l''''argent, de l''''or, des effets, et du bétail, avec des offrandes volontaires pour la maison de Dieu qui est à Jérusalem."}, {"numero": 5, "texto": "Les chefs de famille de Juda et de Benjamin, les sacrificateurs et les Lévites, tous ceux dont Dieu réveilla l''''esprit, se levèrent pour aller bâtir la maison de l''''Eternel à Jérusalem."}, {"numero": 6, "texto": "Tous leurs alentours leur donnèrent des objets d''''argent, de l''''or, des effets, du bétail, et des choses précieuses, outre toutes les offrandes volontaires."}, {"numero": 7, "texto": "Le roi Cyrus rendit les ustensiles de la maison de l''''Eternel, que Nebucadnetsar avait emportés de Jérusalem et placés dans la maison de son dieu."}, {"numero": 8, "texto": "Cyrus, roi de Perse, les fit sortir par Mithredath, le trésorier, qui les remit à Scheschbatsar, prince de Juda."}, {"numero": 9, "texto": "En voici le nombre: trente bassins d''''or, mille bassins d''''argent, vingt-neuf couteaux,"}, {"numero": 10, "texto": "trente coupes d''''or, quatre cent dix coupes d''''argent de second ordre, mille autres ustensiles."}, {"numero": 11, "texto": "Tous les objets d''''or et d''''argent étaient au nombre de cinq mille quatre cents. Scheschbatsar emporta le tout de Babylone à Jérusalem, au retour de la captivité."}]'::jsonb, 'Louis Segond 1910'),
  ('Ed', 1, 'es', '[{"numero": 1, "texto": "Y EN el primer año de Ciro rey de Persia, para que se cumpliese la palabra de Jehová por boca de Jeremías, excitó Jehová el espíritu de Ciro rey de Persia, el cual hizo pasar pregón por todo su reino, y también por escrito, diciendo:"}, {"numero": 2, "texto": "Así ha dicho Ciro rey de Persia: Jehová Dios de los cielos me ha dado todos los reinos de la tierra, y me ha mandado que le edifique casa en Jerusalem, que está en Judá."}, {"numero": 3, "texto": "¿Quién hay entre vosotros de todo su pueblo? Sea Dios con él, y suba á Jerusalem que está en Judá, y edifique la casa á Jehová Dios de Israel, (él es el Dios,) la cual está en Jerusalem."}, {"numero": 4, "texto": "Y á cualquiera que hubiere quedado de todos los lugares donde peregrinare, los hombres de su lugar le ayuden con plata, y oro, y hacienda, y con bestias; con dones voluntarios para la casa de Dios, la cual está en Jerusalem."}, {"numero": 5, "texto": "Entonces se levantaron los cabezas de las familias de Judá y de Benjamín, y los sacerdotes y Levitas, todos aquellos cuyo espíritu despertó Dios para subir á edificar la casa de Jehová, la cual está en Jerusalem."}, {"numero": 6, "texto": "Y todos los que estaban en sus alrededores confortaron las manos de ellos con vasos de plata y de oro, con hacienda y bestias, y con cosas preciosas, á más de lo que se ofreció voluntariamente."}, {"numero": 7, "texto": "Y el rey Ciro sacó los vasos de la casa de Jehová, que Nabucodonosor había traspasado de Jerusalem, y puesto en la casa de sus dioses."}, {"numero": 8, "texto": "Sacólos pues Ciro rey de Persia, por mano de Mitrídates tesorero, el cual los dió por cuenta á Sesbassar príncipe de Judá."}, {"numero": 9, "texto": "Y esta es la cuenta de ellos: treinta tazones de oro, mil tazones de plata, veinte y nueve cuchillos,"}, {"numero": 10, "texto": "Treinta tazas de oro, cuatrocientas y diez otras tazas de plata, y mil otros vasos."}, {"numero": 11, "texto": "Todos los vasos de oro y de plata, cinco mil y cuatrocientos. Todos los hizo llevar Sesbassar con los que subieron del cautiverio de Babilonia á Jerusalem."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ed', 3, 'pt', '[{"numero": 1, "texto": "Tendo, pois, chegado o mês sétimo, e já estando os filhos de Israel nas cidades, o povo se ajuntou como um só homem em Jerusalém."}, {"numero": 2, "texto": "E levantaram-se Jesua, filho de Jozadaque, e seus irmãos os sacerdotes, e Zorobabel filho de Sealtiel, e seus irmãos, e edificaram o altar do Deus de Israel, para oferecerem sobre ele ofertas de queima, como está escrito na Lei de Moisés, homem de Deus."}, {"numero": 3, "texto": "E assentaram o altar sobre suas bases, porém com medo sobre si, por causa dos povos das terras; e ofereceram sobre ele ofertas de queima ao SENHOR, ofertas de queima à manhã e à tarde."}, {"numero": 4, "texto": "E celebraram a festa dos tabernáculos, como está escrito; fizeram ofertas de queima diariamente conforme a regra exigida a cada dia;"}, {"numero": 5, "texto": "E depois disto, ofereceram o holocausto contínuo, assim como os as das luas novas, e todas as festas santificadas ao SENHOR, como também de qualquer um que dava oferta voluntária ao SENHOR."}, {"numero": 6, "texto": "Desde o primeiro dia do mês sétimo começaram a oferecer holocaustos ao SENHOR; porém ainda não estavam postos os fundamentos do templo do SENHOR."}, {"numero": 7, "texto": "Assim deram dinheiro aos pedreiros e carpinteiros; como também comida, bebida, e azeite aos sidônios e aos tírios, para que trazerem do Líbano madeira de cedro ao mar de Jope, conforme a autorização de Ciro, rei da Pérsia, acerca disto."}, {"numero": 8, "texto": "E no ano segundo de sua vinda à casa de Deus em Jerusalém, no mês segundo, começaram Zorobabel, filho de Sealtiel, Jesua, filho de Jozadaque, com os outros irmãos seus, os sacerdotes e os levitas, e todos os que haviam vindo do cativeiro a Jerusalém. E ordenaram aos levitas da idade de vinte anos acima, que cuidassem da casa do SENHOR."}, {"numero": 9, "texto": "Então Jesua, seus filhos e seus irmãos, Cadmiel e seus filhos, filhos de Judá, se levantaram como um só homem para supervisionarem os que faziam a obra na casa de Deus; [com] os filhos de Henadade, seus filhos e seus irmãos, levitas."}, {"numero": 10, "texto": "E quando os construtores do templo do SENHOR puseram os fundamentos, então ordenaram aos sacerdotes, já com as vestimentas e com trombetas, e aos levitas filhos de Asafe com címbalos, para louvarem ao SENHOR, conforme a ordenança de Davi, rei de Israel."}, {"numero": 11, "texto": "E cantavam em revezamento, louvando e celebrando ao SENHOR:Porque ele é bom, porque sua bondade sobre Israel dura para sempre!E todo o povo gritava com grande júbilo, louvando ao SENHOR, por causa da fundação da casa do SENHOR."}, {"numero": 12, "texto": "Porém muitos dos sacerdotes e dos levitas e dos chefes de famílias, já velhos, que haviam visto a primeira casa, quando viram a fundação desta casa, choravam em alta voz, mas muitos outros davam grandes gritos de alegria;"}, {"numero": 13, "texto": "De maneira que o povo não conseguia distinguir as vozes de alegria das vozes de choro do povo; porque o povo gritava com tão grande júbilo, que se podia ouvir o som de muito longe."}]'::jsonb, 'Almeida Livre'),
  ('Ed', 3, 'en', '[{"numero": 1, "texto": "And when the seventh month was come, and the children of Israel were in the cities, the people gathered themselves together as one man to Jerusalem."}, {"numero": 2, "texto": "Then stood up Jeshua the son of Jozadak, and his brethren the priests, and Zerubbabel the son of Shealtiel, and his brethren, and builded the altar of the God of Israel, to offer burnt offerings thereon, as it is written in the law of Moses the man of God."}, {"numero": 3, "texto": "And they set the altar upon his bases; for fear was upon them because of the people of those countries: and they offered burnt offerings thereon unto the Lord, even burnt offerings morning and evening."}, {"numero": 4, "texto": "They kept also the feast of tabernacles, as it is written, and offered the daily burnt offerings by number, according to the custom, as the duty of every day required;"}, {"numero": 5, "texto": "And afterward offered the continual burnt offering, both of the new moons, and of all the set feasts of the Lord that were consecrated, and of every one that willingly offered a freewill offering unto the Lord."}, {"numero": 6, "texto": "From the first day of the seventh month began they to offer burnt offerings unto the Lord. But the foundation of the temple of the Lord was not yet laid."}, {"numero": 7, "texto": "They gave money also unto the masons, and to the carpenters; and meat, and drink, and oil, unto them of Zidon, and to them of Tyre, to bring cedar trees from Lebanon to the sea of Joppa, according to the grant that they had of Cyrus king of Persia."}, {"numero": 8, "texto": "Now in the second year of their coming unto the house of God at Jerusalem, in the second month, began Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and the remnant of their brethren the priests and the Levites, and all they that were come out of the captivity unto Jerusalem; and appointed the Levites, from twenty years old and upward, to set forward the work of the house of the Lord."}, {"numero": 9, "texto": "Then stood Jeshua with his sons and his brethren, Kadmiel and his sons, the sons of Judah, together, to set forward the workmen in the house of God: the sons of Henadad, with their sons and their brethren the Levites."}, {"numero": 10, "texto": "And when the builders laid the foundation of the temple of the Lord, they set the priests in their apparel with trumpets, and the Levites the sons of Asaph with cymbals, to praise the Lord, after the ordinance of David king of Israel."}, {"numero": 11, "texto": "And they sang together by course in praising and giving thanks unto the Lord; because he is good, for his mercy endureth for ever toward Israel. And all the people shouted with a great shout, when they praised the Lord, because the foundation of the house of the Lord was laid."}, {"numero": 12, "texto": "But many of the priests and Levites and chief of the fathers, who were ancient men, that had seen the first house, when the foundation of this house was laid before their eyes, wept with a loud voice; and many shouted aloud for joy:"}, {"numero": 13, "texto": "So that the people could not discern the noise of the shout of joy from the noise of the weeping of the people: for the people shouted with a loud shout, and the noise was heard afar off."}]'::jsonb, 'King James Version'),
  ('Ed', 3, 'fr', '[{"numero": 1, "texto": "Le septième mois arriva, et les enfants d''''Israël étaient dans leurs villes. Alors le peuple s''''assembla comme un seul homme à Jérusalem."}, {"numero": 2, "texto": "Josué, fils de Jotsadak, avec ses frères les sacrificateurs, et Zorobabel, fils de Schealthiel, avec ses frères, se levèrent et bâtirent l''''autel du Dieu d''''Israël, pour y offrir des holocaustes, selon ce qui est écrit dans la loi de Moïse, homme de Dieu."}, {"numero": 3, "texto": "Ils rétablirent l''''autel sur ses fondements, quoiqu''''ils eussent à craindre les peuples du pays, et ils y offrirent des holocaustes à l''''Eternel, les holocaustes du matin et du soir."}, {"numero": 4, "texto": "Ils célébrèrent la fête des tabernacles, comme il est écrit, et ils offrirent jour par jour des holocaustes, selon le nombre ordonné pour chaque jour."}, {"numero": 5, "texto": "Après cela, ils offrirent l''''holocauste perpétuel, les holocaustes des nouvelles lunes et de toutes les solennités consacrées à l''''Eternel, et ceux de quiconque faisait des offrandes volontaires à l''''Eternel."}, {"numero": 6, "texto": "Dès le premier jour du septième mois, ils commencèrent à offrir à l''''Eternel des holocaustes. Cependant les fondements du temple de l''''Eternel n''''étaient pas encore posés."}, {"numero": 7, "texto": "On donna de l''''argent aux tailleurs de pierres et aux charpentiers, et des vivres, des boissons et de l''''huile aux Sidoniens et aux Tyriens, pour qu''''ils amenassent par mer jusqu''''à Japho des bois de cèdre du Liban, suivant l''''autorisation qu''''on avait eue de Cyrus, roi de Perse."}, {"numero": 8, "texto": "La seconde année depuis leur arrivée à la maison de Dieu à Jérusalem, au second mois, Zorobabel, fils de Schealthiel, Josué, fils de Jotsadak, avec le reste de leurs frères les sacrificateurs et les Lévites, et tous ceux qui étaient revenus de la captivité à Jérusalem, se mirent à l''''oeuvre et chargèrent les Lévites de vingt ans et au-dessus de surveiller les travaux de la maison de l''''Eternel."}, {"numero": 9, "texto": "Et Josué, avec ses fils et ses frères, Kadmiel, avec ses fils, fils de Juda, les fils de Hénadad, avec leurs fils et leurs frères les Lévites, se préparèrent tous ensemble à surveiller ceux qui travaillaient à la maison de Dieu."}, {"numero": 10, "texto": "Lorsque les ouvriers posèrent les fondements du temple de l''''Eternel, on fit assister les sacrificateurs en costume, avec les trompettes, et les Lévites, fils d''''Asaph, avec les cymbales, afin qu''''ils célébrassent l''''Eternel, d''''après les ordonnances de David, roi d''''Israël."}, {"numero": 11, "texto": "Ils chantaient, célébrant et louant l''''Eternel par ces paroles: Car il est bon, car sa miséricorde pour Israël dure à toujours! Et tout le peuple poussait de grands cris de joie en célébrant l''''Eternel, parce qu''''on posait les fondements de la maison de l''''Eternel."}, {"numero": 12, "texto": "Mais plusieurs des sacrificateurs et des Lévites, et des chefs de famille âgés, qui avaient vu la première maison, pleuraient à grand bruit pendant qu''''on posait sous leurs yeux les fondements de cette maison. Beaucoup d''''autres faisaient éclater leur joie par des cris,"}, {"numero": 13, "texto": "en sorte qu''''on ne pouvait distinguer le bruit des cris de joie d''''avec le bruit des pleurs parmi le peuple, car le peuple poussait de grands cris dont le son s''''entendait au loin."}]'::jsonb, 'Louis Segond 1910'),
  ('Ed', 3, 'es', '[{"numero": 1, "texto": "Y LLEGADO el mes séptimo, y ya los hijos de Israel en las ciudades, juntóse el pueblo como un solo hombre en Jerusalem."}, {"numero": 2, "texto": "Entonces se levantó Jesuá hijo de Josadec, y sus hermanos los sacerdotes, y Zorobabel hijo de Sealthiel, y sus hermanos, y edificaron el altar del Dios de Israel, para ofrecer sobre él holocaustos, como está escrito en la ley de Moisés varón de Dios."}, {"numero": 3, "texto": "Y asentaron el altar sobre sus basas, bien que tenían miedo de los pueblos de las tierras, y ofrecieron sobre él holocaustos á Jehová, holocaustos á la mañana y á la tarde."}, {"numero": 4, "texto": "Hicieron asimismo la solemnidad de las cabañas, como está escrito, y holocaustos cada día por cuenta, conforme al rito, cada cosa en su día;"}, {"numero": 5, "texto": "Y á más de esto, el holocausto continuo, y las nuevas lunas, y todas las fiestas santificadas de Jehová, y todo sacrificio espontáneo, toda ofrenda voluntaria á Jehová."}, {"numero": 6, "texto": "Desde el primer día del mes séptimo comenzaron á ofrecer holocaustos á Jehová; mas el templo de Jehová no estaba aún fundado."}, {"numero": 7, "texto": "Y dieron dinero á los carpinteros y oficiales; asimismo comida y bebida y aceite á los Sidonios y Tirios, para que trajesen madera de cedro del Líbano á la mar de Joppe, conforme á la voluntad de Ciro rey de Persia acerca de esto."}, {"numero": 8, "texto": "Y en el año segundo de su venida á la casa de Dios en Jerusalem, en el mes segundo, comenzaron Zorobabel hijo de Sealthiel, y Jesuá hijo de Josadec, y los otros sus hermanos, los sacerdotes y los Levitas, y todos los que habían venido de la cautividad á Jerusalem; y pusieron á los Levitas de veinte años arriba para que tuviesen cargo de la obra de la casa de Jehová."}, {"numero": 9, "texto": "Jesuá también, sus hijos y sus hermanos, Cadmiel y sus hijos, hijos de Judá, como un solo hombre asistían para dar priesa á los que hacían la obra en la casa de Dios: los hijos de Henadad, sus hijos y sus hermanos, Levitas."}, {"numero": 10, "texto": "Y cuando los albañiles del templo de Jehová echaban los cimientos, pusieron á los sacerdotes vestidos de sus ropas, con trompetas, y á Levitas hijos de Asaph con címbalos, para que alabasen á Jehová, según ordenanza de David rey de Israel."}, {"numero": 11, "texto": "Y cantaban, alabando y confesando á Jehová, y decían: Porque es bueno, porque para siempre es su misericordia sobre Israel. Y todo el pueblo aclamaba con grande júbilo, alabando á Jehová, porque á la casa de Jehová se echaba el cimiento."}, {"numero": 12, "texto": "Y muchos de los sacerdotes y de los Levitas y de los cabezas de los padres, ancianos que habían visto la casa primera, viendo fundar esta casa, lloraban en alta voz, mientras muchos otros daban grandes gritos de alegría."}, {"numero": 13, "texto": "Y no podía discernir el pueblo el clamor de los gritos de alegría, de la voz del lloro del pueblo: porque clamaba el pueblo con grande júbilo, y oíase el ruido hasta de lejos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ed', 4, 'pt', '[{"numero": 1, "texto": "Quando, pois, os adversários de Judá e de Benjamim, ouviram que os que tinham vindo do cativeiro estavam edificando o templo ao SENHOR, Deus de Israel,"}, {"numero": 2, "texto": "chegaram-se a Zorobabel, e aos chefes das famílias, e lhes disseram: Deixai-nos edificar convosco, porque assim como vós, buscaremos ao vosso Deus, como também já sacrificamos a ele desde os dias de Esar-Hadom, rei da Assíria, que nos fez subir até aqui."}, {"numero": 3, "texto": "Porém Zorobabel, Jesua, e os demais chefes das famílias de Israel lhes disseram: Não nos convém edificar convosco casa a nosso Deus; mas somente nós a edificaremos ao SENHOR, Deus de Israel, como nos mandou o rei Ciro, rei da Pérsia."}, {"numero": 4, "texto": "Todavia o povo da terra desencorajava o povo de Judá, e os perturbava, para que não edificassem."}, {"numero": 5, "texto": "E subornaram contra eles conselheiros para frustrarem sua intenção, todos os dias de Ciro rei da Pérsia, e até o reinado de Dario, rei da Pérsia."}, {"numero": 6, "texto": "E sob o reinado de Assuero, no princípio de seu reinado, escreveram uma acusação contra os moradores de Judá e de Jerusalém."}, {"numero": 7, "texto": "E nos dias de Artaxerxes, Bislão, Mitridate, Tabeel, e os demais seus companheiros, escreveram a Artaxerxes rei da Pérsia; e o escrito da carta estava feito em siríaco, e composto em siríaco."}, {"numero": 8, "texto": "Reum o comandante, e Sinsai o escrivão, escreveram uma carta contra Jerusalém ao rei Artaxerxes, conforme o seguinte:"}, {"numero": 9, "texto": "Reum, o comandante, e Sinsai secretário, e os demais seus companheiros, os dinaítas, os arfasaquitas, tarpelitas, arfasitas, os arquevitas, os babilônios, susanquitas, deavitas, e elamitas;"}, {"numero": 10, "texto": "E os demais povos que o grande e famoso Asnapar transportou, e fez habitar nas cidades de Samaria, e os demais da região dalém do rio."}, {"numero": 11, "texto": "Este é o teor da carta que enviaram: Ao rei Artaxerxes. De teus servos dalém do rio."}, {"numero": 12, "texto": "Seja conhecido do rei que os judeus que subiram de ti a nós, vieram a Jerusalém; e edificam aquela cidade rebelde e má, e estão restaurando [seus] muros; e reparado [seus] fundamentos."}, {"numero": 13, "texto": "Seja agora conhecido do rei, que se aquela cidade for reconstruída, e os muros forem restaurados, os tributos, taxas, e impostos não serão pagos, e o patrimônio real será prejudicado."}, {"numero": 14, "texto": "Visto que somos assalariados pelo palácio, não nos convém ver a desonra do rei; por isso mandamos informar ao rei;"}, {"numero": 15, "texto": "Para que se busque no livro das crônicas de teus pais; e acharás no livro das crônicas, e saberás que aquela cidade foi uma cidade rebelde, prejudicial aos reis e às províncias, e que nela desde antigamente fizeram rebeliões; por isso aquela cidade foi arruinada."}, {"numero": 16, "texto": "Por isso informamos ao rei que, se aquela cidade for reconstruída, e seus muros restaurados, a parte além do rio não será tua."}, {"numero": 17, "texto": "[Então] o rei enviou [esta] resposta a Reum, o comandante, e a Sinsai, o escrivão, e aos demais de seus companheiros que habitam em Samaria, como também aos demais da parte além do rio: Paz."}, {"numero": 18, "texto": "A carta que nos enviastes foi lida claramente diante de mim."}, {"numero": 19, "texto": "E eu dei ordem para que se buscasse; e encontraram que aquela cidade na antiguidade se levantou contra os reis, e nela houve rebelião e insurreição."}, {"numero": 20, "texto": "E que houve reis poderosos em Jerusalém, dominaram toda a região além do rio; e a eles se pagava tributos, taxas e impostos."}, {"numero": 21, "texto": "Agora, pois, dai ordem que impeçam aqueles homens, e aquela cidade não seja reconstruída, até que seja dado mandamento de minha parte."}, {"numero": 22, "texto": "E sede cuidadosos para que não falheis nisto; por que haveria de aumentar o dano para o prejuízo real?"}, {"numero": 23, "texto": "Assim que o teor da carta do rei Artaxerxes foi lido diante de Reum, e de Sinsai o escrivão, e seus companheiros, eles foram apressadamente a Jerusalém aos judeus, e os impediram com força e violência."}, {"numero": 24, "texto": "Cessou, então, a obra da casa de Deus, a qual estava em Jerusalém; e cessou até o segundo ano do reinado de Dario, rei da Pérsia."}]'::jsonb, 'Almeida Livre'),
  ('Ed', 4, 'en', '[{"numero": 1, "texto": "Now when the adversaries of Judah and Benjamin heard that the children of the captivity builded the temple unto the Lord God of Israel;"}, {"numero": 2, "texto": "Then they came to Zerubbabel, and to the chief of the fathers, and said unto them, Let us build with you: for we seek your God, as ye do; and we do sacrifice unto him since the days of Esarhaddon king of Assur, which brought us up hither."}, {"numero": 3, "texto": "But Zerubbabel, and Jeshua, and the rest of the chief of the fathers of Israel, said unto them, Ye have nothing to do with us to build an house unto our God; but we ourselves together will build unto the Lord God of Israel, as king Cyrus the king of Persia hath commanded us."}, {"numero": 4, "texto": "Then the people of the land weakened the hands of the people of Judah, and troubled them in building,"}, {"numero": 5, "texto": "And hired counsellors against them, to frustrate their purpose, all the days of Cyrus king of Persia, even until the reign of Darius king of Persia."}, {"numero": 6, "texto": "And in the reign of Ahasuerus, in the beginning of his reign, wrote they unto him an accusation against the inhabitants of Judah and Jerusalem."}, {"numero": 7, "texto": "And in the days of Artaxerxes wrote Bishlam, Mithredath, Tabeel, and the rest of their companions, unto Artaxerxes king of Persia; and the writing of the letter was written in the Syrian tongue, and interpreted in the Syrian tongue."}, {"numero": 8, "texto": "Rehum the chancellor and Shimshai the scribe wrote a letter against Jerusalem to Artaxerxes the king in this sort:"}, {"numero": 9, "texto": "Then wrote Rehum the chancellor, and Shimshai the scribe, and the rest of their companions; the Dinaites, the Apharsathchites, the Tarpelites, the Apharsites, the Archevites, the Babylonians, the Susanchites, the Dehavites, and the Elamites,"}, {"numero": 10, "texto": "And the rest of the nations whom the great and noble Asnapper brought over, and set in the cities of Samaria, and the rest that are on this side the river, and at such a time."}, {"numero": 11, "texto": "This is the copy of the letter that they sent unto him, even unto Artaxerxes the king; Thy servants the men on this side the river, and at such a time."}, {"numero": 12, "texto": "Be it known unto the king, that the Jews which came up from thee to us are come unto Jerusalem, building the rebellious and the bad city, and have set up the walls thereof, and joined the foundations."}, {"numero": 13, "texto": "Be it known now unto the king, that, if this city be builded, and the walls set up again, then will they not pay toll, tribute, and custom, and so thou shalt endamage the revenue of the kings."}, {"numero": 14, "texto": "Now because we have maintenance from the king''s palace, and it was not meet for us to see the king''s dishonour, therefore have we sent and certified the king;"}, {"numero": 15, "texto": "That search may be made in the book of the records of thy fathers: so shalt thou find in the book of the records, and know that this city is a rebellious city, and hurtful unto kings and provinces, and that they have moved sedition within the same of old time: for which cause was this city destroyed."}, {"numero": 16, "texto": "We certify the king that, if this city be builded again, and the walls thereof set up, by this means thou shalt have no portion on this side the river."}, {"numero": 17, "texto": "Then sent the king an answer unto Rehum the chancellor, and to Shimshai the scribe, and to the rest of their companions that dwell in Samaria, and unto the rest beyond the river, Peace, and at such a time."}, {"numero": 18, "texto": "The letter which ye sent unto us hath been plainly read before me."}, {"numero": 19, "texto": "And I commanded, and search hath been made, and it is found that this city of old time hath made insurrection against kings, and that rebellion and sedition have been made therein."}, {"numero": 20, "texto": "There have been mighty kings also over Jerusalem, which have ruled over all countries beyond the river; and toll, tribute, and custom, was paid unto them."}, {"numero": 21, "texto": "Give ye now commandment to cause these men to cease, and that this city be not builded, until another commandment shall be given from me."}, {"numero": 22, "texto": "Take heed now that ye fail not to do this: why should damage grow to the hurt of the kings?"}, {"numero": 23, "texto": "Now when the copy of king Artaxerxes'' letter was read before Rehum, and Shimshai the scribe, and their companions, they went up in haste to Jerusalem unto the Jews, and made them to cease by force and power."}, {"numero": 24, "texto": "Then ceased the work of the house of God which is at Jerusalem. So it ceased unto the second year of the reign of Darius king of Persia."}]'::jsonb, 'King James Version'),
  ('Ed', 4, 'fr', '[{"numero": 1, "texto": "Les ennemis de Juda et de Benjamin apprirent que les fils de la captivité bâtissaient un temple à l''''Eternel, le Dieu d''''Israël."}, {"numero": 2, "texto": "Ils vinrent auprès de Zorobabel et des chefs de familles, et leur dirent: Nous bâtirons avec vous; car, comme vous, nous invoquons votre Dieu, et nous lui offrons des sacrifices depuis le temps d''''Esar-Haddon, roi d''''Assyrie, qui nous a fait monter ici."}, {"numero": 3, "texto": "Mais Zorobabel, Josué, et les autres chefs des familles d''''Israël, leur répondirent: Ce n''''est pas à vous et à nous de bâtir la maison de notre Dieu; nous la bâtirons nous seuls à l''''Eternel, le Dieu d''''Israël, comme nous l''''a ordonné le roi Cyrus, roi de Perse."}, {"numero": 4, "texto": "Alors les gens du pays découragèrent le peuple de Juda; ils l''''intimidèrent pour l''''empêcher de bâtir,"}, {"numero": 5, "texto": "et ils gagnèrent à prix d''''argent des conseillers pour faire échouer son entreprise. Il en fut ainsi pendant toute la vie de Cyrus, roi de Perse, et jusqu''''au règne de Darius, roi de Perse."}, {"numero": 6, "texto": "Sous le règne d''''Assuérus, au commencement de son règne, ils écrivirent une accusation contre les habitants de Juda et de Jérusalem."}, {"numero": 7, "texto": "Et du temps d''''Artaxerxès, Bischlam, Mithredath, Thabeel, et le reste de leurs collègues, écrivirent à Artaxerxès, roi de Perse. La lettre fut transcrite en caractères araméens et traduite en araméen."}, {"numero": 8, "texto": "Rehum, gouverneur, et Schimschaï, secrétaire écrivirent au roi Artaxerxès la lettre suivante concernant Jérusalem:"}, {"numero": 9, "texto": "Rehum, gouverneur, Schimschaï, secrétaire, et le reste de leurs collègues, ceux de Din, d''''Arpharsathac, de Tharpel, d''''Apharas, d''''Erec, de Babylone, de Suse, de Déha, d''''Elam,"}, {"numero": 10, "texto": "et les autres peuples que le grand et illustre Osnappar a transportés et établis dans la ville de Samarie et autres lieux de ce côté du fleuve, etc."}, {"numero": 11, "texto": "C''''est ici la copie de la lettre qu''''ils envoyèrent au roi Artaxerxès: Tes serviteurs, les gens de ce côté du fleuve, etc."}, {"numero": 12, "texto": "Que le roi sache que les Juifs partis de chez toi et arrivés parmi nous à Jérusalem rebâtissent la ville rebelle et méchante, en relèvent les murs et en restaurent les fondements."}, {"numero": 13, "texto": "Que le roi sache donc que, si cette ville est rebâtie et si ses murs sont relevés, ils ne paieront ni tribut, ni impôt, ni droit de passage, et que le trésor royal en souffrira."}, {"numero": 14, "texto": "Or, comme nous mangeons le sel du palais et qu''''il ne nous paraît pas convenable de voir mépriser le roi, nous envoyons au roi ces informations."}, {"numero": 15, "texto": "Qu''''on fasse des recherches dans le livre des mémoires de tes pères; et tu trouveras et verras dans le livre des mémoires que cette ville est une ville rebelle, funeste aux rois et aux provinces, et qu''''on s''''y est livré à la révolte dès les temps anciens. C''''est pourquoi cette ville a été détruite."}, {"numero": 16, "texto": "Nous faisons savoir au roi que, si cette ville est rebâtie et si ses murs sont relevés, par cela même tu n''''auras plus de possession de ce côté du fleuve."}, {"numero": 17, "texto": "Réponse envoyée par le roi à Rehum, gouverneur, à Schimschaï, secrétaire, et au reste de leurs collègues, demeurant à Samarie et autres lieux de l''''autre côté du fleuve: Salut, etc."}, {"numero": 18, "texto": "La lettre que vous nous avez envoyée a été lue exactement devant moi."}, {"numero": 19, "texto": "J''''ai donné ordre de faire des recherches; et l''''on a trouvé que dès les temps anciens cette ville s''''est soulevée contre les rois, et qu''''on s''''y est livré à la sédition et à la révolte."}, {"numero": 20, "texto": "Il y eut à Jérusalem des rois puissants, maîtres de tout le pays de l''''autre côté du fleuve, et auxquels on payait tribut, impôt, et droit de passage."}, {"numero": 21, "texto": "En conséquence, ordonnez de faire cesser les travaux de ces gens, afin que cette ville ne se rebâtisse point avant une autorisation de ma part."}, {"numero": 22, "texto": "Gardez-vous de mettre en cela de la négligence, de peur que le mal n''''augmente au préjudice des rois."}, {"numero": 23, "texto": "Aussitôt que la copie de la lettre du roi Artaxerxès eut été lue devant Rehum, Schimschaï, le secrétaire, et leurs collègues, ils allèrent en hâte à Jérusalem vers les Juifs, et firent cesser leurs travaux par violence et par force."}, {"numero": 24, "texto": "Alors s''''arrêta l''''ouvrage de la maison de Dieu à Jérusalem, et il fut interrompu jusqu''''à la seconde année du règne de Darius, roi de Perse."}]'::jsonb, 'Louis Segond 1910'),
  ('Ed', 4, 'es', '[{"numero": 1, "texto": "Y OYENDO los enemigos de Judá y de Benjamín, que los venidos de la cautividad edificaban el templo de Jehová Dios de Israel,"}, {"numero": 2, "texto": "Llegáronse á Zorobabel, y á los cabezas de los padres, y dijéronles: Edificaremos con vosotros, porque como vosotros buscaremos á vuestro Dios, y á él sacrificamos desde los días de Esar-haddón rey de Asiria, que nos hizo subir aquí."}, {"numero": 3, "texto": "Y díjoles Zorobabel, y Jesuá, y los demás cabezas de los padres de Israel: No nos conviene edificar con vosotros casa á nuestro Dios, sino que nosotros solos la edificaremos á Jehová Dios de Israel, como nos mandó el rey Ciro, rey de Persia."}, {"numero": 4, "texto": "Mas el pueblo de la tierra debilitaba las manos del pueblo de Judá, y los arredraban de edificar."}, {"numero": 5, "texto": "Cohecharon además contra ellos consejeros para disipar su consejo, todo el tiempo de Ciro rey de Persia, y hasta el reinado de Darío rey de Persia."}, {"numero": 6, "texto": "Y en el reinado de Assuero, en el principio de su reinado, escribieron acusaciones contra los moradores de Judá y de Jerusalem."}, {"numero": 7, "texto": "Y en días de Artajerjes, Bislam, Mitrídates, Tabeel, y los demás sus compañeros, escribieron á Artajerjes rey de Persia; y la escritura de la carta estaba hecha en siriaco, y declarada en siriaco."}, {"numero": 8, "texto": "Rehum canciller, y Simsai secretario, escribieron una carta contra Jerusalem al rey Artajerjes, como se sigue."}, {"numero": 9, "texto": "Entonces Rehum canciller, y Simsai secretario, y los demás sus compañeros, los Dineos, y los Apharsathachêos, Thepharleos, Apharseos, los Erchûeos, los Babilonios, Susanchêos, Dieveos, y Elamitas;"}, {"numero": 10, "texto": "Y los demás pueblos que el grande y glorioso Asnappar trasportó, é hizo habitar en las ciudades de Samaria, y los demás de la otra parte del río, etcétera, escribieron."}, {"numero": 11, "texto": "Este es el traslado de la carta que enviaron: Al rey Artajerjes: Tus siervos de la otra parte del río, etcétera."}, {"numero": 12, "texto": "Sea notorio al rey, que los Judíos que subieron de ti á nosotros, vinieron á Jerusalem; y edifican la ciudad rebelde y mala, y han erigido los muros; y compuesto los fundamentos."}, {"numero": 13, "texto": "Ahora, notorio sea al rey, que si aquella ciudad fuere reedificada, y los muros fueren establecidos, el tributo, pecho, y rentas no darán, y el catastro de lo reyes será menoscabado."}, {"numero": 14, "texto": "Ya pues que estamos mantenidos de palacio, no nos es justo ver el menosprecio del rey: hemos enviado por tanto, y hécholo saber al rey,"}, {"numero": 15, "texto": "Para que busque en el libro de las historias de nuestros padres; y hallarás en el libro de las historias, y sabrás que esta ciudad es ciudad rebelde, y perjudicial á los reyes y á las provincias, y que de tiempo antiguo forman en medio de ella rebeliones; por lo que esta ciudad fué destruída."}, {"numero": 16, "texto": "Hacemos saber al rey, que si esta ciudad fuere edificada, y erigidos sus muros, la parte allá del río no será tuya."}, {"numero": 17, "texto": "El rey envió esta respuesta á Rehum canciller, y á Simsai secretario, y á los demás sus compañeros que habitan en Samaria, y á los demás de la parte allá del río: Paz, etc."}, {"numero": 18, "texto": "La carta que nos enviasteis claramente fué leída delante de mí."}, {"numero": 19, "texto": "Y por mí fué dado mandamiento, y buscaron, y hallaron que aquella ciudad de tiempo antiguo se levanta contra los reyes, y se rebela, y se forma en ella sedición:"}, {"numero": 20, "texto": "Y que reyes fuertes hubo en Jerusalem, quienes señorearon en todo lo que está á la parte allá del río; y que tributo, y pecho, y rentas se les daba."}, {"numero": 21, "texto": "Ahora pues dad orden que cesen aquellos hombres, y no sea esa ciudad edificada, hasta que por mí sea dado mandamiento."}, {"numero": 22, "texto": "Y mirad bien que no hagáis error en esto: ¿por qué habrá de crecer el daño para perjuicio de los reyes?"}, {"numero": 23, "texto": "Entonces, cuando el traslado de la carta del rey Artajerjes fué leído delante de Rehum, y de Simsai secretario, y sus compañeros, fueron prestamente á Jerusalem á los Judíos, é hiciéronles cesar con poder y fuerza."}, {"numero": 24, "texto": "Cesó entonces la obra de la casa de Dios, la cual estaba en Jerusalem: y cesó hasta el año segundo del reinado de Darío rey de Persia."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ed', 5, 'pt', '[{"numero": 1, "texto": "E o profeta Ageu, e Zacarias filho de Ido, profetas, profetizaram aos judeus que estavam em Judá e em Jerusalém, em nome do Deus de Israel, a eles."}, {"numero": 2, "texto": "Então se levantaram Zorobabel, filho de Sealtiel, e Jesua, filho de Jozadaque; e começaram a reconstruir a casa de Deus que está em Jerusalém; e com eles os profetas de Deus, que os ajudavam."}, {"numero": 3, "texto": "Naquele tempo veio a eles Tatenai, capitão da região além do rio, e Setar-Bozenai e seus companheiros, e lhes perguntaram assim:Quem vos deu ordem para reconstruir esta casa, e restaurar estes muros?"}, {"numero": 4, "texto": "Então assim lhes dissemos quais eram os nomes dos homens que reconstruíam este edifício."}, {"numero": 5, "texto": "Mas os olhos de seu Deus estavam sobre os anciãos dos judeus, e não os impediram, até que a causa viesse a Dario; e então responderam por carta sobre isso."}, {"numero": 6, "texto": "Teor da carta que Tatenai, o governador além do rio, e Setar-Bozenai, e seus companheiros os afarsaquitas, que estavam além do rio, enviaram ao rei Dario."}, {"numero": 7, "texto": "Enviaram-lhe uma carta, e assim estava escrito nela: Toda a paz ao rei Dario."}, {"numero": 8, "texto": "Seja conhecido do rei, que fomos à província de Judeia, à casa do grande Deus, a qual é edificada com grandes pedras; e a madeira é posta nas paredes, e a obra se faz apressadamente, e tem sido próspera a em suas mãos."}, {"numero": 9, "texto": "Então perguntamos aos anciãos, dizendo-lhes assim: Quem vos deu ordem para reconstruir esta casa, e para restaurar estes muros?"}, {"numero": 10, "texto": "E também lhes perguntamos seus nomes para os informar a ti; para que pudéssemos escrever a ti os nomes dos homens que eram os seus líderes."}, {"numero": 11, "texto": "E nos deram esta resposta, dizendo: Nós somos servos de Deus do céu e da terra, e reconstruímos a casa que a muitos anos antes tinha sido construída, a qual um grande rei de Israel iniciou e terminou de construir."}, {"numero": 12, "texto": "Mas depois que nossos pais provocaram à ira o Deus dos céus, ele os entregou nas mãos de Nabucodonosor, rei de Babilônia, o caldeu, o qual destruiu esta casa, e transportou o povo para a Babilônia."}, {"numero": 13, "texto": "Porém no primeiro ano de Ciro, rei da Babilônia, o rei Ciro fez um decreto para reconstruir esta casa de Deus."}, {"numero": 14, "texto": "E até os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tinha tomado do templo que estava em Jerusalém, e os tinha posto no templo da Babilônia, o rei Ciro os tirou do templo da Babilônia, e foram entregues a um chamado Sesbazar, a quem pusera por governador."}, {"numero": 15, "texto": "E disse-lhe: Toma estes utensílios, vai, [e] põe-os no templo que está em Jerusalém; e seja reconstruída a casa de Deus em seu lugar."}, {"numero": 16, "texto": "Então este Sesbazar veio, e pôs os fundamentos da casa de Deus, que está em Jerusalém, e desde então até agora foi reconstruída, e ainda não foi terminada."}, {"numero": 17, "texto": "Agora, pois, se for do agrado do rei, busque-se na casa dos tesouros do rei que está ali na Babilônia, se é [verdade] que rei Ciro foi feito decreto para reconstruir esta casa de Deus em Jerusalém, e seja nos enviada a vontade do rei acerca disto."}]'::jsonb, 'Almeida Livre'),
  ('Ed', 5, 'en', '[{"numero": 1, "texto": "Then the prophets, Haggai the prophet, and Zechariah the son of Iddo, prophesied unto the Jews that were in Judah and Jerusalem in the name of the God of Israel, even unto them."}, {"numero": 2, "texto": "Then rose up Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and began to build the house of God which is at Jerusalem: and with them were the prophets of God helping them."}, {"numero": 3, "texto": "At the same time came to them Tatnai, governor on this side the river, and Shetharboznai and their companions, and said thus unto them, Who hath commanded you to build this house, and to make up this wall?"}, {"numero": 4, "texto": "Then said we unto them after this manner, What are the names of the men that make this building?"}, {"numero": 5, "texto": "But the eye of their God was upon the elders of the Jews, that they could not cause them to cease, till the matter came to Darius: and then they returned answer by letter concerning this matter."}, {"numero": 6, "texto": "The copy of the letter that Tatnai, governor on this side the river, and Shetharboznai and his companions the Apharsachites, which were on this side the river, sent unto Darius the king:"}, {"numero": 7, "texto": "They sent a letter unto him, wherein was written thus; Unto Darius the king, all peace."}, {"numero": 8, "texto": "Be it known unto the king, that we went into the province of Judea, to the house of the great God, which is builded with great stones, and timber is laid in the walls, and this work goeth fast on, and prospereth in their hands."}, {"numero": 9, "texto": "Then asked we those elders, and said unto them thus, Who commanded you to build this house, and to make up these walls?"}, {"numero": 10, "texto": "We asked their names also, to certify thee, that we might write the names of the men that were the chief of them."}, {"numero": 11, "texto": "And thus they returned us answer, saying, We are the servants of the God of heaven and earth, and build the house that was builded these many years ago, which a great king of Israel builded and set up."}, {"numero": 12, "texto": "But after that our fathers had provoked the God of heaven unto wrath, he gave them into the hand of Nebuchadnezzar the king of Babylon, the Chaldean, who destroyed this house, and carried the people away into Babylon."}, {"numero": 13, "texto": "But in the first year of Cyrus the king of Babylon the same king Cyrus made a decree to build this house of God."}, {"numero": 14, "texto": "And the vessels also of gold and silver of the house of God, which Nebuchadnezzar took out of the temple that was in Jerusalem, and brought them into the temple of Babylon, those did Cyrus the king take out of the temple of Babylon, and they were delivered unto one, whose name was Sheshbazzar, whom he had made governor;"}, {"numero": 15, "texto": "And said unto him, Take these vessels, go, carry them into the temple that is in Jerusalem, and let the house of God be builded in his place."}, {"numero": 16, "texto": "Then came the same Sheshbazzar, and laid the foundation of the house of God which is in Jerusalem: and since that time even until now hath it been in building, and yet it is not finished."}, {"numero": 17, "texto": "Now therefore, if it seem good to the king, let there be search made in the king''s treasure house, which is there at Babylon, whether it be so, that a decree was made of Cyrus the king to build this house of God at Jerusalem, and let the king send his pleasure to us concerning this matter."}]'::jsonb, 'King James Version'),
  ('Ed', 5, 'fr', '[{"numero": 1, "texto": "Aggée, le prophète, et Zacharie, fils d''''Iddo, le prophète, prophétisèrent aux Juifs qui étaient en Juda et à Jérusalem, au nom du Dieu d''''Israël."}, {"numero": 2, "texto": "Alors Zorobabel, fils de Schealthiel, et Josué, fils de Jotsadak, se levèrent et commencèrent à bâtir la maison de Dieu à Jérusalem. Et avec eux étaient les prophètes de Dieu, qui les assistaient."}, {"numero": 3, "texto": "Dans ce même temps, Thathnaï, gouverneur de ce côté du fleuve, Schethar-Boznaï, et leurs collègues, vinrent auprès d''''eux et leur parlèrent ainsi: Qui vous a donné l''''autorisation de bâtir cette maison et de relever ces murs?"}, {"numero": 4, "texto": "Ils leur dirent encore: Quels sont les noms des hommes qui construisent cet édifice?"}, {"numero": 5, "texto": "Mais l''''oeil de Dieu veillait sur les anciens des Juifs. Et on laissa continuer les travaux pendant l''''envoi d''''un rapport à Darius et jusqu''''à la réception d''''une lettre sur cet objet."}, {"numero": 6, "texto": "Copie de la lettre envoyée au roi Darius par Thathnaï, gouverneur de ce côté du fleuve. Schethar-Boznaï, et leurs collègues d''''Apharsac, demeurant de ce côté du fleuve."}, {"numero": 7, "texto": "Ils lui adressèrent un rapport ainsi conçu: Au roi Darius, salut!"}, {"numero": 8, "texto": "Que le roi sache que nous sommes allés dans la province de Juda, à la maison du grand Dieu. Elle se construit en pierres de taille, et le bois se pose dans les murs; le travail marche rapidement et réussit entre leurs mains."}, {"numero": 9, "texto": "Nous avons interrogé les anciens, et nous leur avons ainsi parlé: Qui vous a donné l''''autorisation de bâtir cette maison et de relever ces murs?"}, {"numero": 10, "texto": "Nous leur avons aussi demandé leurs noms pour te les faire connaître, et nous avons mis par écrit les noms des hommes qui sont à leur tête."}, {"numero": 11, "texto": "Voici la réponse qu''''ils nous ont faite: Nous sommes les serviteurs du Dieu des cieux et de la terre, et nous rebâtissons la maison qui avait été construite il y a bien des années; un grand roi d''''Israël l''''avait bâtie et achevée."}, {"numero": 12, "texto": "Mais après que nos pères eurent irrité le Dieu des cieux, il les livra entre les mains de Nebucadnetsar, roi de Babylone, le Chaldéen, qui détruisit cette maison et emmena le peuple captif à Babylone."}, {"numero": 13, "texto": "Toutefois, la première année de Cyrus, roi de Babylone, le roi Cyrus donna l''''ordre de rebâtir cette maison de Dieu."}, {"numero": 14, "texto": "Et même le roi Cyrus ôta du temple de Babylone les ustensiles d''''or et d''''argent de la maison de Dieu, que Nebucadnetsar avait enlevés du temple de Jérusalem et transportés dans le temple de Babylone, il les fit remettre au nommé Scheschbatsar, qu''''il établit gouverneur,"}, {"numero": 15, "texto": "et il lui dit: Prends ces ustensiles, va les déposer dans le temple de Jérusalem, et que la maison de Dieu soit rebâtie sur le lieu où elle était."}, {"numero": 16, "texto": "Ce Scheschbatsar est donc venu, et il a posé les fondements de la maison de Dieu à Jérusalem; depuis lors jusqu''''à présent elle se construit, et elle n''''est pas achevée."}, {"numero": 17, "texto": "Maintenant, si le roi le trouve bon, que l''''on fasse des recherches dans la maison des trésors du roi à Babylone, pour voir s''''il y a eu de la part du roi Cyrus un ordre donné pour la construction de cette maison de Dieu à Jérusalem. Puis, que le roi nous transmette sa volonté sur cet objet."}]'::jsonb, 'Louis Segond 1910'),
  ('Ed', 5, 'es', '[{"numero": 1, "texto": "Y PROFETIZARON Haggeo profeta, y Zacarías hijo de Iddo, profetas, á los Judíos que estaban en Judá y en Jerusalem yendo en nombre del Dios de Israel á ellos."}, {"numero": 2, "texto": "Entonces se levantaron Zorobabel hijo de Sealthiel, y Jesuá hijo de Josadec; y comenzaron á edificar la casa de Dios que estaba en Jerusalem; y con ellos los profetas de Dios que les ayudaban."}, {"numero": 3, "texto": "En aquel tiempo vino á ellos Tatnai, capitán de la parte allá del río, y Sethar-boznai y sus compañeros, y dijéronles así: ¿Quién os dió mandamiento para edificar esta casa, y restablecer estos muros?"}, {"numero": 4, "texto": "Entonces les dijimos en orden á esto cuáles eran los nombres de los varones que edificaban este edificio."}, {"numero": 5, "texto": "Mas los ojos de su Dios fueron sobre los ancianos de los Judíos, y no les hicieron cesar hasta que el negocio viniese á Darío: y entonces respondieron por carta sobre esto."}, {"numero": 6, "texto": "Traslado de la carta que Tatnai, capitán de la parte allá del río, y Sethar-boznai, y sus compañeros los Apharsachêos, que estaban á la parte allá del río, enviaron al rey Darío."}, {"numero": 7, "texto": "Enviáronle carta, y de esta manera estaba escrito en ella. Al rey Darío toda paz."}, {"numero": 8, "texto": "Sea notorio al rey, que fuimos á la provincia de Judea, á la casa del gran Dios, la cual se edifica de piedra de mármol; y los maderos son puestos en las paredes, y la obra se hace apriesa, y prospera en sus manos."}, {"numero": 9, "texto": "Entonces preguntamos á los ancianos, diciéndoles así: ¿Quién os dió mandamiento para edificar esta casa, y para restablecer estos muros?"}, {"numero": 10, "texto": "Y también les preguntamos sus nombres para hacértelo saber, para escribirte los nombres de los varones que estaban por cabezas de ellos."}, {"numero": 11, "texto": "Y respondiéronnos, diciendo así: Nosotros somos siervos del Dios del cielo y de la tierra, y reedificamos la casa que ya muchos años antes había sido edificada, la cual edificó y fundó el gran rey de Israel."}, {"numero": 12, "texto": "Mas después que nuestros padres ensañaron al Dios de los cielos, él los entregó en mano de Nabucodonosor rey de Babilonia, Caldeo, el cual destruyó esta casa, é hizo trasportar el pueblo á Babilonia."}, {"numero": 13, "texto": "Empero el primer año de Ciro rey de Babilonia, el mismo rey Ciro dió mandamiento para que esta casa de Dios fuese edificada."}, {"numero": 14, "texto": "Y también los vasos de oro y de plata de la casa de Dios, que Nabucodonosor había sacado del templo que estaba en Jerusalem, y los había metido en el templo de Babilonia, el rey Ciro los sacó del templo de Babilonia, y fueron entregados á Sesbassar, al cual había puesto por gobernador;"}, {"numero": 15, "texto": "Y le dijo: Toma estos vasos, ve y ponlos en el templo que está en Jerusalem; y la casa de Dios sea edificada en su lugar."}, {"numero": 16, "texto": "Entonces este Sesbassar vino, y puso los fundamentos de la casa de Dios que estaba en Jerusalem, y desde entonces hasta ahora se edifica, y aun no está acabada."}, {"numero": 17, "texto": "Y ahora, si al rey parece bien, búsquese en la casa de los tesoros del rey que está allí en Babilonia, si es así que por el rey Ciro había sido dado mandamiento para edificar esta casa de Dios en Jerusalem, y envíenos á decir la voluntad del rey sobre esto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ed', 6, 'pt', '[{"numero": 1, "texto": "Então o rei Dario deu ordem, e buscaram nos arquivos da tesouraria na Babilônia."}, {"numero": 2, "texto": "E foi achado em Ecbatana, no palácio que está na província de Média, um livro, dentro do qual estava escrito assim: Memórial:"}, {"numero": 3, "texto": "No primeiro ano do rei Ciro, o rei Ciro fez decreto acerca da casa de Deus que estava em Jerusalém, que fosse reconstruído a casa, o lugar em que sejam oferecidos sacrifícios, e que suas paredes sejam cobertas; sua altura será de sessenta côvados, e sua largura de sessenta côvados."}, {"numero": 4, "texto": "Com três camadas de grandes pedras, e uma camada de madeira nova e que o gasto seja dado da casa do rei."}, {"numero": 5, "texto": "Além disso, os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tirou do templo que estava em Jerusalém e levou a Babilônia, sejam devolvidos para irem ao templo que está em Jerusalém, a seu lugar, e sejam postos na casa de Deus."}, {"numero": 6, "texto": "Agora, [pois] , Tatenai, chefe dalém rio, Setar-Bozenai, e seus companheiros os afarsaquitas que estais além do rio, afastai-vos dali."}, {"numero": 7, "texto": "Deixai-os na obra da casa de Deus; que o governador dos judeus, e os anciãos dos judeus, edifiquem esta casa deste Deus em seu lugar."}, {"numero": 8, "texto": "Também por mim é promulgado decreto do que haveis de fazer com os anciãos destes judeus, para edificar a casa deste Deus: que do patrimônio do rei, dos tributos dalém do rio, sejam pagos os gastos destes homens varões, para que [a obra] não seja interrompida."}, {"numero": 9, "texto": "E o que for necessário, como bezerros, carneiros e cordeiros, para holocaustos ao Deus do céu, trigo, sal, vinho e azeite, conforme o que os sacerdotes que estão em Jerusalém disserem, seja lhes dado a cada um sem falta."}, {"numero": 10, "texto": "Para que ofereçam sacrifícios de aroma suave ao ao Deus dos céus, e orem pela vida do rei e de seus filhos."}, {"numero": 11, "texto": "Também é dada por mim ordem, que qualquer um que mudar este decreto, um madeiro de sua casa seja derrubado, levantado, e nele seja empalado; e sua casa se torne um amontoado por causa disso."}, {"numero": 12, "texto": "E o Deus que fez habitar ali seu nome, derrube a todo rei e povo que estenderem sua mão para mudar ou destruir esta casa de Deus, que está em Jerusalém. Eu, Dario, fiz o decreto; apressadamente se cumpra."}, {"numero": 13, "texto": "Então Tatenai, o governador dalém do rio, e Setar-Bozenai, e seus companheiros, assim fizeram apressadamente, conforme o que o rei Dario havia mandado."}, {"numero": 14, "texto": "E os anciãos dos judeus iam edificando e prosperando, pela profecia do profeta Ageu, e de Zacarias filho de Ido. E edificaram, e terminaram a construção conforme o mandamento do Deus de Israel, e conforme o mandamento de Ciro e de Dario, e de Artaxerxes rei da Pérsia."}, {"numero": 15, "texto": "E esta casa foi terminada ao terceiro dia do mês de Adar, que era o sexto ano do reinado do rei Dario."}, {"numero": 16, "texto": "E os filhos de Israel, os sacerdotes e os levitas, e os demais dos que vieram do cativeiro, fizeram a consagração desta casa de Deus com alegria."}, {"numero": 17, "texto": "E ofereceram para a consagração desta casa de Deus cem novilhos, duzentos carneiros, quatrocentos cordeiros; e doze cabritos por expiação do pecado de todo Israel, segundo o número das tribos de Israel."}, {"numero": 18, "texto": "E puseram aos sacerdotes em suas divisões, e aos levitas em seus grupos, para o serviço a Deus, que está em Jerusalém, conforme o que está escrito no livro de Moisés."}, {"numero": 19, "texto": "E os que vieram do cativeiro celebraram a páscoa aos catorze do mês primeiro."}, {"numero": 20, "texto": "Porque os sacerdotes e os levitas haviam se purificado juntos; todos foram limpos; e fizeram o sacrifício da páscoa por todos os que vieram do cativeiro, e por seus irmãos, os sacerdotes, e por si mesmos."}, {"numero": 21, "texto": "Assim os filhos de Israel que haviam voltado do cativeiro comeram, com todos os que tinham se separado da impureza das nações da terra, para buscarem ao SENHOR Deus de Israel."}, {"numero": 22, "texto": "E celebraram a festa dos pães sem fermento sete dias com alegria, porque o SENHOR os tinha alegrado, e convertido o coração do rei da Assíria a eles, para fortalecer suas mãos na obra da casa de Deus, o Deus de Israel."}]'::jsonb, 'Almeida Livre'),
  ('Ed', 6, 'en', '[{"numero": 1, "texto": "Then Darius the king made a decree, and search was made in the house of the rolls, where the treasures were laid up in Babylon."}, {"numero": 2, "texto": "And there was found at Achmetha, in the palace that is in the province of the Medes, a roll, and therein was a record thus written:"}, {"numero": 3, "texto": "In the first year of Cyrus the king the same Cyrus the king made a decree concerning the house of God at Jerusalem, Let the house be builded, the place where they offered sacrifices, and let the foundations thereof be strongly laid; the height thereof threescore cubits, and the breadth thereof threescore cubits;"}, {"numero": 4, "texto": "With three rows of great stones, and a row of new timber: and let the expenses be given out of the king''s house:"}, {"numero": 5, "texto": "And also let the golden and silver vessels of the house of God, which Nebuchadnezzar took forth out of the temple which is at Jerusalem, and brought unto Babylon, be restored, and brought again unto the temple which is at Jerusalem, every one to his place, and place them in the house of God."}, {"numero": 6, "texto": "Now therefore, Tatnai, governor beyond the river, Shetharboznai, and your companions the Apharsachites, which are beyond the river, be ye far from thence:"}, {"numero": 7, "texto": "Let the work of this house of God alone; let the governor of the Jews and the elders of the Jews build this house of God in his place."}, {"numero": 8, "texto": "Moreover I make a decree what ye shall do to the elders of these Jews for the building of this house of God: that of the king''s goods, even of the tribute beyond the river, forthwith expenses be given unto these men, that they be not hindered."}, {"numero": 9, "texto": "And that which they have need of, both young bullocks, and rams, and lambs, for the burnt offerings of the God of heaven, wheat, salt, wine, and oil, according to the appointment of the priests which are at Jerusalem, let it be given them day by day without fail:"}, {"numero": 10, "texto": "That they may offer sacrifices of sweet savours unto the God of heaven, and pray for the life of the king, and of his sons."}, {"numero": 11, "texto": "Also I have made a decree, that whosoever shall alter this word, let timber be pulled down from his house, and being set up, let him be hanged thereon; and let his house be made a dunghill for this."}, {"numero": 12, "texto": "And the God that hath caused his name to dwell there destroy all kings and people, that shall put to their hand to alter and to destroy this house of God which is at Jerusalem. I Darius have made a decree; let it be done with speed."}, {"numero": 13, "texto": "Then Tatnai, governor on this side the river, Shetharboznai, and their companions, according to that which Darius the king had sent, so they did speedily."}, {"numero": 14, "texto": "And the elders of the Jews builded, and they prospered through the prophesying of Haggai the prophet and Zechariah the son of Iddo. And they builded, and finished it, according to the commandment of the God of Israel, and according to the commandment of Cyrus, and Darius, and Artaxerxes king of Persia."}, {"numero": 15, "texto": "And this house was finished on the third day of the month Adar, which was in the sixth year of the reign of Darius the king."}, {"numero": 16, "texto": "And the children of Israel, the priests, and the Levites, and the rest of the children of the captivity, kept the dedication of this house of God with joy."}, {"numero": 17, "texto": "And offered at the dedication of this house of God an hundred bullocks, two hundred rams, four hundred lambs; and for a sin offering for all Israel, twelve he goats, according to the number of the tribes of Israel."}, {"numero": 18, "texto": "And they set the priests in their divisions, and the Levites in their courses, for the service of God, which is at Jerusalem; as it is written in the book of Moses."}, {"numero": 19, "texto": "And the children of the captivity kept the passover upon the fourteenth day of the first month."}, {"numero": 20, "texto": "For the priests and the Levites were purified together, all of them were pure, and killed the passover for all the children of the captivity, and for their brethren the priests, and for themselves."}, {"numero": 21, "texto": "And the children of Israel, which were come again out of captivity, and all such as had separated themselves unto them from the filthiness of the heathen of the land, to seek the Lord God of Israel, did eat,"}, {"numero": 22, "texto": "And kept the feast of unleavened bread seven days with joy: for the Lord had made them joyful, and turned the heart of the king of Assyria unto them, to strengthen their hands in the work of the house of God, the God of Israel."}]'::jsonb, 'King James Version'),
  ('Ed', 6, 'fr', '[{"numero": 1, "texto": "Alors le roi Darius donna ordre de faire des recherches dans la maison des archives où l''''on déposait les trésors à Babylone."}, {"numero": 2, "texto": "Et l''''on trouva à Achmetha, capitale de la province de Médie, un rouleau sur lequel était écrit le mémoire suivant:"}, {"numero": 3, "texto": "La première année du roi Cyrus, le roi Cyrus a donné cet ordre au sujet de la maison de Dieu à Jérusalem: Que la maison soit rebâtie, pour être un lieu où l''''on offre des sacrifices, et qu''''elle ait des solides fondements. Elle aura soixante coudées de hauteur, soixante coudées de largeur,"}, {"numero": 4, "texto": "trois rangées de pierres de taille et une rangée de bois neuf. Les frais seront payés par la maison du roi."}, {"numero": 5, "texto": "De plus, les ustensiles d''''or et d''''argent de la maison de Dieu, que Nebucadnetsar avait enlevés du temple de Jérusalem et transportés à Babylone, seront rendus, transportés au temple de Jérusalem à la place où ils étaient, et déposés dans la maison de Dieu."}, {"numero": 6, "texto": "Maintenant, Thathnaï, gouverneur de l''''autre côté du fleuve, Schethar-Boznaï, et vos collègues d''''Apharsac, qui demeurez de l''''autre côté du fleuve, tenez-vous loin de ce lieu."}, {"numero": 7, "texto": "Laissez continuer les travaux de cette maison de Dieu; que le gouverneur des Juifs et les anciens des Juifs la rebâtissent sur l''''emplacement qu''''elle occupait."}, {"numero": 8, "texto": "Voici l''''ordre que je donne touchant ce que vous aurez à faire à l''''égard de ces anciens des Juifs pour la construction de cette maison de Dieu: les frais, pris sur les biens du roi provenant des tributs de l''''autre côté du fleuve, seront exactement payés à ces hommes, afin qu''''il n''''y ait pas d''''interruption."}, {"numero": 9, "texto": "Les choses nécessaires pour les holocaustes du Dieu des cieux, jeunes taureaux, béliers et agneaux, froment, sel, vin et huile, seront livrées, sur leur demande, aux sacrificateurs de Jérusalem, jour par jour et sans manquer,"}, {"numero": 10, "texto": "afin qu''''ils offrent des sacrifices de bonne odeur au Dieu des cieux et qu''''ils prient pour la vie du roi et de ses fils."}, {"numero": 11, "texto": "Et voici l''''ordre que je donne touchant quiconque transgressera cette parole: on arrachera de sa maison une pièce de bois, on la dressera pour qu''''il y soit attaché, et l''''on fera de sa maison un tas d''''immondices."}, {"numero": 12, "texto": "Que le Dieu qui fait résider en ce lieu son nom renverse tout roi et tout peuple qui étendraient la main pour transgresser ma parole, pour détruire cette maison de Dieu à Jérusalem! Moi, Darius, j''''ai donné cet ordre. Qu''''il soit ponctuellement exécuté."}, {"numero": 13, "texto": "Thathnaï, gouverneur de ce côté du fleuve, Schethar-Boznaï, et leurs collègues, se conformèrent ponctuellement à cet ordre que leur envoya le roi Darius."}, {"numero": 14, "texto": "Et les anciens des Juifs bâtirent avec succès, selon les prophéties d''''Aggée, le prophète, et de Zacharie, fils d''''Iddo; ils bâtirent et achevèrent, d''''après l''''ordre du Dieu d''''Israël, et d''''après l''''ordre de Cyrus, de Darius, et d''''Artaxerxès, roi de Perse."}, {"numero": 15, "texto": "La maison fut achevée le troisième jour du mois d''''Adar, dans la sixième année du règne du roi Darius."}, {"numero": 16, "texto": "Les enfants d''''Israël, les sacrificateurs et les Lévites, et le reste des fils de la captivité, firent avec joie la dédicace de cette maison de Dieu."}, {"numero": 17, "texto": "Ils offrirent, pour la dédicace de cette maison de Dieu, cent taureaux, deux cents béliers, quatre cents agneaux, et, comme victimes expiatoires pour tout Israël, douze boucs, d''''après le nombre des tribus d''''Israël."}, {"numero": 18, "texto": "Ils établirent les sacrificateurs selon leurs classes et les Lévites selon leurs divisions pour le service de Dieu à Jérusalem, comme il est écrit dans le livre de Moïse."}, {"numero": 19, "texto": "Les fils de la captivité célébrèrent la Pâque le quatorzième jour du premier mois."}, {"numero": 20, "texto": "Les sacrificateurs et les Lévites s''''étaient purifiés de concert, tous étaient purs; ils immolèrent la Pâque pour tous les fils de la captivité, pour leurs frères les sacrificateurs, et pour eux-mêmes."}, {"numero": 21, "texto": "Les enfants d''''Israël revenus de la captivité mangèrent la Pâque, avec tous ceux qui s''''étaient éloignés de l''''impureté des nations du pays et qui se joignirent à eux pour chercher l''''Eternel, le Dieu d''''Israël."}, {"numero": 22, "texto": "Ils célébrèrent avec joie pendant sept jours la fête des pains sans levain, car l''''Eternel les avait réjouis en disposant le roi d''''Assyrie à les soutenir dans l''''oeuvre de la maison de Dieu, du Dieu d''''Israël."}]'::jsonb, 'Louis Segond 1910'),
  ('Ed', 6, 'es', '[{"numero": 1, "texto": "ENTONCES el rey Darío dió mandamiento, y buscaron en la casa de los libros, donde guardaban los tesoros allí en Babilonia."}, {"numero": 2, "texto": "Y fué hallado en Achmetta, en el palacio que está en la provincia de Media, un libro, dentro del cual estaba escrito así: Memoria:"}, {"numero": 3, "texto": "En el año primero del rey Ciro, el mismo rey Ciro dió mandamiento acerca de la casa de Dios que estaba en Jerusalem, que fuese la casa edificada para lugar en que sacrifiquen sacrificios, y que sus paredes fuesen cubiertas; su altura de sesenta codos, y de sesenta codos su anchura;"}, {"numero": 4, "texto": "Los órdenes, tres de piedra de mármol, y un orden de madera nueva: y que el gasto sea dado de la casa del rey."}, {"numero": 5, "texto": "Y también los vasos de oro y de plata de la casa de Dios, que Nabucodonosor sacó del templo que estaba en Jerusalem y los pasó á Babilonia, sean devueltos y vayan al templo que está en Jerusalem, á su lugar, y sean puestos en la casa de Dios."}, {"numero": 6, "texto": "Ahora pues, Tatnai, jefe del lado allá del río, Sethar-boznai, y sus compañeros los Apharsachêos que estáis á la otra parte del río, apartaos de ahí."}, {"numero": 7, "texto": "Dejad la obra de la casa de este Dios al principal de los Judíos, y á sus ancianos, para que edifiquen la casa de este Dios en su lugar."}, {"numero": 8, "texto": "Y por mí es dado mandamiento de lo que habéis de hacer con los ancianos de estos Judíos, para edificar la casa de este Dios: que de la hacienda del rey, que tiene del tributo de la parte allá del río, los gastos sean dados luego á aquellos varones, para que no cesen."}, {"numero": 9, "texto": "Y lo que fuere necesario, becerros y carneros y corderos, para holocaustos al Dios del cielo, trigo, sal, vino y aceite, conforme á lo que dijeren los sacerdotes que están en Jerusalem, déseles cada un día sin obstáculo alguno;"}, {"numero": 10, "texto": "Para que ofrezcan olores de holganza al Dios del cielo, y oren por la vida del rey y por sus hijos."}, {"numero": 11, "texto": "También es dado por mí mandamiento, que cualquiera que mudare este decreto, sea derribado un madero de su casa, y enhiesto, sea colgado en él: y su casa sea hecha muladar por esto."}, {"numero": 12, "texto": "Y el Dios que hizo habitar allí su nombre, destruya todo rey y pueblo que pusiere su mano para mudar ó destruir esta casa de Dios, la cual está en Jerusalem. Yo Darío puse el decreto: sea hecho prestamente."}, {"numero": 13, "texto": "Entonces Tatnai, gobernador del otro lado del río, y Sethar-boznai, y sus compañeros, hicieron prestamente según el rey Darío había enviado."}, {"numero": 14, "texto": "Y los ancianos de los Judíos edificaban y prosperaban, conforme á la profecía de Haggeo profeta, y de Zacarías hijo de Iddo. Edificaron pues, y acabaron, por el mandamiento del Dios de Israel, y por el mandamiento de Ciro, y de Darío, y de Artajerjes rey de Persia."}, {"numero": 15, "texto": "Y esta casa fué acabada al tercer día del mes de Adar, que era el sexto año del reinado del rey Darío."}, {"numero": 16, "texto": "Y los hijos de Israel, los sacerdotes y los Levitas, y los demás que habían venido de la trasportación, hicieron la dedicación de esta casa de Dios con gozo."}, {"numero": 17, "texto": "Y ofrecieron en la dedicación de esta casa de Dios cien becerros, doscientos carneros, cuatrocientos corderos; y machos de cabrío en expiación por todo Israel, doce, conforme al número de las tribus de Israel."}, {"numero": 18, "texto": "Y pusieron á los sacerdotes en sus clases, y á los Levitas en sus divisiones, sobre la obra de Dios que está en Jerusalem, conforme á lo escrito en el libro de Moisés."}, {"numero": 19, "texto": "Y los de la transmigración hicieron la pascua á los catorce del mes primero."}, {"numero": 20, "texto": "Porque los sacerdotes y los Levitas se habían purificado á una; todos fueron limpios: y sacrificaron la pascua por todos los de la transmigración, y por sus hermanos los sacerdotes, y por sí mismos."}, {"numero": 21, "texto": "Y comieron los hijos de Israel que habían vuelto de la transmigración, y todos los que se habían apartado á ellos de la inmundicia de las gentes de la tierra, para buscar á Jehová Dios de Israel."}, {"numero": 22, "texto": "Y celebraron la solemnidad de los panes ázimos siete días con regocijo, por cuanto Jehová los había alegrado, y convertido el corazón del rey de Asiria á ellos, para esforzar sus manos en la obra de la casa de Dios, del Dios de Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ed', 7, 'pt', '[{"numero": 1, "texto": "Passadas estas coisas, no reinado de Artaxerxes, rei da Pérsia, Esdras, filho de Seraías, filho de Azarias, filho de Hilquias,"}, {"numero": 2, "texto": "filho de Salum, filho de Zadoque, filho de Aitube,"}, {"numero": 3, "texto": "filho de Amarias, filho de Azarias, filho de Meraiote,"}, {"numero": 4, "texto": "filho de Zeraías, filho de Uzi, filho de Buqui,"}, {"numero": 5, "texto": "filho de Abisua, filho de Fineias, filho de Eleazar, filho de Arão, o sumo sacerdote;"}, {"numero": 6, "texto": "este Esdras subiu da Babilônia; e ele era escriba habilidoso na lei de Moisés, dada pelo SENHOR Deus de Israel; e segundo a mão do SENHOR, seu Deus, sobre ele, o rei lhe deu tudo quanto lhe pedira."}, {"numero": 7, "texto": "E subiram com ele a Jerusalém [alguns] dos filhos de Israel, dos sacerdotes, levitas, cantores, porteiros, e servos do templo, no sétimo ano do rei Artaxerxes."}, {"numero": 8, "texto": "E ele chegou a Jerusalém no mês quinto, no sétimo ano do rei."}, {"numero": 9, "texto": "Pois no primeiro [dia] do mês primeiro, foi o princípio da subida da Babilônia; e ao primeiro do mês quinto chegou a Jerusalém, segundo a boa mão de seu Deus sobre ele."}, {"numero": 10, "texto": "Porque Esdras tinha decidido em seu coração buscar a lei do SENHOR, e a praticar; e ensinar a Israel [seus] estatutos e juízos."}, {"numero": 11, "texto": "E este é a transcrição da carta que o rei Artaxerxes deu a Esdras, sacerdote e escriba, o escriba das palavras dos mandamentos do SENHOR, e de seus estatutos sobre Israel:"}, {"numero": 12, "texto": "Artaxerxes, rei de reis, ao sacerdote Esdras, escriba da Lei de Deus do céu. [Paz] completa."}, {"numero": 13, "texto": "Por mim é promulgado decreto, que todo aquele em meu reino, do povo de Israel, e de seus sacerdotes e levitas, que quiser ir contigo a Jerusalém, vá."}, {"numero": 14, "texto": "Porque de parte do rei e de seus sete conselheiros tu és enviado a investigar a respeito da de Judá e de Jerusalém, conforme a lei de teu Deus que está em tua mão;"}, {"numero": 15, "texto": "E a levar a prata e o ouro que o rei e seus conselheiros voluntariamente deram ao Deus de Israel, cuja habitação está em Jerusalém;"}, {"numero": 16, "texto": "E também toda a prata e o ouro que achares em toda a província de Babilônia, com as ofertas voluntárias do povo e dos sacerdotes, que voluntariamente oferecerem para a casa de seu Deus que está em Jerusalém."}, {"numero": 17, "texto": "Portanto, com este dinheiro, compra novilhos, carneiros, cordeiros, com seus suas ofertas de alimento e suas ofertas de bebidas, e oferece-os sobre o altar da casa de vosso Deus, que está em Jerusalém."}, {"numero": 18, "texto": "Também o que a ti e a teus irmãos parecer bem fazerdes do restante da prata e do ouro, fazei [-o] conforme a vontade de vosso Deus."}, {"numero": 19, "texto": "E os utensílios que te foram entregues para o serviço da casa de teu Deus, restitui-os diante do Deus de Jerusalém."}, {"numero": 20, "texto": "E o demais que for necessário para a casa de teu Deus que caiba a ti dar, tu o darás da casa dos tesouros do rei."}, {"numero": 21, "texto": "E por mim mesmo, o rei Artaxerxes, é dado decreto a todos os tesoureiros que estão além do rio, que tudo quanto o sacerdote Esdras, escriba da lei do Deus dos céus, vos pedir, apressadamente lhe seja concedido;"}, {"numero": 22, "texto": "Até cem talentos de prata, e até cem coros de trigo, e até cem batos de vinho, e até cem batos de azeite; e sal sem limite."}, {"numero": 23, "texto": "Tudo o que for ordenado pelo Deus do céu, prontamente se faça para a casa do Deus do céu; pois para que teria de haver grande ira contra o reino do rei e de seus filhos?"}, {"numero": 24, "texto": "Também vos fazemos saber, acerca de todos os sacerdotes, levitas, cantores, porteiros, servos do templo, e trabalhadores da casa de Deus, ninguém possa lhes impor tributo, imposto, ou taxa."}, {"numero": 25, "texto": "E tu, Esdras, conforme a sabedoria de teu Deus que está contigo, põe oficiais e juízes, que julguem a todo o povo que está além do rio, a todos os que conhecem as Leis de teu Deus; e ao que não as conhecerem, tu lhes ensinará."}, {"numero": 26, "texto": "E todo aquele que não cumprir a Lei de teu Deus e a lei do rei, prontamente seja julgado, ou à morte, ou à expulsão, ou à multa, ou à prisão."}, {"numero": 27, "texto": "Bendito seja o SENHOR, Deus de nossos pais, que pôs tal coisa no coração do rei, para glorificar a casa do SENHOR, que está em Jerusalém;"}, {"numero": 28, "texto": "E sobre mim inclinou bondade diante do rei e de seus conselheiros, e de todos os príncipes poderosos do rei. Assim eu me esforcei segundo a mão do SENHOR meu Deus sobre mim, e ajuntei os líderes de Israel para subirem comigo."}]'::jsonb, 'Almeida Livre'),
  ('Ed', 7, 'en', '[{"numero": 1, "texto": "Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah,"}, {"numero": 2, "texto": "The son of Shallum, the son of Zadok, the son of Ahitub,"}, {"numero": 3, "texto": "The son of Amariah, the son of Azariah, the son of Meraioth,"}, {"numero": 4, "texto": "The son of Zerahiah, the son of Uzzi, the son of Bukki,"}, {"numero": 5, "texto": "The son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest:"}, {"numero": 6, "texto": "This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the Lord God of Israel had given: and the king granted him all his request, according to the hand of the Lord his God upon him."}, {"numero": 7, "texto": "And there went up some of the children of Israel, and of the priests, and the Levites, and the singers, and the porters, and the Nethinims, unto Jerusalem, in the seventh year of Artaxerxes the king."}, {"numero": 8, "texto": "And he came to Jerusalem in the fifth month, which was in the seventh year of the king."}, {"numero": 9, "texto": "For upon the first day of the first month began he to go up from Babylon, and on the first day of the fifth month came he to Jerusalem, according to the good hand of his God upon him."}, {"numero": 10, "texto": "For Ezra had prepared his heart to seek the law of the Lord, and to do it, and to teach in Israel statutes and judgments."}, {"numero": 11, "texto": "Now this is the copy of the letter that the king Artaxerxes gave unto Ezra the priest, the scribe, even a scribe of the words of the commandments of the Lord, and of his statutes to Israel."}, {"numero": 12, "texto": "Artaxerxes, king of kings, unto Ezra the priest, a scribe of the law of the God of heaven, perfect peace, and at such a time."}, {"numero": 13, "texto": "I make a decree, that all they of the people of Israel, and of his priests and Levites, in my realm, which are minded of their own freewill to go up to Jerusalem, go with thee."}, {"numero": 14, "texto": "Forasmuch as thou art sent of the king, and of his seven counsellors, to enquire concerning Judah and Jerusalem, according to the law of thy God which is in thine hand;"}, {"numero": 15, "texto": "And to carry the silver and gold, which the king and his counsellors have freely offered unto the God of Israel, whose habitation is in Jerusalem,"}, {"numero": 16, "texto": "And all the silver and gold that thou canst find in all the province of Babylon, with the freewill offering of the people, and of the priests, offering willingly for the house of their God which is in Jerusalem:"}, {"numero": 17, "texto": "That thou mayest buy speedily with this money bullocks, rams, lambs, with their meat offerings and their drink offerings, and offer them upon the altar of the house of your God which is in Jerusalem."}, {"numero": 18, "texto": "And whatsoever shall seem good to thee, and to thy brethren, to do with the rest of the silver and the gold, that do after the will of your God."}, {"numero": 19, "texto": "The vessels also that are given thee for the service of the house of thy God, those deliver thou before the God of Jerusalem."}, {"numero": 20, "texto": "And whatsoever more shall be needful for the house of thy God, which thou shalt have occasion to bestow, bestow it out of the king''s treasure house."}, {"numero": 21, "texto": "And I, even I Artaxerxes the king, do make a decree to all the treasurers which are beyond the river, that whatsoever Ezra the priest, the scribe of the law of the God of heaven, shall require of you, it be done speedily,"}, {"numero": 22, "texto": "Unto an hundred talents of silver, and to an hundred measures of wheat, and to an hundred baths of wine, and to an hundred baths of oil, and salt without prescribing how much."}, {"numero": 23, "texto": "Whatsoever is commanded by the God of heaven, let it be diligently done for the house of the God of heaven: for why should there be wrath against the realm of the king and his sons?"}, {"numero": 24, "texto": "Also we certify you, that touching any of the priests and Levites, singers, porters, Nethinims, or ministers of this house of God, it shall not be lawful to impose toll, tribute, or custom, upon them."}, {"numero": 25, "texto": "And thou, Ezra, after the wisdom of thy God, that is in thine hand, set magistrates and judges, which may judge all the people that are beyond the river, all such as know the laws of thy God; and teach ye them that know them not."}, {"numero": 26, "texto": "And whosoever will not do the law of thy God, and the law of the king, let judgment be executed speedily upon him, whether it be unto death, or to banishment, or to confiscation of goods, or to imprisonment."}, {"numero": 27, "texto": "Blessed be the Lord God of our fathers, which hath put such a thing as this in the king''s heart, to beautify the house of the Lord which is in Jerusalem:"}, {"numero": 28, "texto": "And hath extended mercy unto me before the king, and his counsellors, and before all the king''s mighty princes. And I was strengthened as the hand of the Lord my God was upon me, and I gathered together out of Israel chief men to go up with me."}]'::jsonb, 'King James Version'),
  ('Ed', 7, 'fr', '[{"numero": 1, "texto": "Après ces choses, sous le règne d''''Artaxerxès, roi de Perse, vint Esdras, fils de Seraja, fils d''''Azaria, fils de Hilkija,"}, {"numero": 2, "texto": "fils de Schallum, fils de Tsadok, fils d''''Achithub,"}, {"numero": 3, "texto": "fils d''''Amaria, fils d''''Azaria, fils de Merajoth,"}, {"numero": 4, "texto": "fils de Zerachja, fils d''''Uzzi, fils de Bukki,"}, {"numero": 5, "texto": "fils d''''Abischua, fils de Phinées, fils d''''Eléazar, fils d''''Aaron, le souverain sacrificateur."}, {"numero": 6, "texto": "Cet Esdras vint de Babylone: c''''était un scribe versé dans la loi de Moïse, donnée par l''''Eternel, le Dieu d''''Israël. Et comme la main de l''''Eternel, son Dieu, était sur lui, le roi lui accorda tout ce qu''''il avait demandé."}, {"numero": 7, "texto": "Plusieurs des enfants d''''Israël, des sacrificateurs et des Lévites, des chantres, des portiers, et des Néthiniens, vinrent aussi à Jérusalem, la septième année du roi Artaxerxès."}, {"numero": 8, "texto": "Esdras arriva à Jérusalem au cinquième mois de la septième année du roi;"}, {"numero": 9, "texto": "il était parti de Babylone le premier jour du premier mois, et il arriva à Jérusalem le premier jour du cinquième mois, la bonne main de son Dieu étant sur lui."}, {"numero": 10, "texto": "Car Esdras avait appliqué son coeur à étudier et à mettre en pratique la loi de l''''Eternel, et à enseigner au milieu d''''Israël les lois et les ordonnances."}, {"numero": 11, "texto": "Voici la copie de la lettre donnée par le roi Artaxerxès à Esdras, sacrificateur et scribe, enseignant les commandements et les lois de l''''Eternel concernant Israël:"}, {"numero": 12, "texto": "Artaxerxès, roi des rois, à Esdras, sacrificateur et scribe, versé dans la loi du Dieu des cieux, etc."}, {"numero": 13, "texto": "J''''ai donné ordre de laisser aller tous ceux du peuple d''''Israël, de ses sacrificateurs et de ses Lévites, qui se trouvent dans mon royaume, et qui sont disposés à partir avec toi pour Jérusalem."}, {"numero": 14, "texto": "Tu es envoyé par le roi et ses sept conseillers pour inspecter Juda et Jérusalem d''''après la loi de ton Dieu, laquelle est entre tes mains,"}, {"numero": 15, "texto": "et pour porter l''''argent et l''''or que le roi et ses conseillers ont généreusement offerts au Dieu d''''Israël, dont la demeure est à Jérusalem,"}, {"numero": 16, "texto": "tout l''''argent et l''''or que tu trouveras dans toute la province de Babylone, et les dons volontaires faits par le peuple et les sacrificateurs pour la maison de leur Dieu à Jérusalem."}, {"numero": 17, "texto": "En conséquence, tu auras soin d''''acheter avec cet argent des taureaux, des béliers, des agneaux, et ce qui est nécessaire pour les offrandes et les libations, et tu les offriras sur l''''autel de la maison de votre Dieu à Jérusalem."}, {"numero": 18, "texto": "Vous ferez avec le reste de l''''argent et de l''''or ce que vous jugerez bon de faire, toi et tes frères, en vous conformant à la volonté de votre Dieu."}, {"numero": 19, "texto": "Dépose devant le Dieu de Jérusalem les ustensiles qui te sont remis pour le service de la maison de ton Dieu."}, {"numero": 20, "texto": "Tu tireras de la maison des trésors du roi ce qu''''il faudra pour les autres dépenses que tu auras à faire concernant la maison de ton Dieu."}, {"numero": 21, "texto": "Moi, le roi Artaxerxès, je donne l''''ordre à tous les trésoriers de l''''autre côté du fleuve de livrer exactement à Esdras, sacrificateur et scribe, versé dans la loi du Dieu des cieux, tout ce qu''''il vous demandera,"}, {"numero": 22, "texto": "jusqu''''à cent talents d''''argent, cent cors de froment, cent baths de vin, cent baths d''''huile, et du sel à discrétion."}, {"numero": 23, "texto": "Que tout ce qui est ordonné par le Dieu des cieux se fasse ponctuellement pour la maison du Dieu des cieux, afin que sa colère ne soit pas sur le royaume, sur le roi et sur ses fils."}, {"numero": 24, "texto": "Nous vous faisons savoir qu''''il ne peut être levé ni tribut, ni impôt, ni droit de passage, sur aucun des sacrificateurs, des Lévites, des chantres, des portiers, des Néthiniens, et des serviteurs de cette maison de Dieu."}, {"numero": 25, "texto": "Et toi, Esdras, selon la sagesse de Dieu que tu possèdes, établis des juges et des magistrats qui rendent la justice à tout le peuple de l''''autre côté du fleuve, à tous ceux qui connaissent les lois de ton Dieu; et fais-les connaître à ceux qui ne les connaissent pas."}, {"numero": 26, "texto": "Quiconque n''''observera pas ponctuellement la loi de ton Dieu et la loi du roi sera condamné à la mort, au bannissement, à une amende, ou à la prison."}, {"numero": 27, "texto": "Béni soit l''''Eternel, le Dieu de nos pères, qui a disposé le coeur du roi à glorifier ainsi la maison de l''''Eternel à Jérusalem,"}, {"numero": 28, "texto": "et qui m''''a rendu l''''objet de la bienveillance du roi, de ses conseillers, et de tous ses puissants chefs! Fortifié par la main de l''''Eternel, mon Dieu, qui était sur moi, j''''ai rassemblé les chefs d''''Israël, afin qu''''ils partissent avec moi."}]'::jsonb, 'Louis Segond 1910'),
  ('Ed', 7, 'es', '[{"numero": 1, "texto": "PASADAS estas cosas, en el reinado de Artajerjes rey de Persia, Esdras, hijo de Seraías, hijo de Azarías, hijo de Hilcías,"}, {"numero": 2, "texto": "Hijo de Sallum, hijo de Sadoc, hijo de Achîtob,"}, {"numero": 3, "texto": "Hijo de Amarías, hijo de Azarías, hijo de Meraioth,"}, {"numero": 4, "texto": "Hijo de Zeraías, hijo de Uzzi, hijo de Bucci,"}, {"numero": 5, "texto": "Hijo de Abisue, hijo de Phinees, hijo de Eleazar, hijo de Aarón, primer sacerdote:"}, {"numero": 6, "texto": "Este Esdras subió de Babilonia, el cual era escriba diligente en la ley de Moisés, que Jehová Dios de Israel había dado; y concedióle el rey, según la mano de Jehová su Dios sobre él, todo lo que pidió."}, {"numero": 7, "texto": "Y subieron con él á Jerusalem de los hijos de Israel, y de los sacerdotes, y Levitas, y cantores, y porteros, y Nethineos, en el séptimo año del rey Artajerjes."}, {"numero": 8, "texto": "Y llegó á Jerusalem en el mes quinto, el año séptimo del rey."}, {"numero": 9, "texto": "Porque el día primero del primer mes fué el principio de la partida de Babilonia, y al primero del mes quinto llegó á Jerusalem, según la buena mano de su Dios sobre él."}, {"numero": 10, "texto": "Porque Esdras había preparado su corazón para inquirir la ley de Jehová, y para hacer y enseñar á Israel mandamientos y juicios."}, {"numero": 11, "texto": "Y este es el traslado de la carta que dió el rey Artajerjes á Esdras, sacerdote escriba, escriba de las palabras mandadas de Jehová, y de sus estatutos á Israel:"}, {"numero": 12, "texto": "Artajerjes, rey de los reyes, á Esdras sacerdote, escriba perfecto de la ley del Dios del cielo: Salud, etc."}, {"numero": 13, "texto": "Por mí es dado mandamiento, que cualquiera que quisiere en mi reino, del pueblo de Israel y de sus sacerdotes y Levitas, ir contigo á Jerusalem, vaya."}, {"numero": 14, "texto": "Porque de parte del rey y de sus siete consultores eres enviado á visitar á Judea y á Jerusalem, conforme á la ley de tu Dios que está en tu mano;"}, {"numero": 15, "texto": "Y á llevar la plata y el oro que el rey y sus consultores voluntariamente ofrecen al Dios de Israel, cuya morada está en Jerusalem;"}, {"numero": 16, "texto": "Y toda la plata y el oro que hallares en toda la provincia de Babilonia, con las ofrendas voluntarias del pueblo y de los sacerdotes, que de su voluntad ofrecieren para la casa de su Dios que está en Jerusalem."}, {"numero": 17, "texto": "Comprarás pues prestamente con esta plata becerros, carneros, corderos, con sus presentes y sus libaciones, y los ofrecerás sobre el altar de la casa de vuestro Dios que está en Jerusalem."}, {"numero": 18, "texto": "Y lo que á ti y á tus hermanos pluguiere hacer de la otra plata y oro, hacedlo conforme á la voluntad de vuestro Dios."}, {"numero": 19, "texto": "Y los vasos que te son entregados para el servicio de la casa de tu Dios, los restituirás delante de Dios en Jerusalem."}, {"numero": 20, "texto": "Y lo demás necesario para la casa de tu Dios que te fuere menester dar, daráslo de la casa de los tesoros del rey."}, {"numero": 21, "texto": "Y por mí el rey Artajerjes es dado mandamiento á todos los tesoreros que están al otro lado del río, que todo lo que os demandare Esdras sacerdote, escriba de la ley del Dios del cielo, concédasele luego,"}, {"numero": 22, "texto": "Hasta cien talentos de plata, y hasta cien coros de trigo, y hasta cien batos de vino, y hasta cien batos de aceite; y sal sin tasa."}, {"numero": 23, "texto": "Todo lo que es mandado por el Dios del cielo, sea hecho prestamente para la casa del Dios del cielo: pues, ¿por qué habría de ser su ira contra el reino del rey y de sus hijos?"}, {"numero": 24, "texto": "Y á vosotros os hacemos saber, que á todos los sacerdotes y Levitas, cantores, porteros, Nethineos y ministros de la casa de Dios, ninguno pueda imponerles tributo, ó pecho, ó renta."}, {"numero": 25, "texto": "Y tú, Esdras, conforme á la sabiduría de tu Dios que tienes, pon jueces y gobernadores, que gobiernen á todo el pueblo que está del otro lado del río, á todos los que tienen noticia de las leyes de tu Dios; y al que no la tuviere, le enseñaréis."}, {"numero": 26, "texto": "Y cualquiera que no hiciere la ley de tu Dios, y la ley del rey, prestamente sea juzgado, ó á muerte, ó á desarraigo, ó á pena de la hacienda, ó á prisión."}, {"numero": 27, "texto": "Bendito Jehová, Dios de nuestros padres, que puso tal cosa en el corazón del rey, para honrar la casa de Jehová que está en Jerusalem."}, {"numero": 28, "texto": "E inclinó hacia mí su misericordia delante del rey y de sus consultores, y de todos los príncipes poderosos del rey. Y yo, confortado según la mano de mi Dios sobre mí, junté los principales de Israel para que subiesen conmigo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ef', 2, 'pt', '[{"numero": 1, "texto": "E vós estáveis mortos em ofensas e pecados,"}, {"numero": 2, "texto": "nos quais antes andastes conforme o proceder deste mundo, conforme o príncipe do poder do ar, do espírito que agora opera nos filhos da desobediência."}, {"numero": 3, "texto": "Entre esses também todos nós antes andávamos nos desejos da nossa carne, fazendo a vontade da carne e dos pensamentos; e éramos por natureza filhos da ira, como também os outros."}, {"numero": 4, "texto": "Mas Deus, que é rico em misericórdia, pelo seu muito amor com que nos amou,"}, {"numero": 5, "texto": "estando nós ainda mortos em [nossas] ofensas, nos deu vida juntamente com Cristo (pela graça sois salvos),"}, {"numero": 6, "texto": "[nos] ressuscitou, juntamente [com ele] , e [nos] fez sentar nos lugares celestiais, em Cristo Jesus;"}, {"numero": 7, "texto": "para mostrar nos tempos futuros as abundantes riquezas da sua graça, pela [sua] bondade conosco em Cristo Jesus."}, {"numero": 8, "texto": "Porque pela graça sois salvos, por meio da fé; e isto não [vem] de vós; [é] dom de Deus;"}, {"numero": 9, "texto": "não por obras, para que ninguém tenha orgulho de si mesmo."}, {"numero": 10, "texto": "Pois nós fomos feitos por ele, criados em Cristo Jesus para as boas obras, que Deus preparou para que nelas andássemos."}, {"numero": 11, "texto": "Portanto, lembrai-vos de que vós, antes, éreis gentios na carne, e chamados de não-circuncidados pelos que se chamam participantes da circuncisão na carne, feita por mãos humanas;"}, {"numero": 12, "texto": "que naquele tempo estáveis sem Cristo, excluídos da comunidade de Israel, e estranhos aos pactos da promessa, não tendo esperança, e sem Deus no mundo."}, {"numero": 13, "texto": "Mas agora em Cristo Jesus, vós que antes estáveis longe, chegastes para perto pelo sangue de Cristo,"}, {"numero": 14, "texto": "pois ele é a nossa paz. Dos dois [povos] ele fez um, e derrubou do meio o muro da separação."}, {"numero": 15, "texto": "Na sua carne ele desfez a inimizade da Lei dos mandamentos [que consistia] em ordenanças, para criar em si mesmo os dois em um novo homem, fazendo a paz;"}, {"numero": 16, "texto": "e pela cruz reconciliar com Deus a ambos num só corpo, matando nela a inimizade."}, {"numero": 17, "texto": "Ele veio, e proclamou o evangelho da paz a vós que [estáveis] longe, e aos que estavam perto."}, {"numero": 18, "texto": "Pois por meio dele ambos temos acesso ao Pai por um [mesmo] Espírito."}, {"numero": 19, "texto": "Portanto, já não sois estrangeiros, nem forasteiros, mas sim, concidadãos dos santos, e membros da família de Deus,"}, {"numero": 20, "texto": "edificados sobre o fundamento dos apóstolos e dos profetas, do qual Jesus Cristo é a pedra principal da esquina."}, {"numero": 21, "texto": "Nele o edifício todo, bem ajustado, cresce para [ser] um templo santo no Senhor."}, {"numero": 22, "texto": "Nele também vós sois juntamente edificados para [serdes] morada de Deus em Espírito."}]'::jsonb, 'Almeida Livre'),
  ('Ef', 2, 'en', '[{"numero": 1, "texto": "And you hath he quickened, who were dead in trespasses and sins;"}, {"numero": 2, "texto": "Wherein in time past ye walked according to the course of this world, according to the prince of the power of the air, the spirit that now worketh in the children of disobedience:"}, {"numero": 3, "texto": "Among whom also we all had our conversation in times past in the lusts of our flesh, fulfilling the desires of the flesh and of the mind; and were by nature the children of wrath, even as others."}, {"numero": 4, "texto": "But God, who is rich in mercy, for his great love wherewith he loved us,"}, {"numero": 5, "texto": "Even when we were dead in sins, hath quickened us together with Christ, (by grace ye are saved;)"}, {"numero": 6, "texto": "And hath raised us up together, and made us sit together in heavenly places in Christ Jesus:"}, {"numero": 7, "texto": "That in the ages to come he might shew the exceeding riches of his grace in his kindness toward us through Christ Jesus."}, {"numero": 8, "texto": "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:"}, {"numero": 9, "texto": "Not of works, lest any man should boast."}, {"numero": 10, "texto": "For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them."}, {"numero": 11, "texto": "Wherefore remember, that ye being in time past Gentiles in the flesh, who are called Uncircumcision by that which is called the Circumcision in the flesh made by hands;"}, {"numero": 12, "texto": "That at that time ye were without Christ, being aliens from the commonwealth of Israel, and strangers from the covenants of promise, having no hope, and without God in the world:"}, {"numero": 13, "texto": "But now in Christ Jesus ye who sometimes were far off are made nigh by the blood of Christ."}, {"numero": 14, "texto": "For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us;"}, {"numero": 15, "texto": "Having abolished in his flesh the enmity, even the law of commandments contained in ordinances; for to make in himself of twain one new man, so making peace;"}, {"numero": 16, "texto": "And that he might reconcile both unto God in one body by the cross, having slain the enmity thereby:"}, {"numero": 17, "texto": "And came and preached peace to you which were afar off, and to them that were nigh."}, {"numero": 18, "texto": "For through him we both have access by one Spirit unto the Father."}, {"numero": 19, "texto": "Now therefore ye are no more strangers and foreigners, but fellowcitizens with the saints, and of the household of God;"}, {"numero": 20, "texto": "And are built upon the foundation of the apostles and prophets, Jesus Christ himself being the chief corner stone;"}, {"numero": 21, "texto": "In whom all the building fitly framed together groweth unto an holy temple in the Lord:"}, {"numero": 22, "texto": "In whom ye also are builded together for an habitation of God through the Spirit."}]'::jsonb, 'King James Version'),
  ('Ef', 2, 'fr', '[{"numero": 1, "texto": "Vous étiez morts par vos offenses et par vos péchés,"}, {"numero": 2, "texto": "dans lesquels vous marchiez autrefois, selon le train de ce monde, selon le prince de la puissance de l''''air, de l''''esprit qui agit maintenant dans les fils de la rébellion."}, {"numero": 3, "texto": "Nous tous aussi, nous étions de leur nombre, et nous vivions autrefois selon les convoitises de notre chair, accomplissant les volontés de la chair et de nos pensées, et nous étions par nature des enfants de colère, comme les autres..."}, {"numero": 4, "texto": "Mais Dieu, qui est riche en miséricorde, à cause du grand amour dont il nous a aimés,"}, {"numero": 5, "texto": "nous qui étions morts par nos offenses, nous a rendus à la vie avec Christ c''''est par grâce que vous êtes sauvés);"}, {"numero": 6, "texto": "il nous a ressuscités ensemble, et nous a fait asseoir ensemble dans les lieux célestes, en Jésus-Christ,"}, {"numero": 7, "texto": "afin de montrer dans les siècles à venir l''''infinie richesse de sa grâce par sa bonté envers nous en Jésus-Christ."}, {"numero": 8, "texto": "Car c''''est par la grâce que vous êtes sauvés, par le moyen de la foi. Et cela ne vient pas de vous, c''''est le don de Dieu."}, {"numero": 9, "texto": "Ce n''''est point par les oeuvres, afin que personne ne se glorifie."}, {"numero": 10, "texto": "Car nous sommes son ouvrage, ayant été créés en Jésus-Christ pour de bonnes oeuvres, que Dieu a préparées d''''avance, afin que nous les pratiquions."}, {"numero": 11, "texto": "C''''est pourquoi, vous autrefois païens dans la chair, appelés incirconcis par ceux qu''''on appelle circoncis et qui le sont en la chair par la main de l''''homme, souvenez-vous"}, {"numero": 12, "texto": "que vous étiez en ce temps-là sans Christ, privés du droit de cité en Israël, étrangers aux alliances de la promesse, sans espérance et sans Dieu dans le monde."}, {"numero": 13, "texto": "Mais maintenant, en Jésus-Christ, vous qui étiez jadis éloignés, vous avez été rapprochés par le sang de Christ."}, {"numero": 14, "texto": "Car il est notre paix, lui qui des deux n''''en a fait qu''''un, et qui a renversé le mur de séparation,"}, {"numero": 15, "texto": "l''''inimitié, ayant anéanti par sa chair la loi des ordonnances dans ses prescriptions, afin de créer en lui-même avec les deux un seul homme nouveau, en établissant la paix,"}, {"numero": 16, "texto": "et de les réconcilier, l''''un et l''''autre en un seul corps, avec Dieu par la croix, en détruisant par elle l''''inimitié."}, {"numero": 17, "texto": "Il est venu annoncer la paix à vous qui étiez loin, et la paix à ceux qui étaient près;"}, {"numero": 18, "texto": "car par lui nous avons les uns et les autres accès auprès du Père, dans un même Esprit."}, {"numero": 19, "texto": "Ainsi donc, vous n''''êtes plus des étrangers, ni des gens du dehors; mais vous êtes concitoyens des saints, gens de la maison de Dieu."}, {"numero": 20, "texto": "Vous avez été édifiés sur le fondement des apôtres et des prophètes, Jésus-Christ lui-même étant la pierre angulaire."}, {"numero": 21, "texto": "En lui tout l''''édifice, bien coordonné, s''''élève pour être un temple saint dans le Seigneur."}, {"numero": 22, "texto": "En lui vous êtes aussi édifiés pour être une habitation de Dieu en Esprit."}]'::jsonb, 'Louis Segond 1910'),
  ('Ef', 2, 'es', '[{"numero": 1, "texto": "Y DE ella recibisteis vosotros, que estabais muertos en vuestros delitos y pecados,"}, {"numero": 2, "texto": "En que en otro tiempo anduvisteis conforme á la condición de este mundo, conforme al príncipe de la potestad del aire, el espíritu que ahora obra en los hijos de desobediencia:"}, {"numero": 3, "texto": "Entre los cuales todos nosotros también vivimos en otro tiempo en los deseos de nuestra carne, haciendo la voluntad de la carne y de los pensamientos; y éramos por naturaleza hijos de ira, también como los demás."}, {"numero": 4, "texto": "Empero Dios, que es rico en misericordia, por su mucho amor con que nos amó,"}, {"numero": 5, "texto": "Aun estando nosotros muertos en pecados, nos dió vida juntamente con Cristo; por gracia sois salvos;"}, {"numero": 6, "texto": "Y juntamente nos resucitó, y asimismo nos hizo sentar en los cielos con Cristo Jesús,"}, {"numero": 7, "texto": "Para mostrar en los siglos venideros las abundantes riquezas de su gracia en su bondad para con nosotros en Cristo Jesús."}, {"numero": 8, "texto": "Porque por gracia sois salvos por la fe; y esto no de vosotros, pues es don de Dios:"}, {"numero": 9, "texto": "No por obras, para que nadie se gloríe."}, {"numero": 10, "texto": "Porque somos hechura suya, criados en Cristo Jesús para buenas obras, las cuales Dios preparó para que anduviésemos en ellas."}, {"numero": 11, "texto": "Por tanto, acordaos que en otro tiempo vosotros los Gentiles en la carne, que erais llamados incircuncisión por la que se llama circuncisión, hecha con mano en la carne;"}, {"numero": 12, "texto": "Que en aquel tiempo estabais sin Cristo, alejados de la república de Israel, y extranjeros á los pactos de la promesa, sin esperanza y sin Dios en el mundo."}, {"numero": 13, "texto": "Mas ahora en Cristo Jesús, vosotros que en otro tiempo estabais lejos, habéis sido hechos cercanos por la sangre de Cristo."}, {"numero": 14, "texto": "Porque él es nuestra paz, que de ambos hizo uno, derribando la pared intermedia de separación;"}, {"numero": 15, "texto": "Dirimiendo en su carne las enemistades, la ley de los mandamientos en orden á ritos, para edificar en sí mismo los dos en un nuevo hombre, haciendo la paz,"}, {"numero": 16, "texto": "Y reconciliar por la cruz con Dios á ambos en un mismo cuerpo, matando en ella las enemistades."}, {"numero": 17, "texto": "Y vino, y anunció la paz á vosotros que estabais lejos, y á los que estaban cerca:"}, {"numero": 18, "texto": "Que por él los unos y los otros tenemos entrada por un mismo Espíritu al Padre."}, {"numero": 19, "texto": "Así que ya no sois extranjeros ni advenedizos, sino juntamente ciudadanos con los santos, y domésticos de Dios;"}, {"numero": 20, "texto": "Edificados sobre el fundamento de los apóstoles y profetas, siendo la principal piedra del ángulo Jesucristo mismo;"}, {"numero": 21, "texto": "En el cual, compaginado todo el edificio, va creciendo para ser un templo santo en el Señor:"}, {"numero": 22, "texto": "En el cual vosotros también sois juntamente edificados, para morada de Dios en Espíritu."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ef', 6, 'pt', '[{"numero": 1, "texto": "Filhos, sede obedientes aos vossos pais no Senhor, porque isso é justo."}, {"numero": 2, "texto": "Honra teu pai, e [tua] mãe (que é o primeiro mandamento com promessa);"}, {"numero": 3, "texto": "para que te vá bem, e vivas muito tempo sobre a terra."}, {"numero": 4, "texto": "Pais, não provoqueis à ira os vossos filhos, mas criai-os na disciplina e correção do Senhor."}, {"numero": 5, "texto": "Servos, obedecei aos [vossos] senhores segundo a carne, com temor e tremor, em sinceridade do vosso coração, assim como a Cristo;"}, {"numero": 6, "texto": "não servindo somente quando vistos, como para agradar pessoas; mas sim, como servos de Cristo, fazendo de coração a vontade de Deus;"}, {"numero": 7, "texto": "servindo de boa vontade como ao Senhor, e não aos pessoas."}, {"numero": 8, "texto": "Pois sabeis que cada um receberá do Senhor todo o bem que fizer, seja servo, seja livre."}, {"numero": 9, "texto": "Senhores, fazei o mesmo a eles, abandonando as ameaças, pois sabeis também que o Senhor vosso e deles está nos céus, e [que] com ele não há acepção de pessoas."}, {"numero": 10, "texto": "Por fim, meus irmãos, fortalecei-vos no Senhor e na força do seu poder."}, {"numero": 11, "texto": "Revesti-vos de toda a armadura de Deus, para que possais estar firmes contra as ciladas do diabo."}, {"numero": 12, "texto": "Pois temos de lutar não contra carne e sangue, mas sim contra os domínios e poderes, contra os senhores das trevas deste mundo, contra os males espirituais nos lugares celestes."}, {"numero": 13, "texto": "Portanto pegai toda a armadura de Deus, para que possais resistir no dia mal, e depois que fizerdes tudo, continuar firmes."}, {"numero": 14, "texto": "Estai, pois, firmes, com a vossa cintura envolvida com o cinturão da verdade, e vestidos com a couraça da justiça;"}, {"numero": 15, "texto": "e calçados os pés com a prontidão do evangelho da paz."}, {"numero": 16, "texto": "Sobretudo pegai o escudo da fé, com o qual podereis apagar todas as flechas inflamadas do maligno."}, {"numero": 17, "texto": "Pegai também o capacete da salvação, e a espada do Espírito, que é a palavra de Deus;"}, {"numero": 18, "texto": "orando em todo tempo com toda oração e súplica no Espírito, e vigiando nisso com toda perseverança e súplica por todos os santos,"}, {"numero": 19, "texto": "e por mim; a fim de que, quando eu abrir a boca, me seja dada palavra com ousadia, para tornar conhecido o mistério do evangelho,"}, {"numero": 20, "texto": "pelo qual sou embaixador acorrentado; para que dele eu possa falar com ousadia, como devo falar."}, {"numero": 21, "texto": "Para que também vós possais saber o que acontece comigo, [e] o que eu faço, Tíquico, o irmão amado, e fiel servidor do Senhor vos informará de tudo."}, {"numero": 22, "texto": "Eu o enviei até vós para isso, para que saibais o que acontece conosco, e ele conforte os vossos corações."}, {"numero": 23, "texto": "Paz [seja] com os irmãos, e amor com fé, da parte de Deus Pai, e do Senhor Jesus Cristo."}, {"numero": 24, "texto": "A graça [seja] com todos os que amam ao nosso Senhor Jesus Cristo com amor que não falha. Amém![Escrita de Roma para os efésios, e enviada por Tíquico]"}]'::jsonb, 'Almeida Livre'),
  ('Ef', 6, 'en', '[{"numero": 1, "texto": "Children, obey your parents in the Lord: for this is right."}, {"numero": 2, "texto": "Honour thy father and mother; which is the first commandment with promise;"}, {"numero": 3, "texto": "That it may be well with thee, and thou mayest live long on the earth."}, {"numero": 4, "texto": "And, ye fathers, provoke not your children to wrath: but bring them up in the nurture and admonition of the Lord."}, {"numero": 5, "texto": "Servants, be obedient to them that are your masters according to the flesh, with fear and trembling, in singleness of your heart, as unto Christ;"}, {"numero": 6, "texto": "Not with eyeservice, as menpleasers; but as the servants of Christ, doing the will of God from the heart;"}, {"numero": 7, "texto": "With good will doing service, as to the Lord, and not to men:"}, {"numero": 8, "texto": "Knowing that whatsoever good thing any man doeth, the same shall he receive of the Lord, whether he be bond or free."}, {"numero": 9, "texto": "And, ye masters, do the same things unto them, forbearing threatening: knowing that your Master also is in heaven; neither is there respect of persons with him."}, {"numero": 10, "texto": "Finally, my brethren, be strong in the Lord, and in the power of his might."}, {"numero": 11, "texto": "Put on the whole armour of God, that ye may be able to stand against the wiles of the devil."}, {"numero": 12, "texto": "For we wrestle not against flesh and blood, but against principalities, against powers, against the rulers of the darkness of this world, against spiritual wickedness in high places."}, {"numero": 13, "texto": "Wherefore take unto you the whole armour of God, that ye may be able to withstand in the evil day, and having done all, to stand."}, {"numero": 14, "texto": "Stand therefore, having your loins girt about with truth, and having on the breastplate of righteousness;"}, {"numero": 15, "texto": "And your feet shod with the preparation of the gospel of peace;"}, {"numero": 16, "texto": "Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked."}, {"numero": 17, "texto": "And take the helmet of salvation, and the sword of the Spirit, which is the word of God:"}, {"numero": 18, "texto": "Praying always with all prayer and supplication in the Spirit, and watching thereunto with all perseverance and supplication for all saints;"}, {"numero": 19, "texto": "And for me, that utterance may be given unto me, that I may open my mouth boldly, to make known the mystery of the gospel,"}, {"numero": 20, "texto": "For which I am an ambassador in bonds: that therein I may speak boldly, as I ought to speak."}, {"numero": 21, "texto": "But that ye also may know my affairs, and how I do, Tychicus, a beloved brother and faithful minister in the Lord, shall make known to you all things:"}, {"numero": 22, "texto": "Whom I have sent unto you for the same purpose, that ye might know our affairs, and that he might comfort your hearts."}, {"numero": 23, "texto": "Peace be to the brethren, and love with faith, from God the Father and the Lord Jesus Christ."}, {"numero": 24, "texto": "Grace be with all them that love our Lord Jesus Christ in sincerity. Amen."}]'::jsonb, 'King James Version'),
  ('Ef', 6, 'fr', '[{"numero": 1, "texto": "Enfants, obéissez à vos parents, selon le Seigneur, car cela est juste."}, {"numero": 2, "texto": "Honore ton père et ta mère c''''est le premier commandement avec une promesse,"}, {"numero": 3, "texto": "afin que tu sois heureux et que tu vives longtemps sur la terre."}, {"numero": 4, "texto": "Et vous, pères, n''''irritez pas vos enfants, mais élevez-les en les corrigeant et en les instruisant selon le Seigneur."}, {"numero": 5, "texto": "Serviteurs, obéissez à vos maîtres selon la chair, avec crainte et tremblement, dans la simplicité de votre coeur, comme à Christ,"}, {"numero": 6, "texto": "non pas seulement sous leurs yeux, comme pour plaire aux hommes, mais comme des serviteurs de Christ, qui font de bon coeur la volonté de Dieu."}, {"numero": 7, "texto": "Servez-les avec empressement, comme servant le Seigneur et non des hommes,"}, {"numero": 8, "texto": "sachant que chacun, soit esclave, soit libre, recevra du Seigneur selon ce qu''''il aura fait de bien."}, {"numero": 9, "texto": "Et vous, maîtres, agissez de même à leur égard, et abstenez-vous de menaces, sachant que leur maître et le vôtre est dans les cieux, et que devant lui il n''''y a point d''''acception de personnes."}, {"numero": 10, "texto": "Au reste, fortifiez-vous dans le Seigneur, et par sa force toute-puissante."}, {"numero": 11, "texto": "Revêtez-vous de toutes les armes de Dieu, afin de pouvoir tenir ferme contre les ruses du diable."}, {"numero": 12, "texto": "Car nous n''''avons pas à lutter contre la chair et le sang, mais contre les dominations, contre les autorités, contre les princes de ce monde de ténèbres, contre les esprits méchants dans les lieux célestes."}, {"numero": 13, "texto": "C''''est pourquoi, prenez toutes les armes de Dieu, afin de pouvoir résister dans le mauvais jour, et tenir ferme après avoir tout surmonté."}, {"numero": 14, "texto": "Tenez donc ferme: ayez à vos reins la vérité pour ceinture; revêtez la cuirasse de la justice;"}, {"numero": 15, "texto": "mettez pour chaussure à vos pieds le zèle que donne l''''Evangile de paix;"}, {"numero": 16, "texto": "prenez par-dessus tout cela le bouclier de la foi, avec lequel vous pourrez éteindre tous les traits enflammés du malin;"}, {"numero": 17, "texto": "prenez aussi le casque du salut, et l''''épée de l''''Esprit, qui est la parole de Dieu."}, {"numero": 18, "texto": "Faites en tout temps par l''''Esprit toutes sortes de prières et de supplications. Veillez à cela avec une entière persévérance, et priez pour tous les saints."}, {"numero": 19, "texto": "Priez pour moi, afin qu''''il me soit donné, quand j''''ouvre la bouche, de faire connaître hardiment et librement le mystère de l''''Evangile,"}, {"numero": 20, "texto": "pour lequel je suis ambassadeur dans les chaînes, et que j''''en parle avec assurance comme je dois en parler."}, {"numero": 21, "texto": "Afin que vous aussi, vous sachiez ce qui me concerne, ce que je fais, Tychique, le bien-aimé frère et fidèle ministre dans le Seigneur, vous informera de tout."}, {"numero": 22, "texto": "Je l''''envoie exprès vers vous, pour que vous connaissiez notre situation, et pour qu''''il console vos coeurs."}, {"numero": 23, "texto": "Que la paix et la charité avec la foi soient données aux frères de la part de Dieu le Père et du Seigneur Jésus-Christ!"}, {"numero": 24, "texto": "Que la grâce soit avec tous ceux qui aiment notre Seigneur Jésus-Christ d''''un amour inaltérable!"}]'::jsonb, 'Louis Segond 1910'),
  ('Ef', 6, 'es', '[{"numero": 1, "texto": "HIJOS, obedeced en el Señor á vuestros padres; porque esto es justo."}, {"numero": 2, "texto": "Honra á tu padre y á tu madre, que es el primer mandamiento con promesa,"}, {"numero": 3, "texto": "Para que te vaya bien, y seas de larga vida sobre la tierra."}, {"numero": 4, "texto": "Y vosotros, padres, no provoquéis á ira á vuestros hijos; sino criadlos en disciplina y amonestación del Señor."}, {"numero": 5, "texto": "Siervos, obedeced á vuestros amos según la carne con temor y temblor, con sencillez de vuestro corazón, como á Cristo;"}, {"numero": 6, "texto": "No sirviendo al ojo, como los que agradan á los hombres; sino como siervos de Cristo, haciendo de ánimo la voluntad de Dios;"}, {"numero": 7, "texto": "Sirviendo con buena voluntad, como al Señor, y no á los hombres;"}, {"numero": 8, "texto": "Sabiendo que el bien que cada uno hiciere, esto recibirá del Señor, sea siervo ó sea libre."}, {"numero": 9, "texto": "Y vosotros, amos, haced á ellos lo mismo, dejando las amenazas: sabiendo que el Señor de ellos y vuestro está en los cielos, y que no hay acepción de personas con él."}, {"numero": 10, "texto": "Por lo demás, hermanos míos, confortaos en el Señor, y en la potencia de su fortaleza."}, {"numero": 11, "texto": "Vestíos de toda la armadura de Dios, para que podáis estar firmes contra las asechanzas del diablo."}, {"numero": 12, "texto": "Porque no tenemos lucha contra sangre y carne; sino contra principados, contra potestades, contra señores del mundo, gobernadores de estas tinieblas, contra malicias espirituales en los aires."}, {"numero": 13, "texto": "Por tanto, tomad toda la armadura de Dios, para que podáis resistir en el día malo, y estar firmes, habiendo acabado todo."}, {"numero": 14, "texto": "Estad pues firmes, ceñidos vuestros lomos de verdad, y vestidos de la cota de justicia,"}, {"numero": 15, "texto": "Y calzados los pies con el apresto del evangelio de paz;"}, {"numero": 16, "texto": "Sobre todo, tomando el escudo de la fe, con que podáis apagar todos los dardos de fuego del maligno."}, {"numero": 17, "texto": "Y tomad el yelmo de salud, y la espada del Espíritu; que es la palabra de Dios;"}, {"numero": 18, "texto": "Orando en todo tiempo con toda deprecación y súplica en el Espíritu, y velando en ello con toda instancia y suplicación por todos los santos,"}, {"numero": 19, "texto": "Y por mí, para que me sea dada palabra en el abrir de mi boca con confianza, para hacer notorio el misterio del evangelio,"}, {"numero": 20, "texto": "Por el cual soy embajador en cadenas; que resueltamente hable de él, como debo hablar."}, {"numero": 21, "texto": "Mas para que también vosotros sepáis mis negocios, y cómo lo paso, todo os lo hará saber Tichîco, hermano amado y fiel ministro en el Señor:"}, {"numero": 22, "texto": "Al cual os he enviado para esto mismo, para que entendáis lo tocante á nosotros, y que consuele vuestros corazones."}, {"numero": 23, "texto": "Paz sea á los hermanos y amor con fe, de Dios Padre y del Señor Jesucristo."}, {"numero": 24, "texto": "Gracia sea con todos los que aman á nuestro Señor Jesucristo en sinceridad. Amén.  Escrita de Roma á los Efesios por Tichîco."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 1, 'pt', '[{"numero": 1, "texto": "E aconteceu nos dias de Assuero (o Assuero que reinou desde a Índia até Cuxe sobre cento e vinte e sete províncias),"}, {"numero": 2, "texto": "Que naqueles dias, quando o rei Assuero se sentou sobre o trono de seu reino, na fortaleza de Susã,"}, {"numero": 3, "texto": "No terceiro ano de seu reinado, ele fez um banquete a todos seus príncipes e a seus servos, tendo diante dele o exército de Pérsia e da Média, os maiorais e os governadores das províncias,"}, {"numero": 4, "texto": "Para mostrar as riquezas da glória de seu reino, e o esplendor de sua majestosa grandeza, por muitos dias: cento e oitenta dias."}, {"numero": 5, "texto": "E acabados aqueles dias, o rei fez um banquete a todo o povo que se achava na fortaleza de Susã, desde o maior até o menor, durante sete dias, no pátio do jardim do palácio real."}, {"numero": 6, "texto": "[As cortinas eram] de linho branco e azul celeste, amarradas com cordões de linho fino e púrpura, argolas de prata e colunas de mármore; os leitos eram de ouro e de prata, sobre um piso de pórfiro , mármore, madrepérola e pedras preciosas."}, {"numero": 7, "texto": "E dava-se de beber em taças de ouro, e as taças eram diferentes umas das outras; e havia muito vinho real, conforme a generosidade do rei."}, {"numero": 8, "texto": "E de acordo com a lei, a bebida era sem restrições; porque assim o rei tinha mandado a todos os oficiais de sua casa; que fizessem conforme a vontade de cada um."}, {"numero": 9, "texto": "Também a rainha Vasti fez banquete para as mulheres, na casa real do rei Assuero."}, {"numero": 10, "texto": "No sétimo dia, quando o coração do rei estava alegre do vinho, mandou a Meumã, Bizta, Harbona, Bigtá, Abagta, Zetar, e Carcas, sete eunucos que serviam diante do rei Assuero,"}, {"numero": 11, "texto": "Que trouxessem à rainha Vasti com a coroa real diante do rei, para mostrar aos povos e aos príncipes sua beleza; pois ela tinha linda aparência."}, {"numero": 12, "texto": "Porém a rainha Vasti recusou vir à ordem do rei por meio dos eunucos; por isso o rei se enfureceu muito, e sua ira se acendeu nele."}, {"numero": 13, "texto": "Então o rei perguntou aos sábios que entendiam dos tempos (porque assim era o costume do rei para com todos os que sabiam a lei e o direito;"}, {"numero": 14, "texto": "E os mais próximos dele eram Carsena, Setar, Adamata, Társis, Meres, Marsena, e Memucã, sete príncipes da Pérsia e da Média, que viam o rosto do rei, e se sentavam nas [posições] principais do reino)"}, {"numero": 15, "texto": "O que se devia fazer segundo a lei com a rainha Vasti, por não ter cumprido a ordem do rei Assuero por meio dos eunucos."}, {"numero": 16, "texto": "Então Memucã disse na presença do rei e dos príncipes: A rainha Vasti pecou não somente contra o rei, mas também contra todos os príncipes, e contra todos os povos que há em todas as províncias do rei Assuero."}, {"numero": 17, "texto": "Pois o que a rainha fez será notícia a todas as mulheres, de modo que desprezarão seus maridos em seus olhos, quando lhes for dito: O rei Assuero mandou trazer diante de si à rainha Vasti, porém ela não veio."}, {"numero": 18, "texto": "Então neste dia as princesas da Pérsia e da Média dirão [o mesmo] a todos os príncipes do rei, quando ouvirem o que a rainha fez; e [assim] haverá muito desprezo e indignação."}, {"numero": 19, "texto": "Se for do agrado do rei, seja feito de sua parte um mandamento real, e escreva-se nas leis da Pérsia e da Média, e que não se possa revogar: que Vasti nunca mais venha diante do rei Assuero; e o reino dela seja dado a outra que seja melhor que ela."}, {"numero": 20, "texto": "E quando o mandamento que o rei ordenar for ouvido em todo o seu reino (ainda que seja grande), todas as mulheres darão honra a seus maridos, desde o maior até o menor."}, {"numero": 21, "texto": "E esta palavra foi do agrado dos olhos do rei e dos príncipes, e o rei fez conforme o que Memucã havia dito;"}, {"numero": 22, "texto": "Então enviou cartas a todas a províncias do rei, a cada província segundo sua escrita, e a cada povo segundo sua língua, que todo homem fosse senhor em sua casa, e falasse isto conforme a língua de cada povo."}]'::jsonb, 'Almeida Livre'),
  ('Et', 1, 'en', '[{"numero": 1, "texto": "Now it came to pass in the days of Ahasuerus, (this is Ahasuerus which reigned, from India even unto Ethiopia, over an hundred and seven and twenty provinces:)"}, {"numero": 2, "texto": "That in those days, when the king Ahasuerus sat on the throne of his kingdom, which was in Shushan the palace,"}, {"numero": 3, "texto": "In the third year of his reign, he made a feast unto all his princes and his servants; the power of Persia and Media, the nobles and princes of the provinces, being before him:"}, {"numero": 4, "texto": "When he shewed the riches of his glorious kingdom and the honour of his excellent majesty many days, even an hundred and fourscore days."}, {"numero": 5, "texto": "And when these days were expired, the king made a feast unto all the people that were present in Shushan the palace, both unto great and small, seven days, in the court of the garden of the king''s palace;"}, {"numero": 6, "texto": "Where were white, green, and blue, hangings, fastened with cords of fine linen and purple to silver rings and pillars of marble: the beds were of gold and silver, upon a pavement of red, and blue, and white, and black, marble."}, {"numero": 7, "texto": "And they gave them drink in vessels of gold, (the vessels being diverse one from another,) and royal wine in abundance, according to the state of the king."}, {"numero": 8, "texto": "And the drinking was according to the law; none did compel: for so the king had appointed to all the officers of his house, that they should do according to every man''s pleasure."}, {"numero": 9, "texto": "Also Vashti the queen made a feast for the women in the royal house which belonged to king Ahasuerus."}, {"numero": 10, "texto": "On the seventh day, when the heart of the king was merry with wine, he commanded Mehuman, Biztha, Harbona, Bigtha, and Abagtha, Zethar, and Carcas, the seven chamberlains that served in the presence of Ahasuerus the king,"}, {"numero": 11, "texto": "To bring Vashti the queen before the king with the crown royal, to shew the people and the princes her beauty: for she was fair to look on."}, {"numero": 12, "texto": "But the queen Vashti refused to come at the king''s commandment by his chamberlains: therefore was the king very wroth, and his anger burned in him."}, {"numero": 13, "texto": "Then the king said to the wise men, which knew the times, (for so was the king''s manner toward all that knew law and judgment:"}, {"numero": 14, "texto": "And the next unto him was Carshena, Shethar, Admatha, Tarshish, Meres, Marsena, and Memucan, the seven princes of Persia and Media, which saw the king''s face, and which sat the first in the kingdom;)"}, {"numero": 15, "texto": "What shall we do unto the queen Vashti according to law, because she hath not performed the commandment of the king Ahasuerus by the chamberlains?"}, {"numero": 16, "texto": "And Memucan answered before the king and the princes, Vashti the queen hath not done wrong to the king only, but also to all the princes, and to all the people that are in all the provinces of the king Ahasuerus."}, {"numero": 17, "texto": "For this deed of the queen shall come abroad unto all women, so that they shall despise their husbands in their eyes, when it shall be reported, The king Ahasuerus commanded Vashti the queen to be brought in before him, but she came not."}, {"numero": 18, "texto": "Likewise shall the ladies of Persia and Media say this day unto all the king''s princes, which have heard of the deed of the queen. Thus shall there arise too much contempt and wrath."}, {"numero": 19, "texto": "If it please the king, let there go a royal commandment from him, and let it be written among the laws of the Persians and the Medes, that it be not altered, That Vashti come no more before king Ahasuerus; and let the king give her royal estate unto another that is better than she."}, {"numero": 20, "texto": "And when the king''s decree which he shall make shall be published throughout all his empire, (for it is great,) all the wives shall give to their husbands honour, both to great and small."}, {"numero": 21, "texto": "And the saying pleased the king and the princes; and the king did according to the word of Memucan:"}, {"numero": 22, "texto": "For he sent letters into all the king''s provinces, into every province according to the writing thereof, and to every people after their language, that every man should bear rule in his own house, and that it should be published according to the language of every people."}]'::jsonb, 'King James Version'),
  ('Et', 1, 'fr', '[{"numero": 1, "texto": "C''''était du temps d''''Assuérus, de cet Assuérus qui régnait depuis l''''Inde jusqu''''en Ethiopie sur cent vingt-sept provinces;"}, {"numero": 2, "texto": "et le roi Assuérus était alors assis sur son trône royal à Suse, dans la capitale."}, {"numero": 3, "texto": "La troisième année de son règne, il fit un festin à tous ses princes et à ses serviteurs; les commandants de l''''armée des Perses et des Mèdes, les grands et les chefs des provinces furent réunis en sa présence."}, {"numero": 4, "texto": "Il montra la splendide richesse de son royaume et l''''éclatante magnificence de sa grandeur pendant nombre de jours, pendant cent quatre-vingts jours."}, {"numero": 5, "texto": "Lorsque ces jours furent écoulés, le roi fit pour tout le peuple qui se trouvait à Suse, la capitale, depuis le plus grand jusqu''''au plus petit, un festin qui dura sept jours, dans la cour du jardin de la maison royale."}, {"numero": 6, "texto": "Des tentures blanches, vertes et bleues, étaient attachées par des cordons de byssus et de pourpre à des anneaux d''''argent et à des colonnes de marbre. Des lits d''''or et d''''argent reposaient sur un pavé de porphyre, de marbre, de nacre et de pierres noires."}, {"numero": 7, "texto": "On servait à boire dans des vases d''''or, de différentes espèces, et il y avait abondance de vin royal, grâce à la libéralité du roi."}, {"numero": 8, "texto": "Mais on ne forçait personne à boire, car le roi avait ordonné à tous les gens de sa maison de se conformer à la volonté de chacun."}, {"numero": 9, "texto": "La reine Vasthi fit aussi un festin pour les femmes dans la maison royale du roi Assuérus."}, {"numero": 10, "texto": "Le septième jour, comme le coeur du roi était réjoui par le vin, il ordonna à Mehuman, Biztha, Harbona, Bigtha, Abagtha, Zéthar et Carcas, les sept eunuques qui servaient devant le roi Assuérus,"}, {"numero": 11, "texto": "d''''amener en sa présence la reine Vasthi, avec la couronne royale, pour montrer sa beauté aux peuples et aux grands, car elle était belle de figure."}, {"numero": 12, "texto": "Mais la reine Vasthi refusa de venir, quand elle reçut par les eunuques l''''ordre du roi. Et le roi fut très irrité, il fut enflammé de colère."}, {"numero": 13, "texto": "Alors le roi s''''adressa aux sages qui avaient la connaissance des temps. Car ainsi se traitaient les affaires du roi, devant tous ceux qui connaissaient les lois et le droit."}, {"numero": 14, "texto": "Il avait auprès de lui Carschena, Schéthar, Admatha, Tarsis, Mérès, Marsena, Memucan, sept princes de Perse et de Médie, qui voyaient la face du roi et qui occupaient le premier rang dans le royaume."}, {"numero": 15, "texto": "Quelle loi, dit-il, faut-il appliquer à la reine Vasthi, pour n''''avoir point exécuté ce que le roi Assuérus lui a ordonné par les eunuques?"}, {"numero": 16, "texto": "Memucan répondit devant le roi et les princes: Ce n''''est pas seulement à l''''égard du roi que la reine Vasthi a mal agi; c''''est aussi envers tous les princes et tous les peuples qui sont dans toutes les provinces du roi Assuérus."}, {"numero": 17, "texto": "Car l''''action de la reine parviendra à la connaissance de toutes les femmes, et les portera à mépriser leurs maris; elles diront: Le roi Assuérus avait ordonné qu''''on amenât en sa présence la reine Vasthi, et elle n''''y est pas allée."}, {"numero": 18, "texto": "Et dès ce jour les princesses de Perse et de Médie qui auront appris l''''action de la reine la rapporteront à tous les chefs du roi; de là beaucoup de mépris et de colère."}, {"numero": 19, "texto": "Si le roi le trouve bon, qu''''on publie de sa part et qu''''on inscrive parmi les lois des Perses et des Mèdes, avec défense de la transgresser, une ordonnance royale d''''après laquelle Vasthi ne paraîtra plus devant le roi Assuérus et le roi donnera la dignité de reine à une autre qui soit meilleure qu''''elle."}, {"numero": 20, "texto": "L''''édit du roi sera connu dans tout son royaume, quelque grand qu''''il soit, et toutes les femmes rendront honneur à leurs maris, depuis le plus grand jusqu''''au plus petit."}, {"numero": 21, "texto": "Cet avis fut approuvé du roi et des princes, et le roi agit d''''après la parole de Memucan."}, {"numero": 22, "texto": "Il envoya des lettres à toutes les provinces du royaume, à chaque province selon son écriture et à chaque peuple selon sa langue; elles portaient que tout homme devait être le maître dans sa maison, et qu''''il parlerait la langue de son peuple."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 1, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ en los días de Assuero, (el Assuero que reinó desde la India hasta la Etiopía sobre ciento veinte y siete provincias,)"}, {"numero": 2, "texto": "Que en aquellos días, asentado que fué el rey Assuero en la silla de su reino, la cual estaba en Susán capital del reino,"}, {"numero": 3, "texto": "En el tercer año de su reinado hizo banquete á todos sus príncipes y siervos, teniendo delante de él la fuerza de Persia y de Media, gobernadores y príncipes de provincias,"}, {"numero": 4, "texto": "Para mostrar él las riquezas de la gloria de su reino, y el lustre de la magnificencia de su poder, por muchos días, ciento y ochenta días."}, {"numero": 5, "texto": "Y cumplidos estos días, hizo el rey banquete por siete días en el patio del huerto del palacio real á todo el pueblo, desde el mayor hasta el menor que se halló en Susán capital del reino."}, {"numero": 6, "texto": "El pabellón era de blanco, verde, y cárdeno, tendido sobre cuerdas de lino y púrpura en sortijas de plata y columnas de mármol: los reclinatorios de oro y de plata, sobre losado de pórfido y de mármol, y de alabastro y de jacinto."}, {"numero": 7, "texto": "Y daban á beber en vasos de oro, y vasos diferentes unos de otros, y mucho vino real, conforme á la facultad del rey."}, {"numero": 8, "texto": "Y la bebida fué según esta ley: Que nadie constriñese; porque así lo había mandado el rey á todos los mayordomos de su casa; que se hiciese según la voluntad de cada uno."}, {"numero": 9, "texto": "Asimismo la reina Vasthi hizo banquete de mujeres, en la casa real del rey Assuero."}, {"numero": 10, "texto": "El séptimo día, estando el corazón del rey alegre del vino, mandó á Mehumán, y á Biztha, y á Harbona, y á Bigtha, y á Abagtha, y á Zetar, y á Carcas, siete eunucos que servían delante del rey Assuero,"}, {"numero": 11, "texto": "Que trajesen á la reina Vasthi delante del rey con la corona regia, para mostrar á los pueblos y á los príncipes su hermosura; porque era linda de aspecto."}, {"numero": 12, "texto": "Mas la reina Vasthi no quiso comparecer á la orden del rey, enviada por mano de los eunucos; y enojóse el rey muy mucho, y encendióse en él su ira."}, {"numero": 13, "texto": "Preguntó entonces el rey á los sabios que sabían los tiempos, (porque así era la costumbre del rey para con todos los que sabían la ley y el derecho;"}, {"numero": 14, "texto": "Y estaban junto á él, Carsena, y Sethar, y Admatha, y Tharsis, y Meres, y Marsena, y Memucán, siete príncipes de Persia y de Media que veían la cara del rey, y se sentaban los primeros del reino:)"}, {"numero": 15, "texto": "Qué se había de hacer según la ley con la reina Vasthi, por cuanto no había cumplido la orden del rey Assuero, enviada por mano de los eunucos."}, {"numero": 16, "texto": "Y dijo Memucán delante del rey y de los príncipes: No solamente contra el rey ha pecado la reina Vasthi, sino contra todos los príncipes, y contra todos los pueblos que hay en todas las provincias del rey Assuero."}, {"numero": 17, "texto": "Porque este hecho de la reina pasará á noticia de todas las mujeres, para hacerles tener en poca estima á sus maridos, diciendo: El rey Assuero mandó traer delante de sí á la reina Vasthi, y ella no vino."}, {"numero": 18, "texto": "Y entonces dirán esto las señoras de Persia y de Media que oyeren el hecho de la reina, á todos los príncipes del rey: y habrá mucho menosprecio y enojo."}, {"numero": 19, "texto": "Si parece bien al rey, salga mandamiento real delante de él, y escríbase entre las leyes de Persia y de Media, y no sea traspasado: Que no venga más Vasthi delante del rey Assuero: y dé el rey su reino á su compañera que sea mejor que ella."}, {"numero": 20, "texto": "Y el mandamiento que hará el rey será oído en todo su reino, aunque es grande, y todas las mujeres darán honra á sus maridos, desde el mayor hasta el menor."}, {"numero": 21, "texto": "Y plugo esta palabra en ojos del rey y de los príncipes, é hizo el rey conforme al dicho de Memucán;"}, {"numero": 22, "texto": "Pues envió letras á todas las provincias del rey, á cada provincia conforme á su escribir, y á cada pueblo conforme á su lenguaje, diciendo que todo hombre fuese señor en su casa; y háblese esto según la lengua de su pueblo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 2, 'pt', '[{"numero": 1, "texto": "Passadas estas coisas, e tendo já sido apaziguado o furor do rei Assuero, ele se lembrou de Vasti, e do que ela havia feito, e do que havia sido sentenciado contra ela."}, {"numero": 2, "texto": "Então os servos do rei, que lhe serviam, disseram: Busquem-se ao rei moças virgens de boa aparência;"}, {"numero": 3, "texto": "E o rei ponha comissários em todas as províncias de seu reino, para que juntem todas as moças virgens de boa aparência na fortaleza de Susã, na casa das mulheres, ao cuidado de Hegai, eunuco do rei, vigilante das mulheres; e sejam lhes dado seus enfeites;"}, {"numero": 4, "texto": "E a moça que agradar aos olhos do rei, reine em lugar de Vasti.E isto foi do agrado dos olhos do rei, e ele assim fez."}, {"numero": 5, "texto": "Havia um homem judeu na fortaleza de Susã, cujo nome era Mardoqueu, filho de Jair, filho de Simei, filho de Quis, um homem da [linhagem] de Benjamim;"}, {"numero": 6, "texto": "O qual tinha sido levado de Jerusalém com os cativos que foram levados com Jeconias rei de Judá, a quem Nabucodonosor, rei da Babilônia, havia levado."}, {"numero": 7, "texto": "E ele tinha criado a Hadassa, que é Ester, filha de seu tio, porque não tinha pai nem mãe; e ela tinha bela forma, e era linda de aparência; e como seu pai e sua mãe tinham morrido, Mardoqueu a havia tomado como sua filha."}, {"numero": 8, "texto": "Sucedeu pois, que quando se divulgou o mandamento do rei e seu lei, e sendo reunidas muitas moças na fortaleza de Susã, ao cuidado de Hegai, também levaram Ester para casa do rei, ao cuidado de Hegai, vigilante das mulheres."}, {"numero": 9, "texto": "E a moça foi do agrado de seus olhos, e alcançou favor diante dele; por isso ele se apressou em [lhe dar] seus enfeites e suas porções de alimento, dando-lhe também sete moças escolhidas da casa do rei; e ele a passou com suas moças ao melhor [lugar] da casa das mulheres."}, {"numero": 10, "texto": "Ester, porém, não declarou seu povo nem sua parentela; porque Mardoqueu tinha lhe mandado que não declarasse."}, {"numero": 11, "texto": "E todo dia Mardoqueu passeava diante do pátio da casa das mulheres, para saber como Ester estava, e que estava acontecendo com ela."}, {"numero": 12, "texto": "E quando chegava a vez de cada uma das moças para vir ao rei Assuero, ao fim de haver estado doze meses, conforme à lei acerca das mulheres (porque assim se cumpriam os dias de seus enfeites, isto é, seis meses com óleo de mirra, e seis meses com especiarias, e [outros] enfeites de mulheres),"}, {"numero": 13, "texto": "Então assim a moça vinha ao rei; tudo quanto ela pedia se lhe dava, para vir com isso da casa das mulheres até a casa do rei."}, {"numero": 14, "texto": "Ela vinha à tarde, e pela manhã voltava à segunda casa das mulheres, ao cuidado de Saasgaz eunuco do rei, vigilante das concubinas; ela não voltava mais ao rei, a não ser se o rei a desejasse, e fosse chamada por nome."}, {"numero": 15, "texto": "Chegando, pois, a vez de Ester, filha de Abiail, tio de Mardoqueu (que e havia tinha tomado por filha), para vir ao rei, nenhuma coisa pediu a não ser o que Hegai eunuco do rei, vigilante das mulheres, havia dito; e Ester alcançava o favor aos olhos de todos quantos a viam."}, {"numero": 16, "texto": "Assim Ester foi levada ao rei Assuero a sua casa real no décimo mês, que é o mês de Tebete, no sétimo ano de seu reinado."}, {"numero": 17, "texto": "E o rei amou a Ester mais que todas as mulheres, e alcançou diante dele favor e benevolência mais que todas as virgens; e ele pôs a coroa real em sua cabeça, e a fez rainha em lugar de Vasti."}, {"numero": 18, "texto": "Então o rei fez um grande banquete a todos seus príncipes e servos, o banquete de Ester; e deu repouso às províncias, e deu presentes, conforme a generosidade do rei."}, {"numero": 19, "texto": "E quando as virgens se ajuntaram pela segunda vez, Mardoqueu estava sentado à porta do rei."}, {"numero": 20, "texto": "Ester, [porém] ,não tinha declarado sua parentela nem seu povo, assim como Mardoqueu havia lhe mandado; porque Ester fazia o que Mardoqueu mandava, assim como quando ele a criava."}, {"numero": 21, "texto": "Naqueles dias, estando Mardoqueu sentado à porta do rei, Bigtã e Teres, dois eunucos do rei, dos guardas da porta, ficaram muito indignados, e procuravam matar o rei Assuero."}, {"numero": 22, "texto": "E isso foi percebido por Mardoqueu; então ele avisou à rainha Ester, e Ester disse ao rei em nome de Mardoqueu."}, {"numero": 23, "texto": "Tendo o caso sido investigado, assim foi achado; e ambos foram pendurados em uma forca. E isso foi registrado nas crônicas diante do rei."}]'::jsonb, 'Almeida Livre'),
  ('Et', 2, 'en', '[{"numero": 1, "texto": "After these things, when the wrath of king Ahasuerus was appeased, he remembered Vashti, and what she had done, and what was decreed against her."}, {"numero": 2, "texto": "Then said the king''s servants that ministered unto him, Let there be fair young virgins sought for the king:"}, {"numero": 3, "texto": "And let the king appoint officers in all the provinces of his kingdom, that they may gather together all the fair young virgins unto Shushan the palace, to the house of the women, unto the custody of Hege the king''s chamberlain, keeper of the women; and let their things for purification be given them:"}, {"numero": 4, "texto": "And let the maiden which pleaseth the king be queen instead of Vashti. And the thing pleased the king; and he did so."}, {"numero": 5, "texto": "Now in Shushan the palace there was a certain Jew, whose name was Mordecai, the son of Jair, the son of Shimei, the son of Kish, a Benjamite;"}, {"numero": 6, "texto": "Who had been carried away from Jerusalem with the captivity which had been carried away with Jeconiah king of Judah, whom Nebuchadnezzar the king of Babylon had carried away."}, {"numero": 7, "texto": "And he brought up Hadassah, that is, Esther, his uncle''s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."}, {"numero": 8, "texto": "So it came to pass, when the king''s commandment and his decree was heard, and when many maidens were gathered together unto Shushan the palace, to the custody of Hegai, that Esther was brought also unto the king''s house, to the custody of Hegai, keeper of the women."}, {"numero": 9, "texto": "And the maiden pleased him, and she obtained kindness of him; and he speedily gave her her things for purification, with such things as belonged to her, and seven maidens, which were meet to be given her, out of the king''s house: and he preferred her and her maids unto the best place of the house of the women."}, {"numero": 10, "texto": "Esther had not shewed her people nor her kindred: for Mordecai had charged her that she should not shew it."}, {"numero": 11, "texto": "And Mordecai walked every day before the court of the women''s house, to know how Esther did, and what should become of her."}, {"numero": 12, "texto": "Now when every maid''s turn was come to go in to king Ahasuerus, after that she had been twelve months, according to the manner of the women, (for so were the days of their purifications accomplished, to wit, six months with oil of myrrh, and six months with sweet odours, and with other things for the purifying of the women;)"}, {"numero": 13, "texto": "Then thus came every maiden unto the king; whatsoever she desired was given her to go with her out of the house of the women unto the king''s house."}, {"numero": 14, "texto": "In the evening she went, and on the morrow she returned into the second house of the women, to the custody of Shaashgaz, the king''s chamberlain, which kept the concubines: she came in unto the king no more, except the king delighted in her, and that she were called by name."}, {"numero": 15, "texto": "Now when the turn of Esther, the daughter of Abihail the uncle of Mordecai, who had taken her for his daughter, was come to go in unto the king, she required nothing but what Hegai the king''s chamberlain, the keeper of the women, appointed. And Esther obtained favour in the sight of all them that looked upon her."}, {"numero": 16, "texto": "So Esther was taken unto king Ahasuerus into his house royal in the tenth month, which is the month Tebeth, in the seventh year of his reign."}, {"numero": 17, "texto": "And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."}, {"numero": 18, "texto": "Then the king made a great feast unto all his princes and his servants, even Esther''s feast; and he made a release to the provinces, and gave gifts, according to the state of the king."}, {"numero": 19, "texto": "And when the virgins were gathered together the second time, then Mordecai sat in the king''s gate."}, {"numero": 20, "texto": "Esther had not yet shewed her kindred nor her people; as Mordecai had charged her: for Esther did the commandment of Mordecai, like as when she was brought up with him."}, {"numero": 21, "texto": "In those days, while Mordecai sat in the king''s gate, two of the king''s chamberlains, Bigthan and Teresh, of those which kept the door, were wroth, and sought to lay hands on the king Ahasuerus."}, {"numero": 22, "texto": "And the thing was known to Mordecai, who told it unto Esther the queen; and Esther certified the king thereof in Mordecai''s name."}, {"numero": 23, "texto": "And when inquisition was made of the matter, it was found out; therefore they were both hanged on a tree: and it was written in the book of the chronicles before the king."}]'::jsonb, 'King James Version'),
  ('Et', 2, 'fr', '[{"numero": 1, "texto": "Après ces choses, lorsque la colère du roi Assuérus se fut calmée, il pensa à Vasthi, à ce qu''''elle avait fait, et à la décision qui avait été prise à son sujet."}, {"numero": 2, "texto": "Alors ceux qui servaient le roi dirent: Qu''''on cherche pour le roi des jeunes filles, vierges et belles de figure;"}, {"numero": 3, "texto": "que le roi établisse dans toutes les provinces de son royaume des commissaires chargés de rassembler toutes les jeunes filles, vierges et belles de figure, à Suse, la capitale, dans la maison des femmes, sous la surveillance d''''Hégué, eunuque du roi et gardien des femmes, qui leur donnera les choses nécessaires pour leur toilette;"}, {"numero": 4, "texto": "et que la jeune fille qui plaira au roi devienne reine à la place de Vasthi. Cet avis eut l''''approbation du roi, et il fit ainsi."}, {"numero": 5, "texto": "Il y avait dans Suse, la capitale, un Juif nommé Mardochée, fils de Jaïr, fils de Schimeï, fils de Kis, homme de Benjamin,"}, {"numero": 6, "texto": "qui avait été emmené de Jérusalem parmi les captifs déportés avec Jeconia, roi de Juda, par Nebucadnetsar, roi de Babylone."}, {"numero": 7, "texto": "Il élevait Hadassa, qui est Esther, fille de son oncle; car elle n''''avait ni père ni mère. La jeune fille était belle de taille et belle de figure. A la mort de son père et de sa mère, Mardochée l''''avait adoptée pour fille."}, {"numero": 8, "texto": "Lorsqu''''on eut publié l''''ordre du roi et son édit, et qu''''un grand nombre de jeunes filles furent rassemblées à Suse, la capitale, sous la surveillance d''''Hégaï, Esther fut aussi prise et conduite dans la maison du roi, sous la surveillance d''''Hégaï, gardien des femmes."}, {"numero": 9, "texto": "La jeune fille lui plut, et trouva grâce devant lui; il s''''empressa de lui fournir les choses nécessaires pour sa toilette et pour sa subsistance, lui donna sept jeunes filles choisies dans la maison du roi, et la plaça avec ses jeunes filles dans le meilleur appartement de la maison des femmes."}, {"numero": 10, "texto": "Esther ne fit connaître ni son peuple ni sa naissance, car Mardochée lui avait défendu d''''en parler."}, {"numero": 11, "texto": "Et chaque jour Mardochée allait et venait devant la cour de la maison des femmes, pour savoir comment se portait Esther et comment on la traitait."}, {"numero": 12, "texto": "Chaque jeune fille allait à son tour vers le roi Assuérus, après avoir employé douze mois à s''''acquitter de ce qui était prescrit aux femmes; pendant ce temps, elles prenaient soin de leur toilette, six mois avec de l''''huile de myrrhe, et six mois avec des aromates et des parfums en usage parmi les femmes."}, {"numero": 13, "texto": "C''''est ainsi que chaque jeune fille allait vers le roi; et, quand elle passait de la maison des femmes dans la maison du roi, on lui laissait prendre avec elle tout ce qu''''elle voulait."}, {"numero": 14, "texto": "Elle y allait le soir; et le lendemain matin elle passait dans la seconde maison des femmes, sous la surveillance de Schaaschgaz, eunuque du roi et gardien des concubines. Elle ne retournait plus vers le roi, à moins que le roi n''''en eût le désir et qu''''elle ne fût appelée par son nom."}, {"numero": 15, "texto": "Lorsque son tour d''''aller vers le roi fut arrivé, Esther, fille d''''Abichaïl, oncle de Mardochée qui l''''avait adoptée pour fille, ne demanda que ce qui fut désigné par Hégaï, eunuque du roi et gardien des femmes. Esther trouvait grâce aux yeux de tous ceux qui la voyaient."}, {"numero": 16, "texto": "Esther fut conduite auprès du roi Assuérus, dans sa maison royale, le dixième mois, qui est le mois de Tébeth, la septième année de son règne."}, {"numero": 17, "texto": "Le roi aima Esther plus que toutes les autres femmes, et elle obtint grâce et faveur devant lui plus que toutes les autres jeunes filles. Il mit la couronne royale sur sa tête, et la fit reine à la place de Vasthi."}, {"numero": 18, "texto": "Le roi donna un grand festin à tous ses princes et à ses serviteurs, un festin en l''''honneur d''''Esther; il accorda du repos aux provinces, et fit des présents avec une libéralité royale."}, {"numero": 19, "texto": "La seconde fois qu''''on assembla les jeunes filles, Mardochée était assis à la porte du roi."}, {"numero": 20, "texto": "Esther n''''avait fait connaître ni sa naissance ni son peuple, car Mardochée le lui avait défendu, et elle suivait les ordres de Mardochée aussi fidèlement qu''''à l''''époque où elle était sous sa tutelle."}, {"numero": 21, "texto": "Dans ce même temps, comme Mardochée était assis à la porte du roi, Bigthan et Théresch, deux eunuques du roi, gardes du seuil, cédèrent à un mouvement d''''irritation et voulurent porter la main sur le roi Assuérus."}, {"numero": 22, "texto": "Mardochée eut connaissance de la chose et en informa la reine Esther, qui la redit au roi de la part de Mardochée."}, {"numero": 23, "texto": "Le fait ayant été vérifié et trouvé exact, les deux eunuques furent pendus à un bois. Et cela fut écrit dans le livre des Chroniques en présence du roi."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 2, 'es', '[{"numero": 1, "texto": "PASADAS estas cosas, sosegada ya la ira del rey Assuero, acordóse de Vasthi, y de lo que hizo, y de lo que fué sentenciado contra ella."}, {"numero": 2, "texto": "Y dijeron los criados del rey, sus oficiales: Busquen al rey mozas vírgenes de buen parecer;"}, {"numero": 3, "texto": "Y ponga el rey personas en todas las provincias de su reino, que junten todas las mozas vírgenes de buen parecer en Susán residencia regia, en la casa de las mujeres, al cuidado de Hegai, eunuco del rey, guarda de las mujeres, dándoles sus atavíos;"}, {"numero": 4, "texto": "Y la moza que agradare á los ojos del rey, reine en lugar de Vasthi. Y la cosa plugo en ojos del rey, é hízolo así."}, {"numero": 5, "texto": "Había un varón Judío en Susán residencia regia, cuyo nombre era Mardochêo, hijo de Jair, hijo de Simi, hijo de Cis, del linaje de Benjamín;"}, {"numero": 6, "texto": "El cual había sido trasportado de Jerusalem con los cautivos que fueron llevados con Jechônías rey de Judá, á quien hizo trasportar Nabucodonosor rey de Babilonia."}, {"numero": 7, "texto": "Y había criado á Hadassa, que es Esther, hija de su tío, porque no tenía padre ni madre; y era moza de hermosa forma y de buen parecer; y como su padre y su madre murieron, Mardochêo la había tomado por hija suya."}, {"numero": 8, "texto": "Sucedió pues, que como se divulgó el mandamiento del rey y su acuerdo, y siendo reunidas muchas mozas en Susán residencia regia, á cargo de Hegai, fué tomada también Esther para casa del rey, al cuidado de Hegai, guarda de las mujeres."}, {"numero": 9, "texto": "Y la moza agradó en sus ojos, y halló gracia delante de él; por lo que hizo darle prestamente sus atavíos y sus raciones, dándole también siete convenientes doncellas de la casa del rey; y pasóla con sus doncellas á lo mejor de la casa de las mujeres."}, {"numero": 10, "texto": "Esther no declaró su pueblo ni su nacimiento; porque Mardochêo le había mandado que no lo declarase."}, {"numero": 11, "texto": "Y cada día Mardochêo se paseaba delante del patio de la casa de las mujeres, por saber cómo iba á Esther, y qué se hacía de ella."}, {"numero": 12, "texto": "Y como llegaba el tiempo de cada una de las mozas para venir al rey Assuero, al cabo de haber estado ya doce meses conforme á la ley acerca de las mujeres (porque así se cumplía el tiempo de sus atavíos, esto es, seis meses con óleo de mirra, y seis meses con cosas aromáticas y afeites de mujeres),"}, {"numero": 13, "texto": "Entonces la moza venía así al rey: todo lo que ella decía se le daba, para venir con ello de la casa de las mujeres hasta la casa del rey."}, {"numero": 14, "texto": "Ella venía á la tarde, y á la mañana se volvía á la casa segunda de las mujeres, al cargo de Saasgaz eunuco del rey, guarda de las concubinas: no venía más al rey, salvo si el rey la quería, y era llamada por nombre."}, {"numero": 15, "texto": "Y llegado que fué el tiempo de Esther, hija de Abihail tío de Mardochêo, que él se había tomado por hija, para venir al rey, ninguna cosa procuró sino lo que dijo Hegai eunuco del rey, guarda de las mujeres: y ganaba Esther la gracia de todos los que la veían."}, {"numero": 16, "texto": "Fué pues Esther llevada al rey Assuero á su casa real en el mes décimo, que es el mes de Tebeth, en el año séptimo de su reinado."}, {"numero": 17, "texto": "Y el rey amó á Esther sobre todas las mujeres, y halló gracia y benevolencia delante de él más que todas las vírgenes; y puso la corona real en su cabeza, é hízola reina en lugar de Vasthi."}, {"numero": 18, "texto": "Hizo luego el rey gran banquete á todos sus príncipes y siervos, el banquete de Esther; y alivió á las provincias, é hizo y dió mercedes conforme á la facultad real."}, {"numero": 19, "texto": "Y cuando se juntaban las vírgenes la segunda vez, Mardochêo estaba puesto á la puerta del rey."}, {"numero": 20, "texto": "Y Esther, según le tenía mandado Mardochêo, no había declarado su nación ni su pueblo; porque Esther hacía lo que decía Mardochêo, como cuando con él se educaba."}, {"numero": 21, "texto": "En aquellos días, estando Mardochêo sentado á la puerta del rey, enojáronse Bigthán y Teres, dos eunucos del rey, de la guardia de la puerta, y procuraban poner mano en el rey Assuero."}, {"numero": 22, "texto": "Mas entendido que fué esto por Mardochêo, él lo denunció á la reina Esther, y Esther lo dijo al rey en nombre de Mardochêo."}, {"numero": 23, "texto": "Hízose entonces indagación de la cosa, y fué hallada cierta; por tanto, entrambos fueron colgados en una horca. Y escribióse el caso en el libro de las cosas de los tiempos delante del rey."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 3, 'pt', '[{"numero": 1, "texto": "Depois destas coisas, o rei Assuero engrandeceu a Hamã filho de Hamedata agagita, e o exaltou, e pôs seu assento acima de todos os príncipes que estavam com ele."}, {"numero": 2, "texto": "E todos os servos do rei que estavam à porta do rei se inclinavam e prostravam diante de Hamã, porque assim o rei tinha mandado acerca dele; porém Mardoqueu não se inclinava nem se prostrava."}, {"numero": 3, "texto": "Então os servos do rei que estavam à porta do rei disseram a Mardoqueu: Por que transgrides o mandamento do rei?"}, {"numero": 4, "texto": "Sucedeu, pois, que, tendo eles dito [isto] dia após dia, e ele não tendo lhes dado ouvidos, avisaram dele a Hamã, para verem se as palavras de Mardoqueu continuariam; porque ele tinha lhes declarado que era judeu."}, {"numero": 5, "texto": "Quando Hamã viu que Mardoqueu não se inclinava nem se prostrava diante dele, ele se encheu de furor."}, {"numero": 6, "texto": "Porém, tendo já sido informado do povo de Mardoqueu, ele achou pouco matar apenas Mardoqueu; então Hamã procurou destruir a todos os judeus, o povo de Mardoqueu, que havia no reino de Assuero."}, {"numero": 7, "texto": "No primeiro mês (que é o mês de Nisã), no décimo segundo ano do rei Assuero, foi lançada Pur, isto é, a sorte, diante de Hamã, para cada dia e para cada mês; e [a sorte indicou] o décimo segundo mês, o mês de Adar."}, {"numero": 8, "texto": "Então Hamã disse ao rei Assuero: Há um povo disperso e dividido entre os povos em todas as províncias de teu reino, cujas leis são diferentes das de todo o povo, e não obedecem às leis do rei; por isso não convém ao rei tolerá-los."}, {"numero": 9, "texto": "Se for do agrado do rei, escreva-se que sejam destruídos; e eu porei dez mil talentos de prata nas mãos dos executarem a ação, para que sejam postos na tesouraria do rei."}, {"numero": 10, "texto": "Então o rei tirou seu anel de sua mão, e o deu a Hamã filho de Hamedata agageu, inimigo dos judeus,"}, {"numero": 11, "texto": "E o rei disse a Hamã: Essa prata te seja dada; e também esse povo, para fazeres dele o que quiseres."}, {"numero": 12, "texto": "Então chamaram aos escrivães do rei no primeiro mês, no [dia] treze do mesmo, e foi escrito conforme a tudo o que Hamã mandou, aos príncipes do rei, e aos governadores que havia sobre cada província, e aos líderes de cada povo, a cada província conforme sua escrita, e a cada povo conforme sua língua; em nome do rei Assuero foi escrito, e com o anel do rei foi selado."}, {"numero": 13, "texto": "E foram enviadas cartas por meio de mensageiros a todas as províncias do rei, para destruírem, matarem, e exterminarem a todos os judeus, desde o menino até o velho, crianças e mulheres em um dia, no [dia] treze do décimo segundo mês (que é o mês de Adar), e para saquearem suas posses."}, {"numero": 14, "texto": "A cópia do texto foi entregue como decreto para que anunciasse em todas as províncias em público a todos os povos, para que estivessem preparados para aquele dia."}, {"numero": 15, "texto": "Assim os mensageiros, obrigados pela palavra do rei, saíram, e o decreto foi anunciado na fortaleza de Susã. E o rei e Hamã se sentaram para beber; porém a cidade de Susã estava confusa."}]'::jsonb, 'Almeida Livre'),
  ('Et', 3, 'en', '[{"numero": 1, "texto": "After these things did king Ahasuerus promote Haman the son of Hammedatha the Agagite, and advanced him, and set his seat above all the princes that were with him."}, {"numero": 2, "texto": "And all the king''s servants, that were in the king''s gate, bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence."}, {"numero": 3, "texto": "Then the king''s servants, which were in the king''s gate, said unto Mordecai, Why transgressest thou the king''s commandment?"}, {"numero": 4, "texto": "Now it came to pass, when they spake daily unto him, and he hearkened not unto them, that they told Haman, to see whether Mordecai''s matters would stand: for he had told them that he was a Jew."}, {"numero": 5, "texto": "And when Haman saw that Mordecai bowed not, nor did him reverence, then was Haman full of wrath."}, {"numero": 6, "texto": "And he thought scorn to lay hands on Mordecai alone; for they had shewed him the people of Mordecai: wherefore Haman sought to destroy all the Jews that were throughout the whole kingdom of Ahasuerus, even the people of Mordecai."}, {"numero": 7, "texto": "In the first month, that is, the month Nisan, in the twelfth year of king Ahasuerus, they cast Pur, that is, the lot, before Haman from day to day, and from month to month, to the twelfth month, that is, the month Adar."}, {"numero": 8, "texto": "And Haman said unto king Ahasuerus, There is a certain people scattered abroad and dispersed among the people in all the provinces of thy kingdom; and their laws are diverse from all people; neither keep they the king''s laws: therefore it is not for the king''s profit to suffer them."}, {"numero": 9, "texto": "If it please the king, let it be written that they may be destroyed: and I will pay ten thousand talents of silver to the hands of those that have the charge of the business, to bring it into the king''s treasuries."}, {"numero": 10, "texto": "And the king took his ring from his hand, and gave it unto Haman the son of Hammedatha the Agagite, the Jews'' enemy."}, {"numero": 11, "texto": "And the king said unto Haman, The silver is given to thee, the people also, to do with them as it seemeth good to thee."}, {"numero": 12, "texto": "Then were the king''s scribes called on the thirteenth day of the first month, and there was written according to all that Haman had commanded unto the king''s lieutenants, and to the governors that were over every province, and to the rulers of every people of every province according to the writing thereof, and to every people after their language; in the name of king Ahasuerus was it written, and sealed with the king''s ring."}, {"numero": 13, "texto": "And the letters were sent by posts into all the king''s provinces, to destroy, to kill, and to cause to perish, all Jews, both young and old, little children and women, in one day, even upon the thirteenth day of the twelfth month, which is the month Adar, and to take the spoil of them for a prey."}, {"numero": 14, "texto": "The copy of the writing for a commandment to be given in every province was published unto all people, that they should be ready against that day."}, {"numero": 15, "texto": "The posts went out, being hastened by the king''s commandment, and the decree was given in Shushan the palace. And the king and Haman sat down to drink; but the city Shushan was perplexed."}]'::jsonb, 'King James Version'),
  ('Et', 3, 'fr', '[{"numero": 1, "texto": "Après ces choses, le roi Assuérus fit monter au pouvoir Haman, fils d''''Hammedatha, l''''Agaguite; il l''''éleva en dignité et plaça son siège au-dessus de ceux de tous les chefs qui étaient auprès de lui."}, {"numero": 2, "texto": "Tous les serviteurs du roi, qui se tenaient à la porte du roi, fléchissaient le genou et se prosternaient devant Haman, car tel était l''''ordre du roi à son égard. Mais Mardochée ne fléchissait point le genou et ne se prosternait point."}, {"numero": 3, "texto": "Et les serviteurs du roi, qui se tenaient à la porte du roi, dirent à Mardochée: Pourquoi transgresses-tu l''''ordre du roi?"}, {"numero": 4, "texto": "Comme ils le lui répétaient chaque jour et qu''''il ne les écoutait pas, ils en firent rapport à Haman, pour voir si Mardochée persisterait dans sa résolution; car il leur avait dit qu''''il était Juif."}, {"numero": 5, "texto": "Et Haman vit que Mardochée ne fléchissait point le genou et ne se prosternait point devant lui. Il fut rempli de fureur;"}, {"numero": 6, "texto": "mais il dédaigna de porter la main sur Mardochée seul, car on lui avait dit de quel peuple était Mardochée, et il voulut détruire le peuple de Mardochée, tous les Juifs qui se trouvaient dans tout le royaume d''''Assuérus."}, {"numero": 7, "texto": "Au premier mois, qui est le mois de Nisan, la douzième année du roi Assuérus, on jeta le pur, c''''est-à-dire le sort, devant Haman, pour chaque jour et pour chaque mois, jusqu''''au douzième mois, qui est le mois d''''Adar."}, {"numero": 8, "texto": "Alors Haman dit au roi Assuérus: Il y a dans toutes les provinces de ton royaume un peuple dispersé et à part parmi les peuples, ayant des lois différentes de celles de tous les peuples et n''''observant point les lois du roi. Il n''''est pas dans l''''intérêt du roi de le laisser en repos."}, {"numero": 9, "texto": "Si le roi le trouve bon, qu''''on écrive l''''ordre de les faire périr; et je pèserai dix mille talents d''''argent entre les mains des fonctionnaires, pour qu''''on les porte dans le trésor du roi."}, {"numero": 10, "texto": "Le roi ôta son anneau de la main, et le remit à Haman, fils d''''Hammedatha, l''''Agaguite, ennemi des Juifs."}, {"numero": 11, "texto": "Et le roi dit à Haman: L''''argent t''''est donné, et ce peuple aussi; fais-en ce que tu voudras."}, {"numero": 12, "texto": "Les secrétaires du roi furent appelés le treizième jour du premier mois, et l''''on écrivit, suivant tout ce qui fut ordonné par Haman, aux satrapes du roi, aux gouverneurs de chaque province et aux chefs de chaque peuple, à chaque province selon son écriture et à chaque peuple selon sa langue. Ce fut au nom du roi Assuérus que l''''on écrivit, et on scella avec l''''anneau du roi."}, {"numero": 13, "texto": "Les lettres furent envoyées par les courriers dans toutes les provinces du roi, pour qu''''on détruisît, qu''''on tuât et qu''''on fît périr tous les Juifs, jeunes et vieux, petits enfants et femmes, en un seul jour, le treizième du douzième mois, qui est le mois d''''Adar, et pour que leurs biens fussent livrés au pillage."}, {"numero": 14, "texto": "Ces lettres renfermaient une copie de l''''édit qui devait être publié dans chaque province, et invitaient tous les peuples à se tenir prêts pour ce jour-là."}, {"numero": 15, "texto": "Les courriers partirent en toute hâte, d''''après l''''ordre du roi. L''''édit fut aussi publié dans Suse, la capitale; et tandis que le roi et Haman étaient à boire, la ville de Suse était dans la consternation."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 3, 'es', '[{"numero": 1, "texto": "DESPUÉS de estas cosas, el rey Assuero engrandeció á Amán hijo de Amadatha Agageo, y ensalzólo, y puso su silla sobre todos los príncipes que estaban con él."}, {"numero": 2, "texto": "Y todos los siervos del rey que estaban á la puerta del rey, se arrodillaban é inclinaban á Amán, porque así se lo había mandado el rey; pero Mardochêo, ni se arrodillaba ni se humillaba."}, {"numero": 3, "texto": "Y los siervos del rey que estaban á la puerta, dijeron á Mardochêo: ¿Por qué traspasas el mandamiento del rey?"}, {"numero": 4, "texto": "Y aconteció que, hablándole cada día de esta manera, y no escuchándolos él, denunciáronlo á Amán, por ver si las palabras de Mardochêo se mantendrían; porque ya él les había declarado que era Judío."}, {"numero": 5, "texto": "Y vió Amán que Mardochêo ni se arrodillaba ni se humillaba delante de él; y llenóse de ira."}, {"numero": 6, "texto": "Mas tuvo en poco meter mano en solo Mardochêo; que ya le habían declarado el pueblo de Mardochêo: y procuró Amán destruir á todos los Judíos que había en el reino de Assuero, al pueblo de Mardochêo."}, {"numero": 7, "texto": "En el mes primero, que es el mes de Nisán, en el año duodécimo del rey Assuero, fué echada Pur, esto es, la suerte, delante de Amán, de día en día y de mes en mes; y salió el mes duodécimo, que es el mes de Adar."}, {"numero": 8, "texto": "Y dijo Amán al rey Assuero: Hay un pueblo esparcido y dividido entre los pueblos en todas las provincias de tu reino, y sus leyes son diferentes de las de todo pueblo, y no observan las leyes del rey; y al rey no viene provecho de dejarlos."}, {"numero": 9, "texto": "Si place al rey, escríbase que sean destruídos; y yo pesaré diez mil talentos de plata en manos de los que manejan la hacienda, para que sean traídos á los tesoros del rey."}, {"numero": 10, "texto": "Entonces el rey quitó su anillo de su mano, y diólo á Amán hijo de Amadatha Agageo, enemigo de los Judíos,"}, {"numero": 11, "texto": "Y díjole: La plata propuesta sea para ti, y asimismo el pueblo, para que hagas de él lo que bien te pareciere."}, {"numero": 12, "texto": "Entonces fueron llamados los escribanos del rey en el mes primero, á trece del mismo, y fué escrito conforme á todo lo que mandó Amán, á los príncipes del rey, y á los capitanes que estaban sobre cada provincia, y á los príncipes de cada pueblo, á cada provincia según su escritura, y á cada pueblo según su lengua: en nombre del rey Assuero fué escrito, y signado con el anillo del rey."}, {"numero": 13, "texto": "Y fueron enviadas letras por mano de los correos á todas las provincias del rey, para destruir, y matar, y exterminar á todos los Judíos, desde el niño hasta el viejo, niños y mujeres en un día, en el trece del mes duodécimo, que es el mes de Adar, y para apoderarse de su despojo."}, {"numero": 14, "texto": "La copia del escrito que se diese por mandamiento en cada provincia, fué publicada á todos los pueblos, á fin de que estuviesen apercibidos para aquel día."}, {"numero": 15, "texto": "Y salieron los correos de priesa por mandato del rey, y el edicto fué dado en Susán capital del reino. Y el rey y Amán estaban sentados á beber, y la ciudad de Susán estaba conmovida."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 4, 'pt', '[{"numero": 1, "texto": "Quando Mardoqueu soube de tudo quanto havia acontecido, Mordecai rasgou suas vestes, e vestiu-se de saco e de cinza, e saiu andando por meio da cidade, clamando com grande e amargo clamor."}, {"numero": 2, "texto": "E chegou até diante da porta do rei, porque ninguém vestido de saco podia entrar pela porta do rei."}, {"numero": 3, "texto": "E em toda província e lugar onde a palavra do rei e seu decreto chegava, havia entre os judeus grande luto, jejum, choro, e lamentação; e muitos se deitaram em sacos e cinza."}, {"numero": 4, "texto": "Então as virgens de Ester e seus eunucos vieram e a informaram; então a rainha teve grande dor, e enviou roupas para vestir a Mardoqueu, e tirar o saco que estava sobre ele; porém ele não as aceitou."}, {"numero": 5, "texto": "Então Ester chamou a Hatá, um dos eunucos do rei, que ele tinha posto para a servir, e o mandou a Mardoqueu, para saber o que era aquilo, e por quê."}, {"numero": 6, "texto": "Assim, pois Hatá veio a Mardoqueu à praça da cidade que estava diante da porta do rei."}, {"numero": 7, "texto": "E Mardoqueu lhe contou tudo o que tinha lhe acontecido, assim como a soma de prata que Hamã havia dito que daria para a tesouraria do rei por causa dos judeus, para os destruir."}, {"numero": 8, "texto": "Também lhe deu a cópia da escritura do decreto que tinha sido publicado em Susã para que fossem destruídos, a fim de a mostrar a Ester e a ela informar, e lhe mandar que fosse ao rei para lhe pedir e suplicar diante dele em favor de seu povo."}, {"numero": 9, "texto": "Veio, pois, Hatá, e contou a Ester as palavras de Mardoqueu."}, {"numero": 10, "texto": "Então Ester respondeu a Hatá, e mandou-lhe [dizer] a Mardoqueu:"}, {"numero": 11, "texto": "Todos os servos do rei e o povo das províncias do rei sabem que todo homem ou mulher que entra ao pátio interno na presença rei sem ser chamado, sua sentença é a morte, a não ser se o rei estender o cetro de ouro, para que viva; e eu nestes trinta dias não fui chamada para vir ao rei."}, {"numero": 12, "texto": "E contaram a Mardoqueu as palavras de Ester."}, {"numero": 13, "texto": "Então Mardoqueu disse que respondessem a Ester: Não penses em tua alma, que escaparás na casa do rei mais que todos os [outros] judeus;"}, {"numero": 14, "texto": "Porque se te calares agora, haverá alívio e libertação para os judeus de outra parte; porém tu e a casa de teu pai perecereis. E quem sabe se foi para tempo como este que chegaste a ser rainha?"}, {"numero": 15, "texto": "Então Ester disse que respondessem a Mardoqueu:"}, {"numero": 16, "texto": "Vai, e junta a todos os judeus que se acham em Susã, e jejuai por mim, e não comais nem bebais durante três dias, nem de noite nem de dia; eu e minhas virgens também assim jejuaremos; e assim virei ao rei, ainda que não seja segundo à lei; e se eu perecer, perecerei."}, {"numero": 17, "texto": "Então Mardoqueu se foi, e fez conforme tudo quanto Ester lhe mandara."}]'::jsonb, 'Almeida Livre'),
  ('Et', 4, 'en', '[{"numero": 1, "texto": "When Mordecai perceived all that was done, Mordecai rent his clothes, and put on sackcloth with ashes, and went out into the midst of the city, and cried with a loud and a bitter cry;"}, {"numero": 2, "texto": "And came even before the king''s gate: for none might enter into the king''s gate clothed with sackcloth."}, {"numero": 3, "texto": "And in every province, whithersoever the king''s commandment and his decree came, there was great mourning among the Jews, and fasting, and weeping, and wailing; and many lay in sackcloth and ashes."}, {"numero": 4, "texto": "So Esther''s maids and her chamberlains came and told it her. Then was the queen exceedingly grieved; and she sent raiment to clothe Mordecai, and to take away his sackcloth from him: but he received it not."}, {"numero": 5, "texto": "Then called Esther for Hatach, one of the king''s chamberlains, whom he had appointed to attend upon her, and gave him a commandment to Mordecai, to know what it was, and why it was."}, {"numero": 6, "texto": "So Hatach went forth to Mordecai unto the street of the city, which was before the king''s gate."}, {"numero": 7, "texto": "And Mordecai told him of all that had happened unto him, and of the sum of the money that Haman had promised to pay to the king''s treasuries for the Jews, to destroy them."}, {"numero": 8, "texto": "Also he gave him the copy of the writing of the decree that was given at Shushan to destroy them, to shew it unto Esther, and to declare it unto her, and to charge her that she should go in unto the king, to make supplication unto him, and to make request before him for her people."}, {"numero": 9, "texto": "And Hatach came and told Esther the words of Mordecai."}, {"numero": 10, "texto": "Again Esther spake unto Hatach, and gave him commandment unto Mordecai;"}, {"numero": 11, "texto": "All the king''s servants, and the people of the king''s provinces, do know, that whosoever, whether man or women, shall come unto the king into the inner court, who is not called, there is one law of his to put him to death, except such to whom the king shall hold out the golden sceptre, that he may live: but I have not been called to come in unto the king these thirty days."}, {"numero": 12, "texto": "And they told to Mordecai Esther''s words."}, {"numero": 13, "texto": "Then Mordecai commanded to answer Esther, Think not with thyself that thou shalt escape in the king''s house, more than all the Jews."}, {"numero": 14, "texto": "For if thou altogether holdest thy peace at this time, then shall there enlargement and deliverance arise to the Jews from another place; but thou and thy father''s house shall be destroyed: and who knoweth whether thou art come to the kingdom for such a time as this?"}, {"numero": 15, "texto": "Then Esther bade them return Mordecai this answer,"}, {"numero": 16, "texto": "Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish."}, {"numero": 17, "texto": "So Mordecai went his way, and did according to all that Esther had commanded him."}]'::jsonb, 'King James Version'),
  ('Et', 4, 'fr', '[{"numero": 1, "texto": "Mardochée, ayant appris tout ce qui se passait, déchira ses vêtements, s''''enveloppa d''''un sac et se couvrit de cendre. Puis il alla au milieu de la ville en poussant avec force des cris amers,"}, {"numero": 2, "texto": "et se rendit jusqu''''à la porte du roi, dont l''''entrée était interdite à toute personne revêtue d''''un sac."}, {"numero": 3, "texto": "Dans chaque province, partout où arrivaient l''''ordre du roi et son édit, il y eut une grande désolation parmi les Juifs; ils jeûnaient, pleuraient et se lamentaient, et beaucoup se couchaient sur le sac et la cendre."}, {"numero": 4, "texto": "Les servantes d''''Esther et ses eunuques vinrent lui annoncer cela, et la reine fut très effrayée. Elle envoya des vêtements à Mardochée pour le couvrir et lui faire ôter son sac, mais il ne les accepta pas."}, {"numero": 5, "texto": "Alors Esther appela Hathac, l''''un des eunuques que le roi avait placés auprès d''''elle, et elle le chargea d''''aller demander à Mardochée ce que c''''était et d''''où cela venait."}, {"numero": 6, "texto": "Hathac se rendit vers Mardochée sur la place de la ville, devant la porte du roi."}, {"numero": 7, "texto": "Et Mardochée lui raconta tout ce qui lui était arrivé, et lui indiqua la somme d''''argent qu''''Haman avait promis de livrer au trésor du roi en retour du massacre des Juifs."}, {"numero": 8, "texto": "Il lui donna aussi une copie de l''''édit publié dans Suse en vue de leur destruction, afin qu''''il le montrât à Esther et lui fît tout connaître; et il ordonna qu''''Esther se rendît chez le roi pour lui demander grâce et l''''implorer en faveur de son peuple."}, {"numero": 9, "texto": "Hathac vint rapporter à Esther les paroles de Mardochée."}, {"numero": 10, "texto": "Esther chargea Hathac d''''aller dire à Mardochée:"}, {"numero": 11, "texto": "Tous les serviteurs du roi et le peuple des provinces du roi savent qu''''il existe une loi portant peine de mort contre quiconque, homme ou femme, entre chez le roi, dans la cour intérieure, sans avoir été appelé; celui-là seul a la vie sauve, à qui le roi tend le sceptre d''''or. Et moi, je n''''ai point été appelée auprès du roi depuis trente jours."}, {"numero": 12, "texto": "Lorsque les paroles d''''Esther eurent été rapportées à Mardochée,"}, {"numero": 13, "texto": "Mardochée fit répondre à Esther: Ne t''''imagine pas que tu échapperas seule d''''entre tous les Juifs, parce que tu es dans la maison du roi;"}, {"numero": 14, "texto": "car, si tu te tais maintenant, le secours et la délivrance surgiront d''''autre part pour les Juifs, et toi et la maison de ton père vous périrez. Et qui sait si ce n''''est pas pour un temps comme celui-ci que tu es parvenue à la royauté?"}, {"numero": 15, "texto": "Esther envoya dire à Mardochée:"}, {"numero": 16, "texto": "Va, rassemble tous les Juifs qui se trouvent à Suse, et jeûnez pour moi, sans manger ni boire pendant trois jours, ni la nuit ni le jour. Moi aussi, je jeûnerai de même avec mes servantes, puis j''''entrerai chez le roi, malgré la loi; et si je dois périr, je périrai."}, {"numero": 17, "texto": "Mardochée s''''en alla, et fit tout ce qu''''Esther lui avait ordonné."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 4, 'es', '[{"numero": 1, "texto": "LUEGO que supo Mardochêo todo lo que se había hecho, rasgó sus vestidos, y vistióse de saco y de ceniza, y fuése por medio de la ciudad clamando con grande y amargo clamor."}, {"numero": 2, "texto": "Y vino hasta delante de la puerta del rey: porque no era lícito pasar adentro de la puerta del rey con vestido de saco."}, {"numero": 3, "texto": "Y en cada provincia y lugar donde el mandamiento del rey y su decreto llegaba, tenían los Judíos grande luto, y ayuno, y lloro, y lamentación: saco y ceniza era la cama de muchos."}, {"numero": 4, "texto": "Y vinieron las doncellas de Esther y sus eunucos, y dijéronselo: y la reina tuvo gran dolor, y envió vestidos para hacer vestir á Mardochêo, y hacerle quitar el saco de sobre él; mas él no los recibió."}, {"numero": 5, "texto": "Entonces Esther llamó á Atach, uno de los eunucos del rey, que él había hecho estar delante de ella, y mandólo á Mardochêo, con orden de saber qué era aquello, y por qué."}, {"numero": 6, "texto": "Salió pues Atach á Mardochêo, á la plaza de la ciudad que estaba delante de la puerta del rey."}, {"numero": 7, "texto": "Y Mardochêo le declaró todo lo que le había acontecido, y dióle noticia de la plata que Amán había dicho que pesaría para los tesoros del rey por razón de los Judíos, para destruirlos."}, {"numero": 8, "texto": "Dióle también la copia de la escritura del decreto que había sido dado en Susán para que fuesen destruídos, á fin de que la mostrara á Esther y se lo declarase, y le encargara que fuese al rey á suplicarle, y á pedir delante de él por su pueblo."}, {"numero": 9, "texto": "Y vino Atach, y contó á Esther las palabras de Mardochêo."}, {"numero": 10, "texto": "Entonces Esther dijo á Atach, y mandóle decir á Mardochêo:"}, {"numero": 11, "texto": "Todos los siervos del rey, y el pueblo de las provincias del rey saben, que cualquier hombre ó mujer que entra al rey al patio de adentro sin ser llamado, por una sola ley ha de morir: salvo aquel á quien el rey extendiere el cetro de oro, el cual vivirá: y yo no he sido llamada para entrar al rey estos treinta días."}, {"numero": 12, "texto": "Y dijeron á Mardochêo las palabras de Esther."}, {"numero": 13, "texto": "Entonces dijo Mardochêo que respondiesen á Esther: No pienses en tu alma, que escaparás en la casa del rey más que todos los Judíos:"}, {"numero": 14, "texto": "Porque si absolutamente callares en este tiempo, respiro y libertación tendrán los Judíos de otra parte; mas tú y la casa de tu padre pereceréis. ¿Y quién sabe si para esta hora te han hecho llegar al reino?"}, {"numero": 15, "texto": "Y Esther dijo que respondiesen á Mardochêo:"}, {"numero": 16, "texto": "Ve, y junta á todos los Judíos que se hallan en Susán, y ayunad por mí, y no comáis ni bebáis en tres días, noche ni día: yo también con mis doncellas ayunaré igualmente, y así entraré al rey, aunque no sea conforme á la ley; y si perezco, que perezca."}, {"numero": 17, "texto": "Entonces se fué Mardochêo, é hizo conforme á todo lo que le mandó Esther."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 5, 'pt', '[{"numero": 1, "texto": "Aconteceu, pois, que ao terceiro dia Ester se vestiu de vestes reais, e se pôs no pátio de dentro da casa do rei, de frente ao aposento do rei; e o rei estava sentado em seu trono real no aposento real, em frente da porta do aposento."}, {"numero": 2, "texto": "E foi que, quando ele viu a rainha Ester, que estava no pátio, ela alcançou favor em seus olhos; e o rei apontou para Ester o cetro de ouro que tinha em sua mão. Então Ester se aproximou, e tocou a ponta do cetro."}, {"numero": 3, "texto": "Então o rei disse: O que tens, rainha Ester? E qual é a tua petição? Até a metade do reino será dada a ti."}, {"numero": 4, "texto": "E Ester respondeu: Se for do agrado do rei, venha o rei hoje com Hamã ao banquete que lhe tenho preparado."}, {"numero": 5, "texto": "Então o rei disse: Fazei Hamã se apressar a fazer o que Ester disse. Assim o rei veio com Hamã ao banquete que Ester havia preparado."}, {"numero": 6, "texto": "O rei perguntou a Ester no banquete do vinho: Qual é a tua petição, para que te seja concedida? Qual é o teu pedido? Ainda que seja a metade do reino, será feito."}, {"numero": 7, "texto": "Então Ester respondeu, dizendo: Minha petição e minha demanda é:"}, {"numero": 8, "texto": "Se tenho achado favor aos olhos do rei, e se agrada ao rei conceder minha petição e fazer cumprir o meu pedido, que o rei venha com Hamã ao banquete que lhes prepararei; e amanhã farei conforme o que o rei tem dito."}, {"numero": 9, "texto": "Então Hamã saiu naquele dia contente e alegre de coração; porém, quando viu a Mardoqueu à porta do rei, e que ele não se levantava nem se movia por ele, então Hamã se encheu de furor contra Mardoqueu."}, {"numero": 10, "texto": "Porém Hamã se conteve, e veio a sua casa, e mandou vir seus amigos, e a Zeres sua mulher."}, {"numero": 11, "texto": "E Hamã lhes contou a glória de seus riquezas, e a multidão de seus filhos, e tudo em que o rei tinha lhe engrandecido e lhe exaltado sobre os príncipes e servos do rei."}, {"numero": 12, "texto": "Hamã também disse: Até a rainha Ester a ninguém fez vir com o rei ao banquete que ela preparou, a não ser a mim; e ainda amanhã sou convidado dela juntamente com o rei."}, {"numero": 13, "texto": "Porém tudo isto não me satisfaz, enquanto eu ver o judeu Mardoqueu sentado à porta do rei."}, {"numero": 14, "texto": "Então sua mulher Zeres e todos os seus amigos lhe disseram: Seja feita uma forca de cinquenta côvados de altura, e amanhã dize ao rei para que nela enforquem a Mardoqueu; e então vai alegre com o rei ao banquete. E este conselho foi do agrado de Hamã, e ele mandou fazer a forca."}]'::jsonb, 'Almeida Livre'),
  ('Et', 5, 'en', '[{"numero": 1, "texto": "Now it came to pass on the third day, that Esther put on her royal apparel, and stood in the inner court of the king''s house, over against the king''s house: and the king sat upon his royal throne in the royal house, over against the gate of the house."}, {"numero": 2, "texto": "And it was so, when the king saw Esther the queen standing in the court, that she obtained favour in his sight: and the king held out to Esther the golden sceptre that was in his hand. So Esther drew near, and touched the top of the sceptre."}, {"numero": 3, "texto": "Then said the king unto her, What wilt thou, queen Esther? and what is thy request? it shall be even given thee to the half of the kingdom."}, {"numero": 4, "texto": "And Esther answered, If it seem good unto the king, let the king and Haman come this day unto the banquet that I have prepared for him."}, {"numero": 5, "texto": "Then the king said, Cause Haman to make haste, that he may do as Esther hath said. So the king and Haman came to the banquet that Esther had prepared."}, {"numero": 6, "texto": "And the king said unto Esther at the banquet of wine, What is thy petition? and it shall be granted thee: and what is thy request? even to the half of the kingdom it shall be performed."}, {"numero": 7, "texto": "Then answered Esther, and said, My petition and my request is;"}, {"numero": 8, "texto": "If I have found favour in the sight of the king, and if it please the king to grant my petition, and to perform my request, let the king and Haman come to the banquet that I shall prepare for them, and I will do to morrow as the king hath said."}, {"numero": 9, "texto": "Then went Haman forth that day joyful and with a glad heart: but when Haman saw Mordecai in the king''s gate, that he stood not up, nor moved for him, he was full of indignation against Mordecai."}, {"numero": 10, "texto": "Nevertheless Haman refrained himself: and when he came home, he sent and called for his friends, and Zeresh his wife."}, {"numero": 11, "texto": "And Haman told them of the glory of his riches, and the multitude of his children, and all the things wherein the king had promoted him, and how he had advanced him above the princes and servants of the king."}, {"numero": 12, "texto": "Haman said moreover, Yea, Esther the queen did let no man come in with the king unto the banquet that she had prepared but myself; and to morrow am I invited unto her also with the king."}, {"numero": 13, "texto": "Yet all this availeth me nothing, so long as I see Mordecai the Jew sitting at the king''s gate."}, {"numero": 14, "texto": "Then said Zeresh his wife and all his friends unto him, Let a gallows be made of fifty cubits high, and to morrow speak thou unto the king that Mordecai may be hanged thereon: then go thou in merrily with the king unto the banquet. And the thing pleased Haman; and he caused the gallows to be made."}]'::jsonb, 'King James Version'),
  ('Et', 5, 'fr', '[{"numero": 1, "texto": "Le troisième jour, Esther mit ses vêtements royaux et se présenta dans la cour intérieure de la maison du roi, devant la maison du roi. Le roi était assis sur son trône royal dans la maison royale, en face de l''''entrée de la maison."}, {"numero": 2, "texto": "Lorsque le roi vit la reine Esther debout dans la cour, elle trouva grâce à ses yeux; et le roi tendit à Esther le sceptre d''''or qu''''il tenait à la main. Esther s''''approcha, et toucha le bout du sceptre."}, {"numero": 3, "texto": "Le roi lui dit: Qu''''as-tu, reine Esther, et que demandes-tu? Quand ce serait la moitié du royaume, elle te serait donnée."}, {"numero": 4, "texto": "Esther répondit: Si le roi le trouve bon, que le roi vienne aujourd''''hui avec Haman au festin que je lui ai préparé."}, {"numero": 5, "texto": "Et le roi dit: Allez tout de suite chercher Haman, comme le désire Esther. Le roi se rendit avec Haman au festin qu''''avait préparé Esther."}, {"numero": 6, "texto": "Et pendant qu''''on buvait le vin, le roi dit à Esther: Quelle est ta demande? Elle te sera accordée. Que désires-tu? Quand ce serait la moitié du royaume, tu l''''obtiendras."}, {"numero": 7, "texto": "Esther répondit: Voici ce que je demande et ce que je désire."}, {"numero": 8, "texto": "Si j''''ai trouvé grâce aux yeux du roi, et s''''il plaît au roi d''''accorder ma demande et de satisfaire mon désir, que le roi vienne avec Haman au festin que je leur préparerai, et demain je donnerai réponse au roi selon son ordre."}, {"numero": 9, "texto": "Haman sortit ce jour-là, joyeux et le coeur content. Mais lorsqu''''il vit, à la porte du roi, Mardochée qui ne se levait ni ne se remuait devant lui, il fut rempli de colère contre Mardochée."}, {"numero": 10, "texto": "Il sut néanmoins se contenir, et il alla chez lui. Puis il envoya chercher ses amis et Zéresch, sa femme."}, {"numero": 11, "texto": "Haman leur parla de la magnificence de ses richesses, du nombre de ses fils, de tout ce qu''''avait fait le roi pour l''''élever en dignité, et du rang qu''''il lui avait donné au-dessus des chefs et des serviteurs du roi."}, {"numero": 12, "texto": "Et il ajouta: Je suis même le seul que la reine Esther ait admis avec le roi au festin qu''''elle a fait, et je suis encore invité pour demain chez elle avec le roi."}, {"numero": 13, "texto": "Mais tout cela n''''est d''''aucun prix pour moi aussi longtemps que je verrai Mardochée, le Juif, assis à la porte du roi."}, {"numero": 14, "texto": "Zéresch, sa femme, et tous ses amis lui dirent: Qu''''on prépare un bois haut de cinquante coudées, et demain matin demande au roi qu''''on y pende Mardochée; puis tu iras joyeux au festin avec le roi. Cet avis plut à Haman, et il fit préparer le bois."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 5, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que al tercer día se vistió Esther su vestido real, y púsose en el patio de adentro de la casa del rey, enfrente del aposento del rey: y estaba el rey sentado en su solio regio en el aposento real, enfrente de la puerta del aposento."}, {"numero": 2, "texto": "Y fué que, como vió á la reina Esther que estaba en el patio, ella obtuvo gracia en sus ojos; y el rey extendió á Esther el cetro de oro que tenía en la mano. Entonces se llegó Esther, y tocó la punta del cetro."}, {"numero": 3, "texto": "Y dijo el rey: ¿Qué tienes, reina Esther? ¿y cuál es tu petición? Hasta la mitad del reino, se te dará."}, {"numero": 4, "texto": "Y Esther dijo: Si al rey place, venga hoy el rey con Amán al banquete que le he hecho."}, {"numero": 5, "texto": "Y respondió el rey: Daos priesa, llamad á Amán, para hacer lo que Esther ha dicho. Vino pues el rey con Amán al banquete que Esther dispuso."}, {"numero": 6, "texto": "Y dijo el rey á Esther en el banquete del vino: ¿Cuál es tu petición, y te será otorgada? ¿Cuál es tu demanda? Aunque sea la mitad del reino, te será concedida."}, {"numero": 7, "texto": "Entonces respondió Esther, y dijo: Mi petición y mi demanda es:"}, {"numero": 8, "texto": "Si he hallado gracia en los ojos del rey, y si place al rey otorgar mi petición y hacer mi demanda, que venga el rey con Amán al banquete que les dispondré; y mañana haré conforme á lo que el rey ha mandado."}, {"numero": 9, "texto": "Y salió Amán aquel día contento y alegre de corazón; pero como vió á Mardochêo á la puerta del rey, que no se levantaba ni se movía de su lugar, llenóse contra Mardochêo de ira."}, {"numero": 10, "texto": "Mas refrenóse Amán, y vino á su casa, y envió, é hizo venir sus amigos, y á Zeres su mujer."}, {"numero": 11, "texto": "Y refirióles Amán la gloria de sus riquezas, y la multitud de sus hijos, y todas las cosas con que el rey le había engrandecido y con que le había ensalzado sobre los príncipes y siervos del rey."}, {"numero": 12, "texto": "Y añadió Amán: También la reina Esther á ninguno hizo venir con el rey al banquete que ella dispuso, sino á mí: y aun para mañana soy convidado de ella con el rey."}, {"numero": 13, "texto": "Mas todo esto nada me sirve cada vez que veo al judío Mardochêo sentado á la puerta del rey."}, {"numero": 14, "texto": "Y díjole Zeres su mujer, y todos sus amigos: Hagan una horca alta de cincuenta codos, y mañana di al rey que cuelguen á Mardochêo en ella; y entra con el rey al banquete alegre. Y plugo la cosa en los ojos de Amán, é hizo preparar la horca."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 6, 'pt', '[{"numero": 1, "texto": "Naquela noite o rei perdeu o sono. Então ele mandou trazer o livro das memórias das crônicas: e elas foram lidas na presença do rei."}, {"numero": 2, "texto": "E achou-se escrito que Mardoqueu havia denunciado Bigtã e de Teres, dois eunucos do rei, da guarda da porta, que tinham procurado matar o rei Assuero."}, {"numero": 3, "texto": "Então o rei disse: Que honra e que condecoração se fez a Mardoqueu por isto? E os servos do rei que o serviam disseram: Nada foi feito com ele."}, {"numero": 4, "texto": "Então o rei disse: Quem está no pátio? (Pois Hamã tinha vindo ao pátio de fora da casa do rei, para dizer ao rei que enforcassem a Mardoqueu na forca que tinha preparado para ele)."}, {"numero": 5, "texto": "E os servos do rei lhe responderam: Eis que Hamã está no pátio. E o rei mandou que ele entrasse."}, {"numero": 6, "texto": "Quando Hamã entrou, o rei lhe perguntou: Que se fará ao homem a quem rei deseja honrar? Então Hamã pensou em seu coração: A quem o rei desejará mais dar honra que a mim?"}, {"numero": 7, "texto": "Por isso Hamã respondeu ao rei: Ao homem a quem o rei deseja honrar,"}, {"numero": 8, "texto": "Tragam o vestido real de que o rei costuma se vestir, o cavalo em que o rei costuma cavalgar, e ponha-se a coroa real sobre sua cabeça."}, {"numero": 9, "texto": "E entregue-se o vestido e o cavalo na mão de um dos mais importantes príncipes do rei, e vistam a tal homem a quem o rei deseja honrar, e levem-no a cavalo pelas ruas da cidade, e proclamem diante dele: Assim se fará ao homem a quem o rei deseja honrar!"}, {"numero": 10, "texto": "Então o rei disse a Hamã: Apressa-te, toma o vestido e o cavalo, como disseste, e faze assim para com o judeu Mardoqueu, que se senta à porta do rei; não omitas coisa alguma de tudo quanto disseste."}, {"numero": 11, "texto": "E Hamã tomou o vestido e o cavalo, e vestiu a Mardoqueu; e o levou a cavalo pelas ruas da cidade, e proclamou diante dele: Assim se fará ao homem a quem o rei deseja honrar!"}, {"numero": 12, "texto": "Depois disto Mardoqueu voltou à porta do rei. Porém Hamã se retirou correndo para sua casa, aborrecido, e com sua cabeça coberta."}, {"numero": 13, "texto": "E Hamã contou a sua mulher Zeres e a todos seus amigos tudo o que tinha lhe acontecido; então seus sábios e sua mulher Zeres lhe disseram: Se Mardoqueu, diante de quem começaste a cair, é da semente dos judeus, tu não prevalecerás contra ele; ao contrário, certamente cairás diante dele."}, {"numero": 14, "texto": "Enquanto eles ainda estavam falando com ele, os eunucos do rei chegaram, apressados, para levarem Hamã ao banquete que Ester havia preparado."}]'::jsonb, 'Almeida Livre'),
  ('Et', 6, 'en', '[{"numero": 1, "texto": "On that night could not the king sleep, and he commanded to bring the book of records of the chronicles; and they were read before the king."}, {"numero": 2, "texto": "And it was found written, that Mordecai had told of Bigthana and Teresh, two of the king''s chamberlains, the keepers of the door, who sought to lay hand on the king Ahasuerus."}, {"numero": 3, "texto": "And the king said, What honour and dignity hath been done to Mordecai for this? Then said the king''s servants that ministered unto him, There is nothing done for him."}, {"numero": 4, "texto": "And the king said, Who is in the court? Now Haman was come into the outward court of the king''s house, to speak unto the king to hang Mordecai on the gallows that he had prepared for him."}, {"numero": 5, "texto": "And the king''s servants said unto him, Behold, Haman standeth in the court. And the king said, Let him come in."}, {"numero": 6, "texto": "So Haman came in. And the king said unto him, What shall be done unto the man whom the king delighteth to honour? Now Haman thought in his heart, To whom would the king delight to do honour more than to myself?"}, {"numero": 7, "texto": "And Haman answered the king, For the man whom the king delighteth to honour,"}, {"numero": 8, "texto": "Let the royal apparel be brought which the king useth to wear, and the horse that the king rideth upon, and the crown royal which is set upon his head:"}, {"numero": 9, "texto": "And let this apparel and horse be delivered to the hand of one of the king''s most noble princes, that they may array the man withal whom the king delighteth to honour, and bring him on horseback through the street of the city, and proclaim before him, Thus shall it be done to the man whom the king delighteth to honour."}, {"numero": 10, "texto": "Then the king said to Haman, Make haste, and take the apparel and the horse, as thou hast said, and do even so to Mordecai the Jew, that sitteth at the king''s gate: let nothing fail of all that thou hast spoken."}, {"numero": 11, "texto": "Then took Haman the apparel and the horse, and arrayed Mordecai, and brought him on horseback through the street of the city, and proclaimed before him, Thus shall it be done unto the man whom the king delighteth to honour."}, {"numero": 12, "texto": "And Mordecai came again to the king''s gate. But Haman hasted to his house mourning, and having his head covered."}, {"numero": 13, "texto": "And Haman told Zeresh his wife and all his friends every thing that had befallen him. Then said his wise men and Zeresh his wife unto him, If Mordecai be of the seed of the Jews, before whom thou hast begun to fall, thou shalt not prevail against him, but shalt surely fall before him."}, {"numero": 14, "texto": "And while they were yet talking with him, came the king''s chamberlains, and hasted to bring Haman unto the banquet that Esther had prepared."}]'::jsonb, 'King James Version'),
  ('Et', 6, 'fr', '[{"numero": 1, "texto": "Cette nuit-là, le roi ne put pas dormir, et il se fit apporter le livre des annales, les Chroniques. On les lut devant le roi,"}, {"numero": 2, "texto": "et l''''on trouva écrit ce que Mardochée avait révélé au sujet de Bigthan et de Théresch, les deux eunuques du roi, gardes du seuil, qui avaient voulu porter la main sur le roi Assuérus."}, {"numero": 3, "texto": "Le roi dit: Quelle marque de distinction et d''''honneur Mardochée a-t-il reçue pour cela? Il n''''a rien reçu, répondirent ceux qui servaient le roi."}, {"numero": 4, "texto": "Alors le roi dit: Qui est dans la cour? -Haman était venu dans la cour extérieure de la maison du roi, pour demander au roi de faire pendre Mardochée au bois qu''''il avait préparé pour lui. -"}, {"numero": 5, "texto": "Les serviteurs du roi lui répondirent: C''''est Haman qui se tient dans la cour. Et le roi dit: Qu''''il entre."}, {"numero": 6, "texto": "Haman entra, et le roi lui dit: Que faut-il faire pour un homme que le roi veut honorer? Haman se dit en lui-même: Quel autre que moi le roi voudrait-il honorer?"}, {"numero": 7, "texto": "Et Haman répondit au roi: Pour un homme que le roi veut honorer,"}, {"numero": 8, "texto": "il faut prendre le vêtement royal dont le roi se couvre et le cheval que le roi monte et sur la tête duquel se pose une couronne royale,"}, {"numero": 9, "texto": "remettre le vêtement et le cheval à l''''un des principaux chefs du roi, puis revêtir l''''homme que le roi veut honorer, le promener à cheval à travers la place de la ville, et crier devant lui: C''''est ainsi que l''''on fait à l''''homme que le roi veut honorer!"}, {"numero": 10, "texto": "Le roi dit à Haman: Prends tout de suite le vêtement et le cheval, comme tu l''''as dit, et fais ainsi pour Mardochée, le Juif, qui est assis à la porte du roi; ne néglige rien de tout ce que tu as mentionné."}, {"numero": 11, "texto": "Et Haman prit le vêtement et le cheval, il revêtit Mardochée, il le promena à cheval à travers la place de la ville, et il cria devant lui: C''''est ainsi que l''''on fait à l''''homme que le roi veut honorer!"}, {"numero": 12, "texto": "Mardochée retourna à la porte du roi, et Haman se rendit en hâte chez lui, désolé et la tête voilée."}, {"numero": 13, "texto": "Haman raconta à Zéresch, sa femme, et à tous ses amis, tout ce qui lui était arrivé. Et ses sages, et Zéresch, sa femme, lui dirent: Si Mardochée, devant lequel tu as commencé de tomber, est de la race des Juifs, tu ne pourras rien contre lui, mais tu tomberas devant lui."}, {"numero": 14, "texto": "Comme ils lui parlaient encore, les eunuques du roi arrivèrent et conduisirent aussitôt Haman au festin qu''''Esther avait préparé."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 6, 'es', '[{"numero": 1, "texto": "AQUELLA noche se le fué el sueño al rey, y dijo que le trajesen el libro de las memorias de las cosas de los tiempos: y leyéronlas delante del rey."}, {"numero": 2, "texto": "Y hallóse escrito que Mardochêo había denunciado de Bigthan y de Teres, dos eunucos del rey, de la guarda de la puerta, que habían procurado meter mano en el rey Assuero."}, {"numero": 3, "texto": "Y dijo el rey: ¿Qué honra ó que distinción se hizo á Mardochêo por esto? Y respondieron los servidores del rey, sus oficiales: Nada se ha hecho con él."}, {"numero": 4, "texto": "Entonces dijo el rey: ¿Quién está en el patio? Y Amán había venido al patio de afuera de la casa del rey, para decir al rey que hiciese colgar á Mardochêo en la horca que él le tenía preparada."}, {"numero": 5, "texto": "Y los servidores del rey le respondieron: He aquí Amán está en el patio. Y el rey dijo: Entre."}, {"numero": 6, "texto": "Entró pues Amán, y el rey le dijo: ¿Qué se hará al hombre cuya honra desea el rey? Y dijo Amán en su corazón: ¿A quién deseará el rey hacer honra más que á mí?"}, {"numero": 7, "texto": "Y respondió Amán al rey: Al varón cuya honra desea el rey,"}, {"numero": 8, "texto": "Traigan el vestido real de que el rey se viste, y el caballo en que el rey cabalga, y la corona real que está puesta en su cabeza;"}, {"numero": 9, "texto": "Y den el vestido y el caballo en mano de alguno de los príncipes más nobles del rey, y vistan á aquel varón cuya honra desea el rey, y llévenlo en el caballo por la plaza de la ciudad, y pregonen delante de él: Así se hará al varón cuya honra desea el rey."}, {"numero": 10, "texto": "Entonces el rey dijo á Amán: Date priesa, toma el vestido y el caballo, como tú has dicho, y hazlo así con el judío Mardochêo, que se sienta á la puerta del rey; no omitas nada de todo lo que has dicho."}, {"numero": 11, "texto": "Y Amán tomó el vestido y el caballo, y vistió á Mardochêo, y llevólo á caballo por la plaza de la ciudad, é hizo pregonar delante de él: Así se hará al varón cuya honra desea el rey."}, {"numero": 12, "texto": "Después de esto Mardochêo se volvió á la puerta del rey, y Amán se fué corriendo á su casa, apesadumbrado y cubierta su cabeza."}, {"numero": 13, "texto": "Contó luego Amán á Zeres su mujer, y á todos sus amigos, todo lo que le había acontecido: y dijéronle sus sabios, y Zeres su mujer: Si de la simiente de los Judíos es el Mardochêo, delante de quien has comenzado á caer, no lo vencerás; antes caerás por cierto delante de él."}, {"numero": 14, "texto": "Aun estaban ellos hablando con él, cuando los eunucos del rey llegaron apresurados, para hacer venir á Amán al banquete que Esther había dispuesto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 7, 'pt', '[{"numero": 1, "texto": "Veio, pois, o rei com Hamã para beber com a rainha Ester."}, {"numero": 2, "texto": "O rei disse também a Ester no segundo dia do banquete do vinho: Qual é tua petição, rainha Ester, para que te seja concedida? Qual é o teu pedido? Ainda que seja a metade do reino, será feito."}, {"numero": 3, "texto": "Então a rainha Ester respondeu e disse: Ó rei, se tenho achado favor em teus olhos, e se for do agrado do rei, seja me dada minha vida por minha petição, e meu povo por meu pedido."}, {"numero": 4, "texto": "Porque estamos vendidos, eu e meu povo, para sermos destruídos, mortos e exterminados. Se [apenas] fôssemos ser vendidos como escravos e escravas, eu ficaria calada, pois tal opressão não compensaria incomodar ao rei."}, {"numero": 5, "texto": "Então o rei Assuero respondeu à rainha Ester: Quem é esse, e onde está esse, que se atreveu a pensar em fazer assim?"}, {"numero": 6, "texto": "E Ester disse: O homem opressor e inimigo é este malvado Hamã. Então Hamã se perturbou diante do rei e da rainha."}, {"numero": 7, "texto": "E o rei, em seu furor, se levantou do banquete do vinho, e [foi] ao jardim do palácio; e Hamã ficou em pé para suplicar à rainha Ester por sua vida; pois entendeu que o rei já havia decidido o mal contra ele."}, {"numero": 8, "texto": "Quando o rei voltou do jardim do palácio ao lugar do banquete do vinho, Hamã estava caído sobre o leito em que Ester estava. Então disse o rei: Por acaso ele também queria abusar da rainha diante de mim nesta casa? Assim que esta palavra saiu da boca do rei, cobriram o rosto de Hamã."}, {"numero": 9, "texto": "Então Harbona, um dos eunucos que estavam na presença do rei, disse: Eis que há uma forca de cinquenta côvados de altura que Hamã fez para Mardoqueu, o qual falou para o bem do rei, junto à casa de Hamã. Então o rei disse: Enforcai-o nela."}, {"numero": 10, "texto": "Assim enforcaram a Hamã na forca que ele tinha mandado preparar para Mardoqueu; então o furor do rei se apaziguou."}]'::jsonb, 'Almeida Livre'),
  ('Et', 7, 'en', '[{"numero": 1, "texto": "So the king and Haman came to banquet with Esther the queen."}, {"numero": 2, "texto": "And the king said again unto Esther on the second day at the banquet of wine, What is thy petition, queen Esther? and it shall be granted thee: and what is thy request? and it shall be performed, even to the half of the kingdom."}, {"numero": 3, "texto": "Then Esther the queen answered and said, If I have found favour in thy sight, O king, and if it please the king, let my life be given me at my petition, and my people at my request:"}, {"numero": 4, "texto": "For we are sold, I and my people, to be destroyed, to be slain, and to perish. But if we had been sold for bondmen and bondwomen, I had held my tongue, although the enemy could not countervail the king''s damage."}, {"numero": 5, "texto": "Then the king Ahasuerus answered and said unto Esther the queen, Who is he, and where is he, that durst presume in his heart to do so?"}, {"numero": 6, "texto": "And Esther said, The adversary and enemy is this wicked Haman. Then Haman was afraid before the king and the queen."}, {"numero": 7, "texto": "And the king arising from the banquet of wine in his wrath went into the palace garden: and Haman stood up to make request for his life to Esther the queen; for he saw that there was evil determined against him by the king."}, {"numero": 8, "texto": "Then the king returned out of the palace garden into the place of the banquet of wine; and Haman was fallen upon the bed whereon Esther was. Then said the king, Will he force the queen also before me in the house? As the word went out of king''s mouth, they covered Haman''s face."}, {"numero": 9, "texto": "And Harbonah, one of the chamberlains, said before the king, Behold also, the gallows fifty cubits high, which Haman had made for Mordecai, who spoken good for the king, standeth in the house of Haman. Then the king said, Hang him thereon."}, {"numero": 10, "texto": "So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king''s wrath pacified."}]'::jsonb, 'King James Version'),
  ('Et', 7, 'fr', '[{"numero": 1, "texto": "Le roi et Haman allèrent au festin chez la reine Esther."}, {"numero": 2, "texto": "Ce second jour, le roi dit encore à Esther, pendant qu''''on buvait le vin: Quelle est ta demande, reine Esther? Elle te sera accordée. Que désires-tu? Quand ce serait la moitié du royaume, tu l''''obtiendras."}, {"numero": 3, "texto": "La reine Esther répondit: Si j''''ai trouvé grâce à tes yeux, ô roi, et si le roi le trouve bon, accorde-moi la vie, voilà ma demande, et sauve mon peuple, voilà mon désir!"}, {"numero": 4, "texto": "Car nous sommes vendus, moi et mon peuple, pour être détruits, égorgés, anéantis. Encore si nous étions vendus pour devenir esclaves et servantes, je me tairais, mais l''''ennemi ne saurait compenser le dommage fait au roi."}, {"numero": 5, "texto": "Le roi Assuérus prit la parole et dit à la reine Esther: Qui est-il et où est-il celui qui se propose d''''agir ainsi?"}, {"numero": 6, "texto": "Esther répondit: L''''oppresseur, l''''ennemi, c''''est Haman, ce méchant-là! Haman fut saisi de terreur en présence du roi et de la reine."}, {"numero": 7, "texto": "Et le roi, dans sa colère, se leva et quitta le festin, pour aller dans le jardin du palais. Haman resta pour demander grâce de la vie à la reine Esther, car il voyait bien que sa perte était arrêtée dans l''''esprit du roi."}, {"numero": 8, "texto": "Lorsque le roi revint du jardin du palais dans la salle du festin, il vit Haman qui s''''était précipité vers le lit sur lequel était Esther, et il dit: Serait-ce encore pour faire violence à la reine, chez moi, dans le palais? Dès que cette parole fut sortie de la bouche du roi, on voila le visage d''''Haman."}, {"numero": 9, "texto": "Et Harbona, l''''un des eunuques, dit en présence du roi: Voici, le bois préparé par Haman pour Mardochée, qui a parlé pour le bien du roi, est dressé dans la maison d''''Haman, à une hauteur de cinquante coudées. Le roi dit: Qu''''on y pende Haman!"}, {"numero": 10, "texto": "Et l''''on pendit Haman au bois qu''''il avait préparé pour Mardochée. Et la colère du roi s''''apaisa."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 7, 'es', '[{"numero": 1, "texto": "VINO pues el rey con Amán á beber con la reina Esther."}, {"numero": 2, "texto": "Y también el segundo día dijo el rey á Esther en el convite del vino: ¿Cuál es tu petición, reina Esther, y se te concederá? ¿Cuál es pues tu demanda? Aunque sea la mitad del reino, pondráse por obra."}, {"numero": 3, "texto": "Entonces la reina Esther respondió y dijo: Oh rey, si he hallado gracia en tus ojos, y si al rey place, séame dada mi vida por mi petición, y mi pueblo por mi demanda."}, {"numero": 4, "texto": "Porque vendidos estamos yo y mi pueblo, para ser destruídos, para ser muertos y exterminados. Y si para siervos y siervas fuéramos vendidos, callárame, bien que el enemigo no compensara el daño del rey."}, {"numero": 5, "texto": "Y respondió el rey Assuero, y dijo á la reina Esther: ¿Quién es, y dónde está, aquél á quien ha henchido su corazón para obrar así?"}, {"numero": 6, "texto": "Y Esther dijo: El enemigo y adversario es este malvado Amán. Entonces se turbó Amán delante del rey y de la reina."}, {"numero": 7, "texto": "Levantóse luego el rey del banquete del vino en su furor, y se fué al huerto del palacio: y quedóse Amán para procurar de la reina Esther por su vida; porque vió que estaba resuelto para él el mal de parte del rey."}, {"numero": 8, "texto": "Volvió después el rey del huerto del palacio al aposento del banquete del vino, y Amán había caído sobre el lecho en que estaba Esther. Entonces dijo el rey: ¿También para forzar la reina, estando conmigo en casa? Como esta palabra salió de la boca del rey, el rostro de Amán fué cubierto."}, {"numero": 9, "texto": "Y dijo Harbona, uno de los eunucos de delante del rey: He aquí también la horca de cincuenta codos de altura que hizo Amán para Mardochêo, el cual había hablado bien por el rey, está en casa de Amán. Entonces el rey dijo: Colgadlo en ella."}, {"numero": 10, "texto": "Así colgaron á Amán en la horca que él había hecho aparejar para Mardochêo; y apaciguóse la ira del rey."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 8, 'pt', '[{"numero": 1, "texto": "Naquele mesmo dia o rei Assuero deu à rainha Ester a casa de Hamã, inimigo dos judeus; e Mardoqueu veio diante do rei, porque Ester [lhe] declarara o que ele era dela."}, {"numero": 2, "texto": "E o rei tirou o seu anel que tinha tomado de Hamã, e o deu a Mardoqueu. E Ester pôs a Mardoqueu sobre [o comando] da casa de Hamã."}, {"numero": 3, "texto": "Ester falou novamente diante do rei, e lançou-se a seus pés, chorando e suplicando-lhe que revogasse a maldade de Hamã, agagita, e seu plano que tinha tramado contra os judeus."}, {"numero": 4, "texto": "Então o rei apontou para Ester o cetro de ouro; e Ester se levantou, e se pôs em pé diante do rei."}, {"numero": 5, "texto": "E disse: Se for do agrado do rei, e se tenho achado favor diante dele, e se for correto perante o rei, e se eu lhe agrado em seus olhos, escreva-se que sejam revogadas as cartas do plano de Hamã, filho de Hamedata, agagita, que ele escreveu para destruir os judeus que estão em todas as províncias do rei."}, {"numero": 6, "texto": "Pois como poderei eu ver o mal que sobrevirá a meu povo? Como poderei eu ver a destruição dos meus parentes?"}, {"numero": 7, "texto": "Então o rei Assuero respondeu à rainha Ester e ao judeu Mardoqueu: Eis que dei a Ester a casa de Hamã, e a ele enforcaram na forca, por ter tentado matar os judeus."}, {"numero": 8, "texto": "Escrevei, pois, vós aos judeus como bem vos parecer em nome do rei, e selai o com o anel do rei; porque a escritura que é selada com o anel do rei, não pode ser revogada."}, {"numero": 9, "texto": "Então foram chamados os escrivães do rei naquele mesmo instante, no terceiro mês (que é Sivã), ao [dia] vinte e três do mesmo; e escreveu-se conforme tudo quanto Mardoqueu mandou, aos judeus, como também aos sátrapas, aos governadores, e aos líderes das províncias, que [se estendem] da Índia até Cuxe, cento e vinte e sete províncias, a cada província segundo sua escrita, e a cada povo conforme sua língua; como também aos judeus conforme sua escrita, e conforme sua língua."}, {"numero": 10, "texto": "E escreveu-se em nome do rei Assuero, e selou-se com o anel do rei; e as cartas foram enviados por meio dos mensageiros por correios a cavalo, que cavalgavam sobre velozes cavalos, os quais pertenciam ao rei."}, {"numero": 11, "texto": "Que o rei concedia aos judeus que havia em todas a cidades, que se ajuntassem e se pusessem em defesa de suas vidas, para destruírem, matarem e exterminarem todas as tropas de povo e província que viesse contra eles, até a crianças como a mulheres, e [os] despojassem de seus bens;"}, {"numero": 12, "texto": "Em um mesmo dia, em todas as províncias do rei Assuero, no [dia] treze do décimo segundo mês, que é o mês de Adar."}, {"numero": 13, "texto": "A cópia da carta dada como decreto em todas as províncias foi anunciada publicamente a todos os povo, para que os judeus estivessem preparados para aquele dia, para se vingarem de seus inimigos."}, {"numero": 14, "texto": "Os mensageiros, sobre cavalos velozes, saíram apressadamente, impelidos pela ordem do rei; e o decreto também foi publicado na fortaleza de Susã."}, {"numero": 15, "texto": "Então Mardoqueu saiu de diante do rei com vestido real de azul celeste e branco, como também com uma grande coroa de ouro, e um manto de linho e púrpura; e a cidade de Susã jubilou e se alegrou."}, {"numero": 16, "texto": "[E] para os judeus houve luz, alegria, júbilo, e honra."}, {"numero": 17, "texto": "Também em cada província e em cada cidade aonde chegava a palavra do rei e seu decreto, havia entre os judeus alegria e júbilo, banquetes e dia de prazer. E muitos dos povos da terra se tornaram como judeus, porque o temor aos judeus havia caído sobre eles."}]'::jsonb, 'Almeida Livre'),
  ('Et', 8, 'en', '[{"numero": 1, "texto": "On that day did the king Ahasuerus give the house of Haman the Jews'' enemy unto Esther the queen. And Mordecai came before the king; for Esther had told what he was unto her."}, {"numero": 2, "texto": "And the king took off his ring, which he had taken from Haman, and gave it unto Mordecai. And Esther set Mordecai over the house of Haman."}, {"numero": 3, "texto": "And Esther spake yet again before the king, and fell down at his feet, and besought him with tears to put away the mischief of Haman the Agagite, and his device that he had devised against the Jews."}, {"numero": 4, "texto": "Then the king held out the golden sceptre toward Esther. So Esther arose, and stood before the king,"}, {"numero": 5, "texto": "And said, If it please the king, and if I have favour in his sight, and the thing seem right before the king, and I be pleasing in his eyes, let it be written to reverse the letters devised by Haman the son of Hammedatha the Agagite, which he wrote to destroy the Jews which are in all the king''s provinces:"}, {"numero": 6, "texto": "For how can I endure to see the evil that shall come unto my people? or how can I endure to see the destruction of my kindred?"}, {"numero": 7, "texto": "Then the king Ahasuerus said unto Esther the queen and to Mordecai the Jew, Behold, I have given Esther the house of Haman, and him they have hanged upon the gallows, because he laid his hand upon the Jews."}, {"numero": 8, "texto": "Write ye also for the Jews, as it liketh you, in the king''s name, and seal it with the king''s ring: for the writing which is written in the king''s name, and sealed with the king''s ring, may no man reverse."}, {"numero": 9, "texto": "Then were the king''s scribes called at that time in the third month, that is, the month Sivan, on the three and twentieth day thereof; and it was written according to all that Mordecai commanded unto the Jews, and to the lieutenants, and the deputies and rulers of the provinces which are from India unto Ethiopia, an hundred twenty and seven provinces, unto every province according to the writing thereof, and unto every people after their language, and to the Jews according to their writing, and according to their language."}, {"numero": 10, "texto": "And he wrote in the king Ahasuerus'' name, and sealed it with the king''s ring, and sent letters by posts on horseback, and riders on mules, camels, and young dromedaries:"}, {"numero": 11, "texto": "Wherein the king granted the Jews which were in every city to gather themselves together, and to stand for their life, to destroy, to slay and to cause to perish, all the power of the people and province that would assault them, both little ones and women, and to take the spoil of them for a prey,"}, {"numero": 12, "texto": "Upon one day in all the provinces of king Ahasuerus, namely, upon the thirteenth day of the twelfth month, which is the month Adar."}, {"numero": 13, "texto": "The copy of the writing for a commandment to be given in every province was published unto all people, and that the Jews should be ready against that day to avenge themselves on their enemies."}, {"numero": 14, "texto": "So the posts that rode upon mules and camels went out, being hastened and pressed on by the king''s commandment. And the decree was given at Shushan the palace."}, {"numero": 15, "texto": "And Mordecai went out from the presence of the king in royal apparel of blue and white, and with a great crown of gold, and with a garment of fine linen and purple: and the city of Shushan rejoiced and was glad."}, {"numero": 16, "texto": "The Jews had light, and gladness, and joy, and honour."}, {"numero": 17, "texto": "And in every province, and in every city, whithersoever the king''s commandment and his decree came, the Jews had joy and gladness, a feast and a good day. And many of the people of the land became Jews; for the fear of the Jews fell upon them."}]'::jsonb, 'King James Version'),
  ('Et', 8, 'fr', '[{"numero": 1, "texto": "En ce même jour, le roi Assuérus donna à la reine Esther la maison d''''Haman, l''''ennemi des Juifs; et Mardochée parut devant le roi, car Esther avait fait connaître la parenté qui l''''unissait à elle."}, {"numero": 2, "texto": "Le roi ôta son anneau, qu''''il avait repris à Haman, et le donna à Mardochée; Esther, de son côté, établit Mardochée sur la maison d''''Haman."}, {"numero": 3, "texto": "Puis Esther parla de nouveau en présence du roi. Elle se jeta à ses pieds, elle pleura, elle le supplia d''''empêcher les effets de la méchanceté d''''Haman, l''''Agaguite, et la réussite de ses projets contre les Juifs."}, {"numero": 4, "texto": "Le roi tendit le sceptre d''''or à Esther, qui se releva et resta debout devant le roi."}, {"numero": 5, "texto": "Elle dit alors: Si le roi le trouve bon et si j''''ai trouvé grâce devant lui, si la chose paraît convenable au roi et si je suis agréable à ses yeux, qu''''on écrive pour révoquer les lettres conçues par Haman, fils d''''Hammedatha, l''''Agaguite, et écrites par lui dans le but de faire périr les Juifs qui sont dans toutes les provinces du roi."}, {"numero": 6, "texto": "Car comment pourrais-je voir le malheur qui atteindrait mon peuple, et comment pourrais-je voir la destruction de ma race?"}, {"numero": 7, "texto": "Le roi Assuérus dit à la reine Esther et au Juif Mardochée: Voici, j''''ai donné à Esther la maison d''''Haman, et il a été pendu au bois pour avoir étendu la main contre les Juifs."}, {"numero": 8, "texto": "Ecrivez donc en faveur des Juifs comme il vous plaira, au nom du roi, et scellez avec l''''anneau du roi; car une lettre écrite au nom du roi et scellée avec l''''anneau du roi ne peut être révoquée."}, {"numero": 9, "texto": "Les secrétaires du roi furent appelés en ce temps, le vingt-troisième jour du troisième mois, qui est le mois de Sivan, et l''''on écrivit, suivant tout ce qui fut ordonné par Mardochée, aux Juifs, aux satrapes, aux gouverneurs et aux chefs des cent vingt-sept provinces situées de l''''Inde à l''''Ethiopie, à chaque province selon son écriture, à chaque peuple selon sa langue, et aux Juifs selon leur écriture et selon leur langue."}, {"numero": 10, "texto": "On écrivit au nom du roi Assuérus, et l''''on scella avec l''''anneau du roi. On envoya les lettres par des courriers ayant pour montures des chevaux et des mulets nés de juments."}, {"numero": 11, "texto": "Par ces lettres, le roi donnait aux Juifs, en quelque ville qu''''ils fussent, la permission de se rassembler et de défendre leur vie, de détruire, de tuer et de faire périr, avec leurs petits enfants et leurs femmes, tous ceux de chaque peuple et de chaque province qui prendraient les armes pour les attaquer, et de livrer leurs biens au pillage,"}, {"numero": 12, "texto": "et cela en un seul jour, dans toutes les provinces du roi Assuérus, le treizième du douzième mois, qui est le mois d''''Adar."}, {"numero": 13, "texto": "Ces lettres renfermaient une copie de l''''édit qui devait être publié dans chaque province, et informaient tous les peuples que les Juifs se tiendraient prêts pour ce jour-là à se venger de leurs ennemis."}, {"numero": 14, "texto": "Les courriers, montés sur des chevaux et des mulets, partirent aussitôt et en toute hâte, d''''après l''''ordre du roi. L''''édit fut aussi publié dans Suse, la capitale."}, {"numero": 15, "texto": "Mardochée sortit de chez le roi, avec un vêtement royal bleu et blanc, une grande couronne d''''or, et un manteau de byssus et de pourpre. La ville de Suse poussait des cris et se réjouissait."}, {"numero": 16, "texto": "Il n''''y avait pour les Juifs que bonheur et joie, allégresse et gloire."}, {"numero": 17, "texto": "Dans chaque province et dans chaque ville, partout où arrivaient l''''ordre du roi et son édit, il y eut parmi les Juifs de la joie et de l''''allégresse, des festins et des fêtes. Et beaucoup de gens d''''entre les peuples du pays se firent Juifs, car la crainte des Juifs les avait saisis."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 8, 'es', '[{"numero": 1, "texto": "EL MISMO día dió el rey Assuero á la reina Esther la casa de Amán enemigo de los Judíos; y Mardochêo vino delante del rey, porque Esther le declaró lo que era respecto de ella."}, {"numero": 2, "texto": "Y quitóse el rey su anillo que había vuelto á tomar de Amán, y diólo á Mardochêo. Y Esther puso á Mardochêo sobre la casa de Amán."}, {"numero": 3, "texto": "Volvió luego Esther á hablar delante del rey, y echóse á sus pies, llorando y rogándole que hiciese nula la maldad de Amán Agageo, y su designio que había formado contra los Judíos."}, {"numero": 4, "texto": "Entonces extendió el rey á Esther el cetro de oro, y Esther se levantó, y púsose en pie delante del rey."}, {"numero": 5, "texto": "Y dijo: Si place al rey, y si he hallado gracia delante de él, y si la cosa es recta delante del rey, y agradable yo en sus ojos, sea escrito para revocar las letras del designio de Amán hijo de Amadatha Agageo, que escribió para destruir á los Judíos que están en todas las provincias del rey."}, {"numero": 6, "texto": "Porque ¿cómo podré yo ver el mal que alcanzará á mi pueblo? ¿cómo podré yo ver la destrucción de mi nación?"}, {"numero": 7, "texto": "Y respondió el rey Assuero á la reina Esther, y á Mardochêo Judío: He aquí yo he dado á Esther la casa de Amán, y á él han colgado en la horca, por cuanto extendió su mano contra los Judíos."}, {"numero": 8, "texto": "Escribid pues vosotros á los Judíos como bien os pareciere en el nombre del rey, y selladlo con el anillo del rey; porque la escritura que se escribe en nombre del rey, y se sella con el anillo del rey, no es para revocarla."}, {"numero": 9, "texto": "Entonces fueron llamados los escribanos del rey en el mes tercero, que es Siván, á veintitrés del mismo; y escribióse conforme á todo lo que mandó Mardochêo, á los Judíos, y á los sátrapas, y á los capitanes, y á los príncipes de las provincias que había desde la India hasta la Ethiopía, ciento veintisiete provincias; á cada provincia según su escribir, y á cada pueblo conforme á su lengua, á los Judíos también conforme á su escritura y lengua."}, {"numero": 10, "texto": "Y escribió en nombre del rey Assuero, y selló con el anillo del rey, y envió letras por correos de á caballo, montados en dromedarios, y en mulos hijos de yeguas;"}, {"numero": 11, "texto": "Con intimación de que el rey concedía á los Judíos que estaban en todas las ciudades, que se juntasen y estuviesen á la defensa de su vida, prontos á destruir, y matar, y acabar con todo ejército de pueblo ó provincia que viniese contra ellos, aun niños y mujeres, y su despojo para presa,"}, {"numero": 12, "texto": "En un mismo día en todas las provincias del rey Assuero, en el trece del mes duodécimo, que es el mes de Adar."}, {"numero": 13, "texto": "La copia de la escritura que había de darse por ordenanza en cada provincia, para que fuese manifiesta á todos los pueblos, decía que los Judíos estuviesen apercibidos para aquel día, para vengarse de sus enemigos."}, {"numero": 14, "texto": "Los correos pues, cabalgando en dromedarios y en mulos, salieron apresurados y constreñidos por el mandamiento del rey: y la ley fué dada en Susán capital del reino."}, {"numero": 15, "texto": "Y salió Mardochêo de delante del rey con vestido real de cárdeno y blanco, y una gran corona de oro, y un manto de lino y púrpura: y la ciudad de Susán se alegró y regocijó."}, {"numero": 16, "texto": "Los Judíos tuvieron luz y alegría, y gozo y honra."}, {"numero": 17, "texto": "Y en cada provincia y en cada ciudad donde llegó el mandamiento del rey, los Judíos tuvieron alegría y gozo, banquete y día de placer. Y muchos de los pueblos de la tierra se hacían Judíos, porque el temor de los Judíos había caído sobre ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Et', 9, 'pt', '[{"numero": 1, "texto": "E no décimo segundo mês (que é o mês de Adar), no [dia] treze do mesmo, em que chegou o prazo para a palavra do rei se seu decreto serem executados, no mesmo dia em que os inimigos dos judeus esperavam vencê-los, sucedeu o contrário, porque foram os judeus que venceram aqueles que os odiavam."}, {"numero": 2, "texto": "Os judeus se ajuntaram em suas cidades em todas as províncias do rei Assuero, para atacarem os que procuravam lhes fazer mal; e ninguém pôde subsistir diante deles, porque o temor a eles tinha caído sobre todos os povos."}, {"numero": 3, "texto": "E todos os governadores das províncias, e os sátrapas, e os líderes, e os oficiais do rei, auxiliavam os judeus; porque o temor a Mardoqueu tinha caído sobre eles,"}, {"numero": 4, "texto": "Porque Mardoqueu era grande na casa do rei, e sua fama ia por todas as províncias; pois o homem Mardoqueu havia se engrandecido."}, {"numero": 5, "texto": "Assim os judeus feriram a todos os seus inimigos com golpes de espada, matança, e destruição; e fizeram o que quiseram daqueles que os odiavam."}, {"numero": 6, "texto": "E na fortaleza de Susã os judeus mataram e destruíram quinhentos homens,"}, {"numero": 7, "texto": "Inclusive a Parsandata, Dalfom, Aspata,"}, {"numero": 8, "texto": "Porata, Adalia, Aridata,"}, {"numero": 9, "texto": "Farmasta, Arisai, Aridai, e a Vaisata,"}, {"numero": 10, "texto": "Os dez filhos de Hamã filho de Hamedata, inimigo dos judeus; porém não puseram suas mãos no despojo."}, {"numero": 11, "texto": "No mesmo dia veio diante do rei a contagem dos mortos na fortaleza de Susã."}, {"numero": 12, "texto": "E o rei disse à rainha Ester: Na fortaleza de Susã, os judeus mataram e destruíram a quinhentos homens, e aos dez filhos de Hamã; nas demais províncias do rei, o que teriam feito? Qual pois é tua petição, para que te seja concedida? Ou qual mais é teu pedido, para que te seja feito?"}, {"numero": 13, "texto": "Então Ester disse: Se for do agrado do rei, conceda-se também amanhã aos judeus em Susã, que façam conforme a lei de hoje; e que enforquem na forca os dez filhos de Hamã."}, {"numero": 14, "texto": "Então o rei disse que assim se fizesse; e deu-se a ordem em Susã, e enforcaram aos dez filhos de Hamã."}, {"numero": 15, "texto": "E os judeus que estavam em Susã se ajuntaram também no [dia] catorze do mês de Adar, e mataram trezentos homens em Susã; porém não puseram suas mãos no despojo."}, {"numero": 16, "texto": "Também os demais judeus que estavam nas províncias do rei se ajuntaram e para se porem em defesa de sua vida, e terem repouso de seus inimigos; e mataram a setenta e cinco mil daqueles que os odiavam; porém não puseram suas mãos no despojo."}, {"numero": 17, "texto": "[Sucedeu isto] no [dia] treze do mês de Adar; e repousaram no [dia] catorze do mesmo, e fizeram dele um dia de banquetes e de alegria."}, {"numero": 18, "texto": "Também os judeus que estavam em Susã se ajuntaram nos [dias] treze e catorze do mesmo mês; e no [dia] quinze do mesmo repousaram, e fizeram daquele dia um dia de banquetes e de alegria."}, {"numero": 19, "texto": "Por isso os judeus das aldeias, que habitavam nas cidades se muros, fizeram o [dia] catorze do mês de Adar um dia de alegria, de banquetes, e dia de festejo; e de mandarem presentes uns aos outros."}, {"numero": 20, "texto": "E Mardoqueu escreveu estas coisas, e enviou cartas a todos os judeus que havia em todas as províncias do rei Assuero, próximos e distantes,"}, {"numero": 21, "texto": "Ordenando-lhes que comemorassem o décimo quarto [dia] do mês de Adar, e o décimo quinto do mesmo, todos os anos."}, {"numero": 22, "texto": "Como os dias em que os judeus tiveram repouso de seus inimigos; e o mês que tornou para eles de tristeza em alegria, e de luto em dia de festejo; para que os fizessem dias de banquetes e de alegria, e de mandarem presentes uns aos outros, e de doações aos pobres."}, {"numero": 23, "texto": "E os judeus aceitaram fazer o que já tinham começado assim como o que Mardoqueu havia lhes escrito."}, {"numero": 24, "texto": "Porque Hamã filho de Hamedata, o agagita, inimigo de todos os judeus, tinha planejado destruir todos os judeus, e lançou Pur, isto é, sorte, para os oprimir e os destruir."}, {"numero": 25, "texto": "Mas quando isto veio diante do rei, ele deu ordem por cartas, que seu plano maligno, que tramara contra os judeus, tornasse sobre sua cabeça; assim enforcaram a ele e a seus filhos na forca."}, {"numero": 26, "texto": "Por isso aqueles dias foram chamados Purim, por causa do nome Pur. Portanto, por causa de todas as palavras daquela carta; e do que testemunharam quanto a isso, e do que veio sobre eles,"}, {"numero": 27, "texto": "Os judeus confirmaram e comprometeram a si mesmos e a seus descendentes, e a todos os que se fossem próximos deles, que não deixariam de comemorar estes dois dias conforme o que foi escrito deles, e conforme seu tempo determinado, todos os anos;"}, {"numero": 28, "texto": "E que estes dias seriam lembrados e comemorados em todas as gerações, famílias, províncias, e cidades; e que estes dias de Purim não seriam ignorados pelos judeus, e que sua lembrança nunca teria fim entre seus descendentes."}, {"numero": 29, "texto": "Depois disto a rainha Ester, filha de Abiail, e o judeu Mardoqueu, escreveram com todo poder, para confirmarem pela segunda vez esta carta de Purim."}, {"numero": 30, "texto": "E foram enviadas cartas a todos os judeus, às cento e vinte e sete províncias do rei Assuero, com palavras de paz e de verdade,"}, {"numero": 31, "texto": "Para confirmarem estes dias de Purim em seus tempos determinados, conforme o judeu Mardoqueu e a rainha Ester tinham lhes confirmado, e como eles mesmos já o confirmaram para si e para seus descendentes; acerca do jejum e de seu clamor."}, {"numero": 32, "texto": "E o mandamento de Ester confirmou estas palavras dadas acerca de Purim, e escreveu-se em um livro."}]'::jsonb, 'Almeida Livre'),
  ('Et', 9, 'en', '[{"numero": 1, "texto": "Now in the twelfth month, that is, the month Adar, on the thirteenth day of the same, when the king''s commandment and his decree drew near to be put in execution, in the day that the enemies of the Jews hoped to have power over them, (though it was turned to the contrary, that the Jews had rule over them that hated them;)"}, {"numero": 2, "texto": "The Jews gathered themselves together in their cities throughout all the provinces of the king Ahasuerus, to lay hand on such as sought their hurt: and no man could withstand them; for the fear of them fell upon all people."}, {"numero": 3, "texto": "And all the rulers of the provinces, and the lieutenants, and the deputies, and officers of the king, helped the Jews; because the fear of Mordecai fell upon them."}, {"numero": 4, "texto": "For Mordecai was great in the king''s house, and his fame went out throughout all the provinces: for this man Mordecai waxed greater and greater."}, {"numero": 5, "texto": "Thus the Jews smote all their enemies with the stroke of the sword, and slaughter, and destruction, and did what they would unto those that hated them."}, {"numero": 6, "texto": "And in Shushan the palace the Jews slew and destroyed five hundred men."}, {"numero": 7, "texto": "And Parshandatha, and Dalphon, and Aspatha,"}, {"numero": 8, "texto": "And Poratha, and Adalia, and Aridatha,"}, {"numero": 9, "texto": "And Parmashta, and Arisai, and Aridai, and Vajezatha,"}, {"numero": 10, "texto": "The ten sons of Haman the son of Hammedatha, the enemy of the Jews, slew they; but on the spoil laid they not their hand."}, {"numero": 11, "texto": "On that day the number of those that were slain in Shushan the palace was brought before the king."}, {"numero": 12, "texto": "And the king said unto Esther the queen, The Jews have slain and destroyed five hundred men in Shushan the palace, and the ten sons of Haman; what have they done in the rest of the king''s provinces? now what is thy petition? and it shall be granted thee: or what is thy request further? and it shall be done."}, {"numero": 13, "texto": "Then said Esther, If it please the king, let it be granted to the Jews which are in Shushan to do to morrow also according unto this day''s decree, and let Haman''s ten sons be hanged upon the gallows."}, {"numero": 14, "texto": "And the king commanded it so to be done: and the decree was given at Shushan; and they hanged Haman''s ten sons."}, {"numero": 15, "texto": "For the Jews that were in Shushan gathered themselves together on the fourteenth day also of the month Adar, and slew three hundred men at Shushan; but on the prey they laid not their hand."}, {"numero": 16, "texto": "But the other Jews that were in the king''s provinces gathered themselves together, and stood for their lives, and had rest from their enemies, and slew of their foes seventy and five thousand, but they laid not their hands on the prey,"}, {"numero": 17, "texto": "On the thirteenth day of the month Adar; and on the fourteenth day of the same rested they, and made it a day of feasting and gladness."}, {"numero": 18, "texto": "But the Jews that were at Shushan assembled together on the thirteenth day thereof, and on the fourteenth thereof; and on the fifteenth day of the same they rested, and made it a day of feasting and gladness."}, {"numero": 19, "texto": "Therefore the Jews of the villages, that dwelt in the unwalled towns, made the fourteenth day of the month Adar a day of gladness and feasting, and a good day, and of sending portions one to another."}, {"numero": 20, "texto": "And Mordecai wrote these things, and sent letters unto all the Jews that were in all the provinces of the king Ahasuerus, both nigh and far,"}, {"numero": 21, "texto": "To stablish this among them, that they should keep the fourteenth day of the month Adar, and the fifteenth day of the same, yearly,"}, {"numero": 22, "texto": "As the days wherein the Jews rested from their enemies, and the month which was turned unto them from sorrow to joy, and from mourning into a good day: that they should make them days of feasting and joy, and of sending portions one to another, and gifts to the poor."}, {"numero": 23, "texto": "And the Jews undertook to do as they had begun, and as Mordecai had written unto them;"}, {"numero": 24, "texto": "Because Haman the son of Hammedatha, the Agagite, the enemy of all the Jews, had devised against the Jews to destroy them, and had cast Pur, that is, the lot, to consume them, and to destroy them;"}, {"numero": 25, "texto": "But when Esther came before the king, he commanded by letters that his wicked device, which he devised against the Jews, should return upon his own head, and that he and his sons should be hanged on the gallows."}, {"numero": 26, "texto": "Wherefore they called these days Purim after the name of Pur. Therefore for all the words of this letter, and of that which they had seen concerning this matter, and which had come unto them,"}, {"numero": 27, "texto": "The Jews ordained, and took upon them, and upon their seed, and upon all such as joined themselves unto them, so as it should not fail, that they would keep these two days according to their writing, and according to their appointed time every year;"}, {"numero": 28, "texto": "And that these days should be remembered and kept throughout every generation, every family, every province, and every city; and that these days of Purim should not fail from among the Jews, nor the memorial of them perish from their seed."}, {"numero": 29, "texto": "Then Esther the queen, the daughter of Abihail, and Mordecai the Jew, wrote with all authority, to confirm this second letter of Purim."}, {"numero": 30, "texto": "And he sent the letters unto all the Jews, to the hundred twenty and seven provinces of the kingdom of Ahasuerus, with words of peace and truth,"}, {"numero": 31, "texto": "To confirm these days of Purim in their times appointed, according as Mordecai the Jew and Esther the queen had enjoined them, and as they had decreed for themselves and for their seed, the matters of the fastings and their cry."}, {"numero": 32, "texto": "And the decree of Esther confirmed these matters of Purim; and it was written in the book."}]'::jsonb, 'King James Version'),
  ('Et', 9, 'fr', '[{"numero": 1, "texto": "Au douzième mois, qui est le mois d''''Adar, le treizième jour du mois, jour où devaient s''''exécuter l''''ordre et l''''édit du roi, et où les ennemis des Juifs avaient espéré dominer sur eux, ce fut le contraire qui arriva, et les Juifs dominèrent sur leurs ennemis."}, {"numero": 2, "texto": "Les Juifs se rassemblèrent dans leurs villes, dans toutes les provinces du roi Assuérus, pour mettre la main sur ceux qui cherchaient leur perte; et personne ne put leur résister, car la crainte qu''''on avait d''''eux s''''était emparée de tous les peuples."}, {"numero": 3, "texto": "Et tous les chefs des provinces, les satrapes, les gouverneurs, les fonctionnaires du roi, soutinrent les Juifs, à cause de l''''effroi que leur inspirait Mardochée."}, {"numero": 4, "texto": "Car Mardochée était puissant dans la maison du roi, et sa renommée se répandait dans toutes les provinces, parce qu''''il devenait de plus en plus puissant."}, {"numero": 5, "texto": "Les Juifs frappèrent à coups d''''épée tous leurs ennemis, ils les tuèrent et les firent périr; ils traitèrent comme il leur plut ceux qui leur étaient hostiles."}, {"numero": 6, "texto": "Dans Suse, la capitale, les Juifs tuèrent et firent périr cinq cents hommes,"}, {"numero": 7, "texto": "et ils égorgèrent Parschandatha, Dalphon, Aspatha,"}, {"numero": 8, "texto": "Poratha, Adalia, Aridatha,"}, {"numero": 9, "texto": "Parmaschtha, Arizaï, Aridaï et Vajezatha,"}, {"numero": 10, "texto": "les dix fils d''''Haman, fils d''''Hammedatha, l''''ennemi des Juifs. Mais ils ne mirent pas la main au pillage."}, {"numero": 11, "texto": "Ce jour-là, le nombre de ceux qui avaient été tués dans Suse, la capitale, parvint à la connaissance du roi."}, {"numero": 12, "texto": "Et le roi dit à la reine Esther: Les Juifs ont tué et fait périr dans Suse, la capitale, cinq cents hommes et les dix fils d''''Haman; qu''''auront-ils fait dans le reste des provinces du roi? Quelle est ta demande? Elle te sera accordée. Que désires-tu encore? Tu l''''obtiendras."}, {"numero": 13, "texto": "Esther répondit: Si le roi le trouve bon, qu''''il soit permis aux Juifs qui sont à Suse d''''agir encore demain selon le décret d''''aujourd''''hui, et que l''''on pende au bois les dix fils d''''Haman."}, {"numero": 14, "texto": "Et le roi ordonna de faire ainsi. L''''édit fut publié dans Suse. On pendit les dix fils d''''Haman;"}, {"numero": 15, "texto": "et les Juifs qui se trouvaient à Suse se rassemblèrent de nouveau le quatorzième jour du mois d''''Adar et tuèrent dans Suse trois cents hommes. Mais ils ne mirent pas la main au pillage."}, {"numero": 16, "texto": "Les autres Juifs qui étaient dans les provinces du roi se rassemblèrent et défendirent leur vie; ils se procurèrent du repos en se délivrant de leurs ennemis, et ils tuèrent soixante-quinze mille de ceux qui leur étaient hostiles. Mais ils ne mirent pas la main au pillage."}, {"numero": 17, "texto": "Ces choses arrivèrent le treizième jour du mois d''''Adar. Les Juifs se reposèrent le quatorzième, et ils en firent un jour de festin et de joie."}, {"numero": 18, "texto": "Ceux qui se trouvaient à Suse, s''''étant rassemblés le treizième jour et le quatorzième jour, se reposèrent le quinzième, et ils en firent un jour de festin et de joie."}, {"numero": 19, "texto": "C''''est pourquoi les Juifs de la campagne, qui habitent des villes sans murailles, font du quatorzième jour du mois d''''Adar un jour de joie, de festin et de fête, où l''''on s''''envoie des portions les uns aux autres."}, {"numero": 20, "texto": "Mardochée écrivit ces choses, et il envoya des lettres à tous les Juifs qui étaient dans toutes les provinces du roi Assuérus, auprès et au loin."}, {"numero": 21, "texto": "Il leur prescrivait de célébrer chaque année le quatorzième jour et le quinzième jour du mois d''''Adar"}, {"numero": 22, "texto": "comme les jours où ils avaient obtenu du repos en se délivrant de leurs ennemis, de célébrer le mois où leur tristesse avait été changée en joie et leur désolation en jour de fête, et de faire de ces jours des jours de festin et de joie où l''''on s''''envoie des portions les uns aux autres et où l''''on distribue des dons aux indigents."}, {"numero": 23, "texto": "Les Juifs s''''engagèrent à faire ce qu''''ils avaient déjà commencé et ce que Mardochée leur écrivit."}, {"numero": 24, "texto": "Car Haman, fils d''''Hammedatha, l''''Agaguite, ennemi de tous les Juifs, avait formé le projet de les faire périr, et il avait jeté le pur, c''''est-à-dire le sort, afin de les tuer et de les détruire;"}, {"numero": 25, "texto": "mais Esther s''''étant présentée devant le roi, le roi ordonna par écrit de faire retomber sur la tête d''''Haman le méchant projet qu''''il avait formé contre les Juifs, et de le pendre au bois, lui et ses fils."}, {"numero": 26, "texto": "C''''est pourquoi on appela ces jours Purim, du nom de pur. D''''après tout le contenu de cette lettre, d''''après ce qu''''ils avaient eux-mêmes vu et ce qui leur était arrivé,"}, {"numero": 27, "texto": "les Juifs prirent pour eux, pour leur postérité, et pour tous ceux qui s''''attacheraient à eux, la résolution et l''''engagement irrévocables de célébrer chaque année ces deux jours, selon le mode prescrit et au temps fixé."}, {"numero": 28, "texto": "Ces jours devaient être rappelés et célébrés de génération en génération, dans chaque famille, dans chaque province et dans chaque ville; et ces jours de Purim ne devaient jamais être abolis au milieu des Juifs, ni le souvenir s''''en effacer parmi leurs descendants."}, {"numero": 29, "texto": "La reine Esther, fille d''''Abichaïl, et le Juif Mardochée écrivirent d''''une manière pressante une seconde fois pour confirmer la lettre sur les Purim."}, {"numero": 30, "texto": "On envoya des lettres à tous les Juifs, dans les cent vingt-sept provinces du roi Assuérus. Elles contenaient des paroles de paix et de fidélité,"}, {"numero": 31, "texto": "pour prescrire ces jours de Purim au temps fixé, comme le Juif Mardochée et la reine Esther les avaient établis pour eux, et comme ils les avaient établis pour eux-mêmes et pour leur postérité, à l''''occasion de leur jeûne et de leurs cris."}, {"numero": 32, "texto": "Ainsi l''''ordre d''''Esther confirma l''''institution des Purim, et cela fut écrit dans le livre."}]'::jsonb, 'Louis Segond 1910'),
  ('Et', 9, 'es', '[{"numero": 1, "texto": "Y EN el mes duodécimo, que es el mes de Adar, á trece del mismo, en el que tocaba se ejecutase el mandamiento del rey y su ley, el mismo día en que esperaban los enemigos de los Judíos enseñorearse de ellos, fué lo contrario; porque los Judíos se enseñorearon de los que los aborrecían."}, {"numero": 2, "texto": "Los Judíos se juntaron en sus ciudades en todas las provincias del rey Assuero, para meter mano sobre los que habían procurado su mal: y nadie se puso delante de ellos, porque el temor de ellos había caído sobre todos los pueblos."}, {"numero": 3, "texto": "Y todos los príncipes de las provincias, y los virreyes, y capitanes, y oficiales del rey, ensalzaban á los Judíos; porque el temor de Mardochêo había caído sobre ellos."}, {"numero": 4, "texto": "Porque Mardochêo era grande en la casa del rey, y su fama iba por todas las provincias; pues el varón Mardochêo iba engrandeciéndose."}, {"numero": 5, "texto": "E hirieron los Judíos á todos sus enemigos con plaga de espada, y de mortandad, y de perdición; é hicieron en sus enemigos á su voluntad."}, {"numero": 6, "texto": "Y en Susán capital del reino, mataron y destruyeron los Judíos á quinientos hombres."}, {"numero": 7, "texto": "Mataron entonces á Phorsandatha, y á Dalphón, y á Asphatha,"}, {"numero": 8, "texto": "Y á Phoratha y á Ahalía, y á Aridatha,"}, {"numero": 9, "texto": "Y á Pharmastha, y á Arisai, y á Aridai, y á Vaizatha,"}, {"numero": 10, "texto": "Diez hijos de Amán hijo de Amadatha, enemigo de los Judíos: mas en la presa no metieron su mano."}, {"numero": 11, "texto": "El mismo día vino la cuenta de los muertos en Susán residencia regia, delante del rey."}, {"numero": 12, "texto": "Y dijo el rey á la reina Esther: En Susán, capital del reino, han muerto los Judíos y destruído á quinientos hombres, y á diez hijos de Amán; ¿qué habrán hecho en las otras provincias del rey? ¿Cuál pues es tu petición, y te será concedida? ¿ó qué más es tu demanda, y será hecho?"}, {"numero": 13, "texto": "Y respondió Esther: Si place al rey, concédase también mañana á los Judíos en Susán, que hagan conforme á la ley de hoy; y que cuelguen en la horca á los diez hijos de Amán."}, {"numero": 14, "texto": "Y mandó el rey que se hiciese así: y dióse la orden en Susán, y colgaron á los diez hijos de Amán."}, {"numero": 15, "texto": "Y los Judíos que estaban en Susán, se juntaron también el catorce del mes de Adar, y mataron en Susán trescientos hombres: mas en la presa no metieron su mano."}, {"numero": 16, "texto": "En cuanto á los otros Judíos que estaban en las provincias del rey, también se juntaron y pusiéronse en defensa de su vida, y tuvieron reposo de sus enemigos, y mataron de sus contrarios setenta y cinco mil; mas en la presa no metieron su mano."}, {"numero": 17, "texto": "En el día trece del mes de Adar fué esto; y reposaron en el día catorce del mismo, é hiciéronlo día de banquete y de alegría."}, {"numero": 18, "texto": "Mas los Judíos que estaban en Susán se juntaron en el trece y en el catorce del mismo mes; y al quince del mismo reposaron, é hicieron aquel día día de banquete y de regocijo."}, {"numero": 19, "texto": "Por tanto los Judíos aldeanos que habitan en las villas sin muro, hacen á los catorce del mes de Adar el día de alegría y de banquete, y buen día, y de enviar porciones cada uno á su vecino."}, {"numero": 20, "texto": "Y escribió Mardochêo estas cosas, y envió letras á todos los Judíos que estaban en todas las provincias del rey Assuero, cercanos y distantes,"}, {"numero": 21, "texto": "Ordenándoles que celebrasen el día décimocuarto del mes de Adar, y el décimoquinto del mismo, cada un año,"}, {"numero": 22, "texto": "Como días en que los Judíos tuvieron reposo de sus enemigos, y el mes que se les tornó de tristeza en alegría, y de luto en día bueno; que los hiciesen días de banquete y de gozo, y de enviar porciones cada uno á su vecino, y dádivas á los pobres."}, {"numero": 23, "texto": "Y los Judíos aceptaron hacer, según habían comenzado, lo que les escribió Mardochêo."}, {"numero": 24, "texto": "Porque Amán hijo de Amadatha, Agageo, enemigo de todos los Judíos, había ideado contra los Judíos para destruirlos, y echó Pur, que quiere decir suerte, para consumirlos y acabar con ellos."}, {"numero": 25, "texto": "Mas como Esther vino á la presencia del rey, él intimó por carta: El perverso designio que aquél trazó contra los Judíos, recaiga sobre su cabeza; y cuélguenlo á él y á sus hijos en la horca."}, {"numero": 26, "texto": "Por esto llamaron á estos días Purim, del nombre Pur. Por todas las palabras pues de esta carta, y por lo que ellos vieron sobre esto, y lo que llegó á su noticia,"}, {"numero": 27, "texto": "Establecieron y tomaron los Judíos sobre sí, y sobre su simiente, y sobre todos los allegados á ellos, y no será traspasado, el celebrar estos dos días según está escrito en orden á ellos, y conforme á su tiempo cada un año;"}, {"numero": 28, "texto": "Y que estos dos días serían en memoria, y celebrados en todas las naciones, y familias, y provincias, y ciudades. Estos días de Purim no pasarán de entre los Judíos, y la memoria de ellos no cesará de su simiente."}, {"numero": 29, "texto": "Y la reina Esther hija de Abihail, y Mardochêo Judío, escribieron con toda eficacia, para confirmar esta segunda carta de Purim."}, {"numero": 30, "texto": "Y envió Mardochêo letras á todos los Judíos, á las ciento veintisiete provincias del rey Assuero, con palabras de paz y de verdad,"}, {"numero": 31, "texto": "Para confirmar estos días de Purim en sus tiempos señalados, según les había constituído Mardochêo Judío y la reina Esther, y como habían ellos tomado sobre sí y sobre su simiente, para conmemorar el fin de los ayunos y de su clamor."}, {"numero": 32, "texto": "Y el mandamiento de Esther confirmó estas palabras dadas acerca de Purim, y escribióse en el libro."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 1, 'pt', '[{"numero": 1, "texto": "Estes são os nomes dos filhos de Israel que entraram em Egito com Jacó; cada um entrou com sua família:"}, {"numero": 2, "texto": "Rúben, Simeão, Levi e Judá;"}, {"numero": 3, "texto": "Issacar, Zebulom e Benjamim;"}, {"numero": 4, "texto": "Dã e Naftali, Gade e Aser."}, {"numero": 5, "texto": "Assim, todas as pessoas que descenderam do corpo de Jacó foram setenta. Porém José estava no Egito."}, {"numero": 6, "texto": "Depois que morreram José, todos os seus irmãos, e toda aquela geração,"}, {"numero": 7, "texto": "os filhos de Israel cresceram e multiplicaram, e foram aumentados e fortalecidos grandemente; de maneira que a terra encheu-se deles."}, {"numero": 8, "texto": "Levantou-se, entretanto, um novo rei sobre o Egito, que não conhecia José."}, {"numero": 9, "texto": "Ele disse ao seu povo: Eis que o povo dos filhos de Israel é maior e mais forte que nós;"}, {"numero": 10, "texto": "Agora, pois, sejamos astutos para com ele, a fim de que não se multiplique, e aconteça que caso venha guerra, ele se alie aos nossos inimigos, lute contra nós, e saia desta terra."}, {"numero": 11, "texto": "Então puseram sobre [o povo de Israel] capatazes para os oprimirem com trabalhos forçados; e edificaram a Faraó as cidades de armazenamento, Pitom e Ramessés."}, {"numero": 12, "texto": "Porém, quanto mais os oprimiam, mais se multiplicavam e cresciam. Por isso eles detestavam os filhos de Israel."}, {"numero": 13, "texto": "Assim os egípcios fizeram os filhos de Israel servirem duramente,"}, {"numero": 14, "texto": "e amargaram a vida deles com dura servidão, em fazerem barro e tijolos, em todo trabalho do campo, e em todo o seu serviço, ao qual os obrigavam com rigor."}, {"numero": 15, "texto": "E o rei do Egito falou às parteiras das hebreias, uma das quais se chamava Sifrá, e outra Puá, e disse-lhes:"}, {"numero": 16, "texto": "Quando fizerdes o parto das hebreias, e olhardes os assentos, se for filho, matai-o; e se for filha, então viva."}, {"numero": 17, "texto": "Mas as parteiras temeram a Deus, e não fizeram como o rei do Egito lhes mandara; em vez disso, preservaram a vida dos meninos."}, {"numero": 18, "texto": "E o rei do Egito mandou chamar às parteiras e lhes perguntou: Por que fizestes isto, que preservastes a vida dos meninos?"}, {"numero": 19, "texto": "As parteiras responderam a Faraó: As mulheres hebreias não são como as egípcias; pois são fortes, de maneira que dão à luz antes que a parteira chegue a elas."}, {"numero": 20, "texto": "E Deus fez bem às parteiras. E o povo se multiplicou, e se fortaleceu muito."}, {"numero": 21, "texto": "E por as parteiras terem temido a Deus, ele constituiu famílias a elas."}, {"numero": 22, "texto": "Então Faraó deu a todo o seu povo a seguinte ordem: Lançai no rio todo filho que nascer, e a toda filha preservai a vida."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 1, 'en', '[{"numero": 1, "texto": "Now these are the names of the children of Israel, which came into Egypt; every man and his household came with Jacob."}, {"numero": 2, "texto": "Reuben, Simeon, Levi, and Judah,"}, {"numero": 3, "texto": "Issachar, Zebulun, and Benjamin,"}, {"numero": 4, "texto": "Dan, and Naphtali, Gad, and Asher."}, {"numero": 5, "texto": "And all the souls that came out of the loins of Jacob were seventy souls: for Joseph was in Egypt already."}, {"numero": 6, "texto": "And Joseph died, and all his brethren, and all that generation."}, {"numero": 7, "texto": "And the children of Israel were fruitful, and increased abundantly, and multiplied, and waxed exceeding mighty; and the land was filled with them."}, {"numero": 8, "texto": "Now there arose up a new king over Egypt, which knew not Joseph."}, {"numero": 9, "texto": "And he said unto his people, Behold, the people of the children of Israel are more and mightier than we:"}, {"numero": 10, "texto": "Come on, let us deal wisely with them; lest they multiply, and it come to pass, that, when there falleth out any war, they join also unto our enemies, and fight against us, and so get them up out of the land."}, {"numero": 11, "texto": "Therefore they did set over them taskmasters to afflict them with their burdens. And they built for Pharaoh treasure cities, Pithom and Raamses."}, {"numero": 12, "texto": "But the more they afflicted them, the more they multiplied and grew. And they were grieved because of the children of Israel."}, {"numero": 13, "texto": "And the Egyptians made the children of Israel to serve with rigour:"}, {"numero": 14, "texto": "And they made their lives bitter with hard bondage, in morter, and in brick, and in all manner of service in the field: all their service, wherein they made them serve, was with rigour."}, {"numero": 15, "texto": "And the king of Egypt spake to the Hebrew midwives, of which the name of the one was Shiphrah, and the name of the other Puah:"}, {"numero": 16, "texto": "And he said, When ye do the office of a midwife to the Hebrew women, and see them upon the stools; if it be a son, then ye shall kill him: but if it be a daughter, then she shall live."}, {"numero": 17, "texto": "But the midwives feared God, and did not as the king of Egypt commanded them, but saved the men children alive."}, {"numero": 18, "texto": "And the king of Egypt called for the midwives, and said unto them, Why have ye done this thing, and have saved the men children alive?"}, {"numero": 19, "texto": "And the midwives said unto Pharaoh, Because the Hebrew women are not as the Egyptian women; for they are lively, and are delivered ere the midwives come in unto them."}, {"numero": 20, "texto": "Therefore God dealt well with the midwives: and the people multiplied, and waxed very mighty."}, {"numero": 21, "texto": "And it came to pass, because the midwives feared God, that he made them houses."}, {"numero": 22, "texto": "And Pharaoh charged all his people, saying, Every son that is born ye shall cast into the river, and every daughter ye shall save alive."}]'::jsonb, 'King James Version'),
  ('Ex', 1, 'fr', '[{"numero": 1, "texto": "Voici les noms des fils d''''Israël, venus en Egypte avec Jacob et la famille de chacun d''''eux:"}, {"numero": 2, "texto": "Ruben, Siméon, Lévi, Juda,"}, {"numero": 3, "texto": "Issacar, Zabulon, Benjamin,"}, {"numero": 4, "texto": "Dan, Nephthali, Gad et Aser."}, {"numero": 5, "texto": "Les personnes issues de Jacob étaient au nombre de soixante-dix en tout. Joseph était alors en Egypte."}, {"numero": 6, "texto": "Joseph mourut, ainsi que tous ses frères et toute cette génération-là."}, {"numero": 7, "texto": "Les enfants d''''Israël furent féconds et multiplièrent, ils s''''accrurent et devinrent de plus en plus puissants. Et le pays en fut rempli."}, {"numero": 8, "texto": "Il s''''éleva sur l''''Egypte un nouveau roi, qui n''''avait point connu Joseph."}, {"numero": 9, "texto": "Il dit à son peuple: Voilà les enfants d''''Israël qui forment un peuple plus nombreux et plus puissant que nous."}, {"numero": 10, "texto": "Allons! montrons-nous habiles à son égard; empêchons qu''''il ne s''''accroisse, et que, s''''il survient une guerre, il ne se joigne à nos ennemis, pour nous combattre et sortir ensuite du pays."}, {"numero": 11, "texto": "Et l''''on établit sur lui des chefs de corvées, afin de l''''accabler de travaux pénibles. C''''est ainsi qu''''il bâtit les villes de Pithom et de Ramsès, pour servir de magasins à Pharaon."}, {"numero": 12, "texto": "Mais plus on l''''accablait, plus il multipliait et s''''accroissait; et l''''on prit en aversion les enfants d''''Israël."}, {"numero": 13, "texto": "Alors les Egyptiens réduisirent les enfants d''''Israël à une dure servitude."}, {"numero": 14, "texto": "Ils leur rendirent la vie amère par de rudes travaux en argile et en briques, et par tous les ouvrages des champs: et c''''était avec cruauté qu''''ils leur imposaient toutes ces charges."}, {"numero": 15, "texto": "Le roi d''''Egypte parla aussi aux sages-femmes des Hébreux, nommées l''''une Schiphra, et l''''autre Pua."}, {"numero": 16, "texto": "Il leur dit: Quand vous accoucherez les femmes des Hébreux et que vous les verrez sur les sièges, si c''''est un garçon, faites-le mourir; si c''''est une fille, laissez-la vivre."}, {"numero": 17, "texto": "Mais les sages-femmes craignirent Dieu, et ne firent point ce que leur avait dit le roi d''''Egypte; elles laissèrent vivre les enfants."}, {"numero": 18, "texto": "Le roi d''''Egypte appela les sages-femmes, et leur dit: Pourquoi avez-vous agi ainsi, et avez-vous laissé vivre les enfants?"}, {"numero": 19, "texto": "Les sages-femmes répondirent à Pharaon: C''''est que les femmes des Hébreux ne sont pas comme les Egyptiennes; elles sont vigoureuses et elles accouchent avant l''''arrivée de la sage-femme."}, {"numero": 20, "texto": "Dieu fit du bien aux sages-femmes; et le peuple multiplia et devint très nombreux."}, {"numero": 21, "texto": "Parce que les sages-femmes avaient eu la crainte de Dieu, Dieu fit prospérer leurs maisons."}, {"numero": 22, "texto": "Alors Pharaon donna cet ordre à tout son peuple: Vous jetterez dans le fleuve tout garçon qui naîtra, et vous laisserez vivre toutes les filles."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 1, 'es', '[{"numero": 1, "texto": "ESTOS son los nombres de los hijos de Israel, que entraron en Egipto con Jacob; cada uno entró con su familia."}, {"numero": 2, "texto": "Rubén, Simeón, Leví y Judá;"}, {"numero": 3, "texto": "Issachâr, Zabulón y Benjamín;"}, {"numero": 4, "texto": "Dan y Nephtalí, Gad y Aser."}, {"numero": 5, "texto": "Y todas las almas de los que salieron del muslo de Jacob, fueron setenta. Y José estaba en Egipto."}, {"numero": 6, "texto": "Y murió José, y todos sus hermanos, y toda aquella generación."}, {"numero": 7, "texto": "Y los hijos de Israel crecieron, y multiplicaron, y fueron aumentados y corroborados en extremo; y llenóse la tierra de ellos."}, {"numero": 8, "texto": "Levantóse entretanto un nuevo rey sobre Egipto, que no conocía á José; el cual dijo á su pueblo:"}, {"numero": 9, "texto": "He aquí, el pueblo de los hijos de Israel es mayor y más fuerte que nosotros:"}, {"numero": 10, "texto": "Ahora, pues, seamos sabios para con él, porque no se multiplique, y acontezca que viniendo guerra, él también se junte con nuestros enemigos, y pelee contra nosotros, y se vaya de la tierra."}, {"numero": 11, "texto": "Entonces pusieron sobre él comisarios de tributos que los molestasen con sus cargas; y edificaron á Faraón las ciudades de los bastimentos, Phithom y Raamses."}, {"numero": 12, "texto": "Empero cuanto más los oprimían, tanto más se multiplicaban y crecían: así que estaban ellos fastidiados de los hijos de Israel."}, {"numero": 13, "texto": "Y los Egipcios hicieron servir á los hijos de Israel con dureza:"}, {"numero": 14, "texto": "Y amargaron su vida con dura servidumbre, en hacer barro y ladrillo, y en toda labor del campo, y en todo su servicio, al cual los obligaban con rigorismo."}, {"numero": 15, "texto": "Y habló el rey de Egipto á las parteras de las Hebreas, una de las cuales se llamaba Siphra, y otra Phúa, y díjoles:"}, {"numero": 16, "texto": "Cuando parteareis á las Hebreas, y mirareis los asientos, si fuere hijo, matadlo; y si fuere hija, entonces viva."}, {"numero": 17, "texto": "Mas las parteras temieron á Dios, y no hicieron como les mandó el rey de Egipto, sino que reservaban la vida á los niños."}, {"numero": 18, "texto": "Y el rey de Egipto hizo llamar á las parteras, y díjoles: Por qué habéis hecho esto, que habéis reservado la vida á los niños?"}, {"numero": 19, "texto": "Y las parteras respondieron á Faraón: Porque las mujeres Hebreas no son como las Egipcias: porque son robustas, y paren antes que la partera venga á ellas."}, {"numero": 20, "texto": "Y Dios hizo bien á las parteras: y el pueblo se multiplicó, y se corroboraron en gran manera."}, {"numero": 21, "texto": "Y por haber las parteras temido á Dios, él les hizo casas."}, {"numero": 22, "texto": "Entonces Faraón mandó á todo su pueblo, diciendo: Echad en el río todo hijo que naciere, y á toda hija reservad la vida."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 2, 'pt', '[{"numero": 1, "texto": "Um homem da família de Levi foi, e tomou por mulher uma filha de Levi:"}, {"numero": 2, "texto": "A qual concebeu, e deu à luz um filho: e vendo-o que era belo, teve-lhe escondido três meses."}, {"numero": 3, "texto": "Porém não podendo ocultar-lhe mais tempo, tomou uma cesta de juncos, e vedou-a com piche e betume, e colocou nela ao menino, e o pôs entre os juncos à beira do rio:"}, {"numero": 4, "texto": "E ficou parada uma irmã sua ao longe, para ver o que lhe aconteceria."}, {"numero": 5, "texto": "E a filha de Faraó desceu a lavar-se ao rio, e passeando suas virgens pela beira do rio, viu ela a cesta entre os juncos, e enviou uma criada sua a que a tomasse."}, {"numero": 6, "texto": "E quando a abriu, viu ao menino; e eis que o menino chorava. E tendo compaixão dele, disse: Dos meninos dos hebreus é este."}, {"numero": 7, "texto": "Então sua irmã disse à filha de Faraó: Irei a chamar-te uma ama das hebreias, para que te crie este menino?"}, {"numero": 8, "texto": "E a filha de Faraó respondeu: Vai. Então foi a virgem, e chamou à mãe do menino;"}, {"numero": 9, "texto": "À qual disse a filha de Faraó: Leva este menino, e cria-o para mim, e eu te o pagarei. E a mulher tomou ao menino, e o criou."}, {"numero": 10, "texto": "E quando cresceu o menino, ela o trouxe à filha de Faraó, a qual o adotou, e pôs-lhe por nome Moisés, dizendo: Porque das águas o tirei."}, {"numero": 11, "texto": "E naqueles dias aconteceu que, crescido já Moisés, saiu a seus irmãos, e viu suas cargas: e observou a um egípcio que feria a um dos hebreus, seus irmãos."}, {"numero": 12, "texto": "E olhou a todas as partes, e vendo que não parecia ninguém, matou ao egípcio, e escondeu-o na areia."}, {"numero": 13, "texto": "E saiu ao dia seguinte, e vendo a dois hebreus que brigavam, disse ao que fazia a injúria: Por que feres a teu próximo?"}, {"numero": 14, "texto": "E ele respondeu: Quem te pôs a ti por príncipe e juiz sobre nós? Pensas matar-me como mataste ao egípcio? Então Moisés teve medo, e disse: Certamente esta coisa é descoberta."}, {"numero": 15, "texto": "E ouvindo Faraó este negócio, procurou matar a Moisés: mas Moisés fugiu de diante de Faraó, e habitou na terra de Midiã; e sentou-se junto a um poço."}, {"numero": 16, "texto": "Tinha o sacerdote de Midiã sete filhas, as quais vieram a tirar água, para encher os bebedouros e dar de beber as ovelhas de seu pai."}, {"numero": 17, "texto": "Mas os pastores vieram, e expulsaram-nas: Então Moisés se levantou e defendeu-as, e deu de beber às suas ovelhas."}, {"numero": 18, "texto": "E voltando elas a Reuel seu pai, disse-lhes ele: Por que viestes hoje tão cedo?"}, {"numero": 19, "texto": "E elas responderam: Um homem egípcio nos defendeu da mão dos pastores, e também tirou a água, e deu de beber as as ovelhas."}, {"numero": 20, "texto": "E disse a suas filhas: E onde está? Por que deixastes esse homem? Chamai-lhe para que coma pão."}, {"numero": 21, "texto": "E Moisés concordou em morar com aquele homem; e ele deu a Moisés a sua filha Zípora:"}, {"numero": 22, "texto": "A qual lhe deu à luz um filho, e ele lhe pôs por nome Gérson: porque disse: Peregrino sou em terra alheia."}, {"numero": 23, "texto": "E aconteceu que depois de muitos dias morreu o rei do Egito, e os filhos de Israel suspiraram por causa da servidão, e clamaram: e subiu a Deus o clamor deles com motivo de sua servidão."}, {"numero": 24, "texto": "E ouviu Deus o gemido deles, e lembrou-se de seu pacto com Abraão, Isaque e Jacó."}, {"numero": 25, "texto": "Deus olhou os filhos de Israel, e Deus os reconheceu."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 2, 'en', '[{"numero": 1, "texto": "And there went a man of the house of Levi, and took to wife a daughter of Levi."}, {"numero": 2, "texto": "And the woman conceived, and bare a son: and when she saw him that he was a goodly child, she hid him three months."}, {"numero": 3, "texto": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river''s brink."}, {"numero": 4, "texto": "And his sister stood afar off, to wit what would be done to him."}, {"numero": 5, "texto": "And the daughter of Pharaoh came down to wash herself at the river; and her maidens walked along by the river''s side; and when she saw the ark among the flags, she sent her maid to fetch it."}, {"numero": 6, "texto": "And when she had opened it, she saw the child: and, behold, the babe wept. And she had compassion on him, and said, This is one of the Hebrews'' children."}, {"numero": 7, "texto": "Then said his sister to Pharaoh''s daughter, Shall I go and call to thee a nurse of the Hebrew women, that she may nurse the child for thee?"}, {"numero": 8, "texto": "And Pharaoh''s daughter said to her, Go. And the maid went and called the child''s mother."}, {"numero": 9, "texto": "And Pharaoh''s daughter said unto her, Take this child away, and nurse it for me, and I will give thee thy wages. And the women took the child, and nursed it."}, {"numero": 10, "texto": "And the child grew, and she brought him unto Pharaoh''s daughter, and he became her son. And she called his name Moses: and she said, Because I drew him out of the water."}, {"numero": 11, "texto": "And it came to pass in those days, when Moses was grown, that he went out unto his brethren, and looked on their burdens: and he spied an Egyptian smiting an Hebrew, one of his brethren."}, {"numero": 12, "texto": "And he looked this way and that way, and when he saw that there was no man, he slew the Egyptian, and hid him in the sand."}, {"numero": 13, "texto": "And when he went out the second day, behold, two men of the Hebrews strove together: and he said to him that did the wrong, Wherefore smitest thou thy fellow?"}, {"numero": 14, "texto": "And he said, Who made thee a prince and a judge over us? intendest thou to kill me, as thou killedst the Egyptian? And Moses feared, and said, Surely this thing is known."}, {"numero": 15, "texto": "Now when Pharaoh heard this thing, he sought to slay Moses. But Moses fled from the face of Pharaoh, and dwelt in the land of Midian: and he sat down by a well."}, {"numero": 16, "texto": "Now the priest of Midian had seven daughters: and they came and drew water, and filled the troughs to water their father''s flock."}, {"numero": 17, "texto": "And the shepherds came and drove them away: but Moses stood up and helped them, and watered their flock."}, {"numero": 18, "texto": "And when they came to Reuel their father, he said, How is it that ye are come so soon to day?"}, {"numero": 19, "texto": "And they said, An Egyptian delivered us out of the hand of the shepherds, and also drew water enough for us, and watered the flock."}, {"numero": 20, "texto": "And he said unto his daughters, And where is he? why is it that ye have left the man? call him, that he may eat bread."}, {"numero": 21, "texto": "And Moses was content to dwell with the man: and he gave Moses Zipporah his daughter."}, {"numero": 22, "texto": "And she bare him a son, and he called his name Gershom: for he said, I have been a stranger in a strange land."}, {"numero": 23, "texto": "And it came to pass in process of time, that the king of Egypt died: and the children of Israel sighed by reason of the bondage, and they cried, and their cry came up unto God by reason of the bondage."}, {"numero": 24, "texto": "And God heard their groaning, and God remembered his covenant with Abraham, with Isaac, and with Jacob."}, {"numero": 25, "texto": "And God looked upon the children of Israel, and God had respect unto them."}]'::jsonb, 'King James Version'),
  ('Ex', 2, 'fr', '[{"numero": 1, "texto": "Un homme de la maison de Lévi avait pris pour femme une fille de Lévi."}, {"numero": 2, "texto": "Cette femme devint enceinte et enfanta un fils. Elle vit qu''''il était beau, et elle le cacha pendant trois mois."}, {"numero": 3, "texto": "Ne pouvant plus le cacher, elle prit une caisse de jonc, qu''''elle enduisit de bitume et de poix; elle y mit l''''enfant, et le déposa parmi les roseaux, sur le bord du fleuve."}, {"numero": 4, "texto": "La soeur de l''''enfant se tint à quelque distance, pour savoir ce qui lui arriverait."}, {"numero": 5, "texto": "La fille de Pharaon descendit au fleuve pour se baigner, et ses compagnes se promenèrent le long du fleuve. Elle aperçut la caisse au milieu des roseaux, et elle envoya sa servante pour la prendre."}, {"numero": 6, "texto": "Elle l''''ouvrit, et vit l''''enfant: c''''était un petit garçon qui pleurait. Elle en eut pitié, et elle dit: C''''est un enfant des Hébreux!"}, {"numero": 7, "texto": "Alors la soeur de l''''enfant dit à la fille de Pharaon: Veux-tu que j''''aille te chercher une nourrice parmi les femmes des Hébreux, pour allaiter cet enfant?"}, {"numero": 8, "texto": "Va, lui répondit la fille de Pharaon. Et la jeune fille alla chercher la mère de l''''enfant."}, {"numero": 9, "texto": "La fille de Pharaon lui dit: Emporte cet enfant, et allaite-le-moi; je te donnerai ton salaire. La femme prit l''''enfant, et l''''allaita."}, {"numero": 10, "texto": "Quand il eut grandi, elle l''''amena à la fille de Pharaon, et il fut pour elle comme un fils. Elle lui donna le nom de Moïse, car, dit-elle, je l''''ai retiré des eaux."}, {"numero": 11, "texto": "En ce temps-là, Moïse, devenu grand, se rendit vers ses frères, et fut témoin de leurs pénibles travaux. Il vit un Egyptien qui frappait un Hébreu d''''entre ses frères."}, {"numero": 12, "texto": "Il regarda de côté et d''''autre, et, voyant qu''''il n''''y avait personne, il tua l''''Egyptien, et le cacha dans le sable."}, {"numero": 13, "texto": "Il sortit le jour suivant; et voici, deux Hébreux se querellaient. Il dit à celui qui avait tort: Pourquoi frappes-tu ton prochain?"}, {"numero": 14, "texto": "Et cet homme répondit: Qui t''''a établi chef et juge sur nous? Penses-tu me tuer, comme tu as tué l''''Egyptien? Moïse eut peur, et dit: Certainement la chose est connue."}, {"numero": 15, "texto": "Pharaon apprit ce qui s''''était passé, et il cherchait à faire mourir Moïse. Mais Moïse s''''enfuit de devant Pharaon, et il se retira dans le pays de Madian, où il s''''arrêta près d''''un puits."}, {"numero": 16, "texto": "Le sacrificateur de Madian avait sept filles. Elles vinrent puiser de l''''eau, et elles remplirent les auges pour abreuver le troupeau de leur père."}, {"numero": 17, "texto": "Les bergers arrivèrent, et les chassèrent. Alors Moïse se leva, prit leur défense, et fit boire leur troupeau."}, {"numero": 18, "texto": "Quand elles furent de retour auprès de Réuel, leur père, il dit: Pourquoi revenez-vous si tôt aujourd''''hui?"}, {"numero": 19, "texto": "Elles répondirent: Un Egyptien nous a délivrées de la main des bergers, et même il nous a puisé de l''''eau, et a fait boire le troupeau."}, {"numero": 20, "texto": "Et il dit à ses filles: Où est-il? Pourquoi avez-vous laissé cet homme? Appelez-le, pour qu''''il prenne quelque nourriture."}, {"numero": 21, "texto": "Moïse se décida à demeurer chez cet homme, qui lui donna pour femme Séphora, sa fille."}, {"numero": 22, "texto": "Elle enfanta un fils, qu''''il appela du nom de Guerschom, car, dit-il, j''''habite un pays étranger."}, {"numero": 23, "texto": "Longtemps après, le roi d''''Egypte mourut, et les enfants d''''Israël gémissaient encore sous la servitude, et poussaient des cris. Ces cris, que leur arrachait la servitude, montèrent jusqu''''à Dieu."}, {"numero": 24, "texto": "Dieu entendit leurs gémissements, et se souvint de son alliance avec Abraham, Isaac et Jacob."}, {"numero": 25, "texto": "Dieu regarda les enfants d''''Israël, et il en eut compassion."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 2, 'es', '[{"numero": 1, "texto": "UN varón de la familia de Leví fué, y tomó por mujer una hija de Leví:"}, {"numero": 2, "texto": "La cual concibió, y parió un hijo: y viéndolo que era hermoso, túvole escondido tres meses."}, {"numero": 3, "texto": "Pero no pudiendo ocultarle más tiempo, tomó una arquilla de juncos, y calafateóla con pez y betún, y colocó en ella al niño, y púsolo en un carrizal á la orilla del río:"}, {"numero": 4, "texto": "Y paróse una hermana suya á lo lejos, para ver lo que le acontecería."}, {"numero": 5, "texto": "Y la hija de Faraón descendió á lavarse al río, y paseándose sus doncellas por la ribera del río, vió ella la arquilla en el carrizal, y envió una criada suya á que la tomase."}, {"numero": 6, "texto": "Y como la abrió, vió al niño; y he aquí que el niño lloraba. Y teniendo compasión de él, dijo: De los niños de los Hebreos es éste."}, {"numero": 7, "texto": "Entonces su hermana dijo á la hija de Faraón: ¿Iré á llamarte un ama de las Hebreas, para que te críe este niño?"}, {"numero": 8, "texto": "Y la hija de Faraón respondió: Ve. Entonces fué la doncella, y llamó á la madre del niño;"}, {"numero": 9, "texto": "A la cual dijo la hija de Faraón: Lleva este niño, y críamelo, y yo te lo pagaré. Y la mujer tomó al niño, y criólo."}, {"numero": 10, "texto": "Y como creció el niño, ella lo trajo á la hija de Faraón, la cual lo prohijó, y púsole por nombre Moisés, diciendo: Porque de las aguas lo saqué."}, {"numero": 11, "texto": "Y en aquellos días acaeció que, crecido ya Moisés, salió á sus hermanos, y vió sus cargas: y observó á un Egipcio que hería á uno de los Hebreos, sus hermanos."}, {"numero": 12, "texto": "Y miró á todas partes, y viendo que no parecía nadie, mató al Egipcio, y escondiólo en la arena."}, {"numero": 13, "texto": "Y salió al día siguiente, y viendo á dos Hebreos que reñían, dijo al que hacía la injuria: ¿Por qué hieres á tu prójimo?"}, {"numero": 14, "texto": "Y él respondió: ¿Quién te ha puesto á ti por príncipe y juez sobre nosotros? ¿piensas matarme como mataste al Egipcio? Entonces Moisés tuvo miedo, y dijo: Ciertamente esta cosa es descubierta."}, {"numero": 15, "texto": "Y oyendo Faraón este negocio, procuró matar á Moisés: mas Moisés huyó de delante de Faraón, y habitó en la tierra de Madián; y sentóse junto á un pozo."}, {"numero": 16, "texto": "Tenía el sacerdote de Madián siete hijas, las cuales vinieron á sacar agua, para llenar las pilas y dar de beber á las ovejas de su padre."}, {"numero": 17, "texto": "Mas los pastores vinieron, y echáronlas: Entonces Moisés se levantó y defendiólas, y abrevó sus ovejas."}, {"numero": 18, "texto": "Y volviendo ellas á Ragüel su padre, díjoles él: ¿Por qué habéis hoy venido tan presto?"}, {"numero": 19, "texto": "Y ellas respondieron: Un varón Egipcio nos defendió de mano de los pastores, y también nos sacó el agua, y abrevó las ovejas."}, {"numero": 20, "texto": "Y dijo á sus hijas: ¿Y dónde está? ¿por qué habéis dejado ese hombre? llamadle para que coma pan."}, {"numero": 21, "texto": "Y Moisés acordó en morar con aquel varón; y él dió á Moisés á su hija Séphora:"}, {"numero": 22, "texto": "La cual le parió un hijo, y él le puso por nombre Gersom: porque dijo: Peregrino soy en tierra ajena."}, {"numero": 23, "texto": "Y aconteció que después de muchos días murió el rey de Egipto, y los hijos de Israel suspiraron á causa de la servidumbre, y clamaron: y subió á Dios el clamor de ellos con motivo de su servidumbre."}, {"numero": 24, "texto": "Y oyó Dios el gemido de ellos, y acordóse de su pacto con Abraham, Isaac y Jacob."}, {"numero": 25, "texto": "Y miró Dios á los hijos de Israel, y reconociólos Dios."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 3, 'pt', '[{"numero": 1, "texto": "E apascentando Moisés as ovelhas de Jetro seu sogro, sacerdote de Midiã, levou as ovelhas ao outro lado do deserto, e veio a Horebe, monte de Deus."}, {"numero": 2, "texto": "E apareceu-lhe o anjo do SENHOR em uma chama de fogo em meio de uma sarça: e ele olhou, e viu que a sarça ardia em fogo, e a sarça não se consumia."}, {"numero": 3, "texto": "Então Moisés disse: Irei eu agora, e verei esta grande visão, por que causa a sarça não se queima."}, {"numero": 4, "texto": "E quando o SENHOR viu que ia ver, Deus o chamou do meio da sarça, e disse: Moisés, Moisés! E ele respondeu: Eis-me aqui."}, {"numero": 5, "texto": "E disse: Não te aproximes daqui; tira teus calçados de teus pés, porque o lugar em que estás é terra santa."}, {"numero": 6, "texto": "E disse: Eu sou o Deus de teu pai, Deus de Abraão, Deus de Isaque, Deus de Jacó. Então Moisés cobriu seu rosto, porque teve medo de olhar a Deus."}, {"numero": 7, "texto": "E disse o SENHOR: Vi a aflição do meu povo que está no Egito, e ouvi seu clamor por causa de seus opressores; pois conheço suas angústias."}, {"numero": 8, "texto": "Por isso desci para livrá-los da mão dos egípcios, e tirá-los daquela terra, fazendo-os subir para uma terra boa e larga, para uma terra que flui leite e mel, para o lugar dos cananeus, dos heteus, dos amorreus, dos perizeus, dos heveus e dos jebuseus."}, {"numero": 9, "texto": "Eis que o clamor dos filhos de Israel veio a mim, e tenho visto a opressão com que os egípcios os oprimem."}, {"numero": 10, "texto": "Vem, pois, agora, e te enviarei a Faraó, para que tires meu povo, os filhos de Israel, do Egito."}, {"numero": 11, "texto": "Então Moisés respondeu a Deus: Quem sou eu, para que vá a Faraó, e tire do Egito aos filhos de Israel?"}, {"numero": 12, "texto": "E ele lhe respondeu: Vai, porque eu serei contigo; e isto te será por sinal de que eu te enviei: logo que houveres tirado este povo do Egito, servireis a Deus sobre este monte."}, {"numero": 13, "texto": "E disse Moisés a Deus: Eis que, quando eu chegar aos filhos de Israel, e lhes disser, O Deus de vossos pais me enviou a vós; se eles me perguntarem: Qual é seu nome? que lhes responderei?"}, {"numero": 14, "texto": "Deus respondeu a Moisés: EU SOU O QUE SOU. E disse: Assim dirás aos filhos de Israel: EU SOU me enviou a vós."}, {"numero": 15, "texto": "E disse mais Deus a Moisés: Assim dirás aos filhos de Israel: o SENHOR, o Deus de vossos pais, o Deus de Abraão, Deus de Isaque e Deus de Jacó, me enviou a vós. Este é meu nome para sempre, este é meu memorial por todos os séculos."}, {"numero": 16, "texto": "Vai, e junta os anciãos de Israel, e dize-lhes: O SENHOR, o Deus de vossos pais, o Deus de Abraão, de Isaque, e de Jacó, me apareceu, dizendo: Certamente vos visitei, e vi o que se faz convosco no Egito;"}, {"numero": 17, "texto": "E disse: Eu vos tirarei da aflição do Egito à terra dos cananeus, e dos heteus, e dos amorreus, e dos perizeus, e dos heveus, e dos jebuseus, a uma terra que flui leite e mel."}, {"numero": 18, "texto": "E ouvirão tua voz; e irás tu, e os anciãos de Israel, ao rei do Egito, e lhe direis: O SENHOR, o Deus dos hebreus, nos encontrou; portanto nós iremos agora caminho de três dias pelo deserto, para que sacrifiquemos ao SENHOR nosso Deus."}, {"numero": 19, "texto": "Mas eu sei que o rei do Egito não vos deixará ir a não ser por mão forte."}, {"numero": 20, "texto": "Porém eu estenderei minha mão, e ferirei ao Egito com todas minhas maravilhas que farei nele, e então vos deixará ir."}, {"numero": 21, "texto": "E eu darei a este povo favor aos olhos dos egípcios, para que quando vos partirdes, não saiais vazios:"}, {"numero": 22, "texto": "Em vez disso pedirá cada mulher à sua vizinha e à sua visitante vasos de prata, vasos de ouro, e roupas; os quais poreis sobre vossos filhos e vossas filhas, e despojareis ao Egito."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 3, 'en', '[{"numero": 1, "texto": "Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb."}, {"numero": 2, "texto": "And the angel of the Lord appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed."}, {"numero": 3, "texto": "And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt."}, {"numero": 4, "texto": "And when the Lord saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here am I."}, {"numero": 5, "texto": "And he said, Draw not nigh hither: put off thy shoes from off thy feet, for the place whereon thou standest is holy ground."}, {"numero": 6, "texto": "Moreover he said, I am the God of thy father, the God of Abraham, the God of Isaac, and the God of Jacob. And Moses hid his face; for he was afraid to look upon God."}, {"numero": 7, "texto": "And the Lord said, I have surely seen the affliction of my people which are in Egypt, and have heard their cry by reason of their taskmasters; for I know their sorrows;"}, {"numero": 8, "texto": "And I am come down to deliver them out of the hand of the Egyptians, and to bring them up out of that land unto a good land and a large, unto a land flowing with milk and honey; unto the place of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites."}, {"numero": 9, "texto": "Now therefore, behold, the cry of the children of Israel is come unto me: and I have also seen the oppression wherewith the Egyptians oppress them."}, {"numero": 10, "texto": "Come now therefore, and I will send thee unto Pharaoh, that thou mayest bring forth my people the children of Israel out of Egypt."}, {"numero": 11, "texto": "And Moses said unto God, Who am I, that I should go unto Pharaoh, and that I should bring forth the children of Israel out of Egypt?"}, {"numero": 12, "texto": "And he said, Certainly I will be with thee; and this shall be a token unto thee, that I have sent thee: When thou hast brought forth the people out of Egypt, ye shall serve God upon this mountain."}, {"numero": 13, "texto": "And Moses said unto God, Behold, when I come unto the children of Israel, and shall say unto them, The God of your fathers hath sent me unto you; and they shall say to me, What is his name? what shall I say unto them?"}, {"numero": 14, "texto": "And God said unto Moses, I Am That I Am: and he said, Thus shalt thou say unto the children of Israel, I Am hath sent me unto you."}, {"numero": 15, "texto": "And God said moreover unto Moses, Thus shalt thou say unto the children of Israel, the Lord God of your fathers, the God of Abraham, the God of Isaac, and the God of Jacob, hath sent me unto you: this is my name for ever, and this is my memorial unto all generations."}, {"numero": 16, "texto": "Go, and gather the elders of Israel together, and say unto them, The Lord God of your fathers, the God of Abraham, of Isaac, and of Jacob, appeared unto me, saying, I have surely visited you, and seen that which is done to you in Egypt:"}, {"numero": 17, "texto": "And I have said, I will bring you up out of the affliction of Egypt unto the land of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites, unto a land flowing with milk and honey."}, {"numero": 18, "texto": "And they shall hearken to thy voice: and thou shalt come, thou and the elders of Israel, unto the king of Egypt, and ye shall say unto him, The Lord God of the Hebrews hath met with us: and now let us go, we beseech thee, three days'' journey into the wilderness, that we may sacrifice to the Lord our God."}, {"numero": 19, "texto": "And I am sure that the king of Egypt will not let you go, no, not by a mighty hand."}, {"numero": 20, "texto": "And I will stretch out my hand, and smite Egypt with all my wonders which I will do in the midst thereof: and after that he will let you go."}, {"numero": 21, "texto": "And I will give this people favour in the sight of the Egyptians: and it shall come to pass, that, when ye go, ye shall not go empty."}, {"numero": 22, "texto": "But every woman shall borrow of her neighbour, and of her that sojourneth in her house, jewels of silver, and jewels of gold, and raiment: and ye shall put them upon your sons, and upon your daughters; and ye shall spoil the Egyptians."}]'::jsonb, 'King James Version'),
  ('Ex', 3, 'fr', '[{"numero": 1, "texto": "Moïse faisait paître le troupeau de Jéthro, son beau-père, sacrificateur de Madian; et il mena le troupeau derrière le désert, et vint à la montagne de Dieu, à Horeb."}, {"numero": 2, "texto": "L''''ange de l''''Eternel lui apparut dans une flamme de feu, au milieu d''''un buisson. Moïse regarda; et voici, le buisson était tout en feu, et le buisson ne se consumait point."}, {"numero": 3, "texto": "Moïse dit: Je veux me détourner pour voir quelle est cette grande vision, et pourquoi le buisson ne se consume point."}, {"numero": 4, "texto": "L''''Eternel vit qu''''il se détournait pour voir; et Dieu l''''appela du milieu du buisson, et dit: Moïse! Moïse! Et il répondit: Me voici!"}, {"numero": 5, "texto": "Dieu dit: N''''approche pas d''''ici, ôte tes souliers de tes pieds, car le lieu sur lequel tu te tiens est une terre sainte."}, {"numero": 6, "texto": "Et il ajouta: Je suis le Dieu de ton père, le Dieu d''''Abraham, le Dieu d''''Isaac et le Dieu de Jacob. Moïse se cacha le visage, car il craignait de regarder Dieu."}, {"numero": 7, "texto": "L''''Eternel dit: J''''ai vu la souffrance de mon peuple qui est en Egypte, et j''''ai entendu les cris que lui font pousser ses oppresseurs, car je connais ses douleurs."}, {"numero": 8, "texto": "Je suis descendu pour le délivrer de la main des Egyptiens, et pour le faire monter de ce pays dans un bon et vaste pays, dans un pays où coulent le lait et le miel, dans les lieux qu''''habitent les Cananéens, les Héthiens, les Amoréens, les Phéréziens, les Héviens et les Jébusiens."}, {"numero": 9, "texto": "Voici, les cris d''''Israël sont venus jusqu''''à moi, et j''''ai vu l''''oppression que leur font souffrir les Egyptiens."}, {"numero": 10, "texto": "Maintenant, va, je t''''enverrai auprès de Pharaon, et tu feras sortir d''''Egypte mon peuple, les enfants d''''Israël."}, {"numero": 11, "texto": "Moïse dit à Dieu: Qui suis-je, pour aller vers Pharaon, et pour faire sortir d''''Egypte les enfants d''''Israël?"}, {"numero": 12, "texto": "Dieu dit: Je serai avec toi; et ceci sera pour toi le signe que c''''est moi qui t''''envoie: quand tu auras fait sortir d''''Egypte le peuple, vous servirez Dieu sur cette montagne."}, {"numero": 13, "texto": "Moïse dit à Dieu: J''''irai donc vers les enfants d''''Israël, et je leur dirai: Le Dieu de vos pères m''''envoie vers vous. Mais, s''''ils me demandent quel est son nom, que leur répondrai-je?"}, {"numero": 14, "texto": "Dieu dit à Moïse: Je suis celui qui suis. Et il ajouta: C''''est ainsi que tu répondras aux enfants d''''Israël: Celui qui s''''appelle \"je suis\" m''''a envoyé vers vous."}, {"numero": 15, "texto": "Dieu dit encore à Moïse: Tu parleras ainsi aux enfants d''''Israël: L''''Eternel, le Dieu de vos pères, le Dieu d''''Abraham, le Dieu d''''Isaac et le Dieu de Jacob, m''''envoie vers vous. Voilà mon nom pour l''''éternité, voilà mon nom de génération en génération."}, {"numero": 16, "texto": "Va, rassemble les anciens d''''Israël, et dis-leur: L''''Eternel, le Dieu de vos pères, m''''est apparu, le Dieu d''''Abraham, d''''Isaac et de Jacob. Il a dit: Je vous ai vus, et j''''ai vu ce qu''''on vous fait en Egypte,"}, {"numero": 17, "texto": "et j''''ai dit: Je vous ferai monter de l''''Egypte, où vous souffrez, dans le pays des Cananéens, des Héthiens, des Amoréens, des Phéréziens, des Héviens et des Jébusiens, dans un pays où coulent le lait et le miel."}, {"numero": 18, "texto": "Ils écouteront ta voix; et tu iras, toi et les anciens d''''Israël, auprès du roi d''''Egypte, et vous lui direz: L''''Eternel, le Dieu des Hébreux, nous est apparu. Permets-nous de faire trois journées de marche dans le désert, pour offrir des sacrifices à l''''Eternel, notre Dieu."}, {"numero": 19, "texto": "Je sais que le roi d''''Egypte ne vous laissera point aller, si ce n''''est par une main puissante."}, {"numero": 20, "texto": "J''''étendrai ma main, et je frapperai l''''Egypte par toutes sortes de prodiges que je ferai au milieu d''''elle. Après quoi, il vous laissera aller."}, {"numero": 21, "texto": "Je ferai même trouver grâce à ce peuple aux yeux des Egyptiens, et quand vous partirez, vous ne partirez point à vide."}, {"numero": 22, "texto": "Chaque femme demandera à sa voisine et à celle qui demeure dans sa maison des vases d''''argent, des vases d''''or, et des vêtements, que vous mettrez sur vos fils et vos filles. Et vous dépouillerez les Egyptiens."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 3, 'es', '[{"numero": 1, "texto": "Y APACENTANDO Moisés las ovejas de Jethro su suegro, sacerdote de Madián, llevó las ovejas detrás del desierto, y vino á Horeb, monte de Dios."}, {"numero": 2, "texto": "Y apareciósele el Angel de Jehová en una llama de fuego en medio de una zarza: y él miró, y vió que la zarza ardía en fuego, y la zarza no se consumía."}, {"numero": 3, "texto": "Entonces Moisés dijo: Iré yo ahora, y veré esta grande visión, por qué causa la zarza no se quema."}, {"numero": 4, "texto": "Y viendo Jehová que iba á ver, llamólo Dios de en medio de la zarza, y dijo: ¡Moisés, Moisés! Y él respondió: Heme aquí."}, {"numero": 5, "texto": "Y dijo: No te llegues acá: quita tus zapatos de tus pies, porque el lugar en que tú estás, tierra santa es."}, {"numero": 6, "texto": "Y dijo: Yo soy el Dios de tu padre, Dios de Abraham, Dios de Isaac, Dios de Jacob. Entonces Moisés cubrió su rostro, porque tuvo miedo de mirar á Dios."}, {"numero": 7, "texto": "Y dijo Jehová: Bien he visto la aflicción de mi pueblo que está en Egipto, y he oído su clamor á causa de sus exactores; pues tengo conocidas sus angustias:"}, {"numero": 8, "texto": "Y he descendido para librarlos de mano de los Egipcios, y sacarlos de aquella tierra á una tierra buena y ancha, á tierra que fluye leche y miel, á los lugares del Cananeo, del Hetheo, del Amorrheo, del Pherezeo, del Heveo, y del Jebuseo."}, {"numero": 9, "texto": "El clamor, pues, de los hijos de Israel ha venido delante de mí, y también he visto la opresión con que los Egipcios los oprimen."}, {"numero": 10, "texto": "Ven por tanto ahora, y enviarte he á Faraón, para que saques á mi pueblo, los hijos de Israel, de Egipto."}, {"numero": 11, "texto": "Entonces Moisés respondió á Dios: ¿Quién soy yo, para que vaya á Faraón, y saque de Egipto á los hijos de Israel?"}, {"numero": 12, "texto": "Y él le respondió: Ve, porque yo seré contigo; y esto te será por señal de que yo te he enviado: luego que hubieres sacado este pueblo de Egipto, serviréis á Dios sobre este monte."}, {"numero": 13, "texto": "Y dijo Moisés á Dios: He aquí que llego yo á los hijos de Israel, y les digo, El Dios de vuestros padres me ha enviado á vosotros; si ellos me preguntaren: ¿Cuál es su nombre? ¿qué les responderé?"}, {"numero": 14, "texto": "Y respondió Dios á Moisés: YO SOY EL QUE SOY. Y dijo: Así dirás á los hijos de Israel: YO SOY me ha enviado á vosotros."}, {"numero": 15, "texto": "Y dijo más Dios á Moisés: Así dirás á los hijos de Israel: Jehová, el Dios de vuestros padres, el Dios de Abraham, Dios de Isaac y Dios de Jacob, me ha enviado á vosotros. Este es mi nombre para siempre, este es mi memorial por todos los siglos."}, {"numero": 16, "texto": "Ve, y junta los ancianos de Israel, y diles: Jehová, el Dios de vuestros padres, el Dios de Abraham, de Isaac, y de Jacob, me apareció, diciendo: De cierto os he visitado, y visto lo que se os hace en Egipto;"}, {"numero": 17, "texto": "Y he dicho: Yo os sacaré de la aflicción de Egipto á la tierra del Cananeo, y del Hetheo, y del Amorrheo, y del Pherezeo, y del Heveo, y del Jebuseo, á una tierra que fluye leche y miel."}, {"numero": 18, "texto": "Y oirán tu voz; é irás tú, y los ancianos de Israel, al rey de Egipto, y le diréis: Jehová, el Dios de los Hebreos, nos ha encontrado; por tanto nosotros iremos ahora camino de tres días por el desierto, para que sacrifiquemos á Jehová nuestro Dios."}, {"numero": 19, "texto": "Mas yo sé que el rey de Egipto no os dejará ir sino por mano fuerte."}, {"numero": 20, "texto": "Empero yo extenderé mi mano, y heriré á Egipto con todas mis maravillas que haré en él, y entonces os dejará ir."}, {"numero": 21, "texto": "Y yo daré á este pueblo gracia en los ojos de los Egipcios, para que cuando os partiereis, no salgáis vacíos:"}, {"numero": 22, "texto": "Sino que demandará cada mujer á su vecina y á su huéspeda vasos de plata, vasos de oro, y vestidos: los cuales pondréis sobre vuestros hijos y vuestras hijas; y despojaréis á Egipto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 4, 'pt', '[{"numero": 1, "texto": "Então Moisés respondeu, e disse: Eis que eles não crerão em mim, nem ouvirão minha voz; porque dirão: O SENHOR não apareceu a ti."}, {"numero": 2, "texto": "E o SENHOR disse: Que é isso que tens em tua mão? E ele respondeu: Uma vara."}, {"numero": 3, "texto": "E ele lhe disse: Lança-a em terra. E ele a lançou em terra, e tornou-se uma cobra: e Moisés fugia dela."}, {"numero": 4, "texto": "Então disse o SENHOR a Moisés: Estende tua mão, e toma-a pela cauda. E ele estendeu sua mão, e tomou-a, e tornou-se vara em sua mão."}, {"numero": 5, "texto": "Por isto crerão que se te apareceu o SENHOR, o Deus de teus pais, o Deus de Abraão, Deus de Isaque, e Deus de Jacó."}, {"numero": 6, "texto": "E disse-lhe mais o SENHOR: Mete agora tua mão em teu peito. E ele meteu a mão em seu peito; e quando a tirou, eis que sua mão estava leprosa como a neve."}, {"numero": 7, "texto": "E disse: Volta a meter tua mão em teu peito; e ele voltou a meter sua mão em seu peito; e voltando-a a tirar do peito, eis que se havia voltado como a outra carne."}, {"numero": 8, "texto": "Se acontecer, que não te crerem, nem obedecerem à voz do primeiro sinal, crerão à voz do último."}, {"numero": 9, "texto": "E se ainda não crerem nestes dois sinais, nem ouvirem tua voz, tomarás das águas do rio, e as derramará em terra; e se tornarão aquelas águas que tomarás do rio, se tornarão sangue na terra."}, {"numero": 10, "texto": "Então disse Moisés ao SENHOR: Ai Senhor! Eu não sou homem de palavras de ontem nem de anteontem, nem ainda desde que tu falas a teu servo; porque sou lento no fala e incômodo de língua."}, {"numero": 11, "texto": "E o SENHOR lhe respondeu: Quem deu a boca ao homem? Ou quem fez ao mudo e ao surdo, ao que vai e ao cego? não sou eu, o SENHOR?"}, {"numero": 12, "texto": "Agora pois, vai, que eu serei em tua boca, e te ensinarei o que tenhas de falar."}, {"numero": 13, "texto": "E ele disse: Ai Senhor! envia por meio do que hás de enviar."}, {"numero": 14, "texto": "Então o SENHOR se irou contra Moisés, e disse: Não conheço eu a teu irmão Arão, levita, e que ele fala bem? E ainda eis que ele sairá para te receber, e vendo-te, se alegrará em seu coração."}, {"numero": 15, "texto": "Tu falarás a ele, e porás em sua boca as palavras, e eu serei em tua boca e na sua, e vos ensinarei o que deveis fazer."}, {"numero": 16, "texto": "E ele falará por ti ao povo; e ele te será a ti em lugar de boca, e tu serás para ele em lugar de Deus."}, {"numero": 17, "texto": "E tomarás esta vara em tua mão, com a qual farás os sinais."}, {"numero": 18, "texto": "Assim se foi Moisés, e voltando a seu sogro Jetro, disse-lhe: Irei agora, e voltarei a meus irmãos que estão em Egito, para ver se ainda vivem. E Jetro disse a Moisés: Vai em paz."}, {"numero": 19, "texto": "Disse também o SENHOR a Moisés em Midiã: Vai, e volta-te ao Egito, porque mataram todos os que procuravam tua morte."}, {"numero": 20, "texto": "Então Moisés tomou sua mulher e seus filhos, e os pôs sobre um asno, e voltou-se à terra do Egito: tomou também Moisés a vara de Deus em sua mão."}, {"numero": 21, "texto": "E disse o SENHOR a Moisés: Quando houverdes voltado ao Egito, olha que faças diante de Faraó todas as maravilhas que pus em tua mão: eu, porém, endurecerei seu coração, de modo que não deixará ir ao povo."}, {"numero": 22, "texto": "E dirás a Faraó: O SENHOR disse assim: Israel é meu filho, meu primogênito."}, {"numero": 23, "texto": "Já te disse que deixes ir a meu filho, para que me sirva, mas não quiseste deixá-lo ir: eis que eu vou a matar a teu filho, o teu primogênito."}, {"numero": 24, "texto": "E aconteceu no caminho, que em uma parada o SENHOR lhe saiu ao encontro, e quis matá-lo."}, {"numero": 25, "texto": "Então Zípora agarrou uma pedra afiada, e cortou o prepúcio de seu filho, e lançou-o a seus pés, dizendo: Em verdade tu me és um esposo de sangue."}, {"numero": 26, "texto": "Assim lhe deixou logo ir. E ela disse: Esposo de sangue, por causa da circuncisão."}, {"numero": 27, "texto": "E o SENHOR disse a Arão: Vai receber a Moisés ao deserto. E ele foi, e encontrou-o no monte de Deus, e beijou-lhe."}, {"numero": 28, "texto": "Então contou Moisés a Arão todas as palavras do SENHOR que lhe enviava, e todas o sinais que lhe havia dado."}, {"numero": 29, "texto": "E foram Moisés e Arão, e juntaram todos os anciãos dos filhos de Israel:"}, {"numero": 30, "texto": "E falou Arão todas as palavras que o SENHOR havia dito a Moisés, e fez o sinais diante dos olhos do povo."}, {"numero": 31, "texto": "E o povo creu; e ouvindo que o SENHOR havia visitado os filhos de Israel, e que havia visto sua aflição, inclinaram-se e adoraram."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 4, 'en', '[{"numero": 1, "texto": "And Moses answered and said, But, behold, they will not believe me, nor hearken unto my voice: for they will say, The Lord hath not appeared unto thee."}, {"numero": 2, "texto": "And the Lord said unto him, What is that in thine hand? And he said, A rod."}, {"numero": 3, "texto": "And he said, Cast it on the ground. And he cast it on the ground, and it became a serpent; and Moses fled from before it."}, {"numero": 4, "texto": "And the Lord said unto Moses, Put forth thine hand, and take it by the tail. And he put forth his hand, and caught it, and it became a rod in his hand:"}, {"numero": 5, "texto": "That they may believe that the Lord God of their fathers, the God of Abraham, the God of Isaac, and the God of Jacob, hath appeared unto thee."}, {"numero": 6, "texto": "And the Lord said furthermore unto him, Put now thine hand into thy bosom. And he put his hand into his bosom: and when he took it out, behold, his hand was leprous as snow."}, {"numero": 7, "texto": "And he said, Put thine hand into thy bosom again. And he put his hand into his bosom again; and plucked it out of his bosom, and, behold, it was turned again as his other flesh."}, {"numero": 8, "texto": "And it shall come to pass, if they will not believe thee, neither hearken to the voice of the first sign, that they will believe the voice of the latter sign."}, {"numero": 9, "texto": "And it shall come to pass, if they will not believe also these two signs, neither hearken unto thy voice, that thou shalt take of the water of the river, and pour it upon the dry land: and the water which thou takest out of the river shall become blood upon the dry land."}, {"numero": 10, "texto": "And Moses said unto the Lord, O my Lord, I am not eloquent, neither heretofore, nor since thou hast spoken unto thy servant: but I am slow of speech, and of a slow tongue."}, {"numero": 11, "texto": "And the Lord said unto him, Who hath made man''s mouth? or who maketh the dumb, or deaf, or the seeing, or the blind? have not I the Lord?"}, {"numero": 12, "texto": "Now therefore go, and I will be with thy mouth, and teach thee what thou shalt say."}, {"numero": 13, "texto": "And he said, O my Lord, send, I pray thee, by the hand of him whom thou wilt send."}, {"numero": 14, "texto": "And the anger of the Lord was kindled against Moses, and he said, Is not Aaron the Levite thy brother? I know that he can speak well. And also, behold, he cometh forth to meet thee: and when he seeth thee, he will be glad in his heart."}, {"numero": 15, "texto": "And thou shalt speak unto him, and put words in his mouth: and I will be with thy mouth, and with his mouth, and will teach you what ye shall do."}, {"numero": 16, "texto": "And he shall be thy spokesman unto the people: and he shall be, even he shall be to thee instead of a mouth, and thou shalt be to him instead of God."}, {"numero": 17, "texto": "And thou shalt take this rod in thine hand, wherewith thou shalt do signs."}, {"numero": 18, "texto": "And Moses went and returned to Jethro his father in law, and said unto him, Let me go, I pray thee, and return unto my brethren which are in Egypt, and see whether they be yet alive. And Jethro said to Moses, Go in peace."}, {"numero": 19, "texto": "And the Lord said unto Moses in Midian, Go, return into Egypt: for all the men are dead which sought thy life."}, {"numero": 20, "texto": "And Moses took his wife and his sons, and set them upon an ass, and he returned to the land of Egypt: and Moses took the rod of God in his hand."}, {"numero": 21, "texto": "And the Lord said unto Moses, When thou goest to return into Egypt, see that thou do all those wonders before Pharaoh, which I have put in thine hand: but I will harden his heart, that he shall not let the people go."}, {"numero": 22, "texto": "And thou shalt say unto Pharaoh, Thus saith the Lord, Israel is my son, even my firstborn:"}, {"numero": 23, "texto": "And I say unto thee, Let my son go, that he may serve me: and if thou refuse to let him go, behold, I will slay thy son, even thy firstborn."}, {"numero": 24, "texto": "And it came to pass by the way in the inn, that the Lord met him, and sought to kill him."}, {"numero": 25, "texto": "Then Zipporah took a sharp stone, and cut off the foreskin of her son, and cast it at his feet, and said, Surely a bloody husband art thou to me."}, {"numero": 26, "texto": "So he let him go: then she said, A bloody husband thou art, because of the circumcision."}, {"numero": 27, "texto": "And the Lord said to Aaron, Go into the wilderness to meet Moses. And he went, and met him in the mount of God, and kissed him."}, {"numero": 28, "texto": "And Moses told Aaron all the words of the Lord who had sent him, and all the signs which he had commanded him."}, {"numero": 29, "texto": "And Moses and Aaron went and gathered together all the elders of the children of Israel:"}, {"numero": 30, "texto": "And Aaron spake all the words which the Lord had spoken unto Moses, and did the signs in the sight of the people."}, {"numero": 31, "texto": "And the people believed: and when they heard that the Lord had visited the children of Israel, and that he had looked upon their affliction, then they bowed their heads and worshipped."}]'::jsonb, 'King James Version'),
  ('Ex', 4, 'fr', '[{"numero": 1, "texto": "Moïse répondit, et dit: Voici, ils ne me croiront point, et ils n''''écouteront point ma voix. Mais ils diront: L''''Eternel ne t''''est point apparu."}, {"numero": 2, "texto": "L''''Eternel lui dit: Qu''''y a-t-il dans ta main? Il répondit: Une verge."}, {"numero": 3, "texto": "L''''Eternel dit: Jette-la par terre. Il la jeta par terre, et elle devint un serpent. Moïse fuyait devant lui."}, {"numero": 4, "texto": "L''''Eternel dit à Moïse: Etends ta main, et saisis-le par la queue. Il étendit la main et le saisit et le serpent redevint une verge dans sa main."}, {"numero": 5, "texto": "C''''est là, dit l''''Eternel, ce que tu feras, afin qu''''ils croient que l''''Eternel, le Dieu de leurs pères, t''''est apparu, le Dieu d''''Abraham, le Dieu d''''Isaac et le Dieu de Jacob."}, {"numero": 6, "texto": "L''''Eternel lui dit encore: Mets ta main dans ton sein. Il mit sa main dans son sein; puis il la retira, et voici, sa main était couverte de lèpre, blanche comme la neige."}, {"numero": 7, "texto": "L''''Eternel dit: Remets ta main dans ton sein. Il remit sa main dans son sein; puis il la retira de son sein, et voici, elle était redevenue comme sa chair."}, {"numero": 8, "texto": "S''''ils ne te croient pas, dit l''''Eternel, et n''''écoutent pas la voix du premier signe, ils croiront à la voix du dernier signe."}, {"numero": 9, "texto": "S''''ils ne croient pas même à ces deux signes, et n''''écoutent pas ta voix, tu prendras de l''''eau du fleuve, tu la répandras sur la terre, et l''''eau que tu auras prise du fleuve deviendra du sang sur la terre."}, {"numero": 10, "texto": "Moïse dit à l''''Eternel: Ah! Seigneur, je ne suis pas un homme qui ait la parole facile, et ce n''''est ni d''''hier ni d''''avant-hier, ni même depuis que tu parles à ton serviteur; car j''''ai la bouche et la langue embarrassées."}, {"numero": 11, "texto": "L''''Eternel lui dit: Qui a fait la bouche de l''''homme? et qui rend muet ou sourd, voyant ou aveugle? N''''est-ce pas moi, l''''Eternel?"}, {"numero": 12, "texto": "Va donc, je serai avec ta bouche, et je t''''enseignerai ce que tu auras à dire."}, {"numero": 13, "texto": "Moïse dit: Ah! Seigneur, envoie qui tu voudras envoyer."}, {"numero": 14, "texto": "Alors la colère de l''''Eternel s''''enflamma contre Moïse, et il dit: N''''y a t-il pas ton frère Aaron, le Lévite? Je sais qu''''il parlera facilement. Le voici lui-même, qui vient au-devant de toi; et, quand il te verra, il se réjouira dans son coeur."}, {"numero": 15, "texto": "Tu lui parleras, et tu mettras les paroles dans sa bouche; et moi, je serai avec ta bouche et avec sa bouche, et je vous enseignerai ce que vous aurez à faire."}, {"numero": 16, "texto": "Il parlera pour toi au peuple; il te servira de bouche, et tu tiendras pour lui la place de Dieu."}, {"numero": 17, "texto": "Prends dans ta main cette verge, avec laquelle tu feras les signes."}, {"numero": 18, "texto": "Moïse s''''en alla; et de retour auprès de Jéthro, son beau-père, il lui dit: Laisse-moi, je te prie, aller rejoindre mes frères qui sont en Egypte, afin que je voie s''''ils sont encore vivants. Jéthro dit à Moïse: Va en paix."}, {"numero": 19, "texto": "L''''Eternel dit à Moïse, en Madian: Va, retourne en Egypte, car tous ceux qui en voulaient à ta vie sont morts."}, {"numero": 20, "texto": "Moïse prit sa femme et ses fils, les fit monter sur des ânes, et retourna dans le pays d''''Egypte. Il prit dans sa main la verge de Dieu."}, {"numero": 21, "texto": "L''''Eternel dit à Moïse: En partant pour retourner en Egypte, vois tous les prodiges que je mets en ta main: tu les feras devant Pharaon. Et moi, j''''endurcirai son coeur, et il ne laissera point aller le peuple."}, {"numero": 22, "texto": "Tu diras à Pharaon: Ainsi parle l''''Eternel: Israël est mon fils, mon premier-né."}, {"numero": 23, "texto": "Je te dis: Laisse aller mon fils, pour qu''''il me serve; si tu refuses de le laisser aller, voici, je ferai périr ton fils, ton premier-né."}, {"numero": 24, "texto": "Pendant le voyage, en un lieu où Moïse passa la nuit, l''''Eternel l''''attaqua et voulut le faire mourir."}, {"numero": 25, "texto": "Séphora prit une pierre aiguë, coupa le prépuce de son fils, et le jeta aux pieds de Moïse, en disant: Tu es pour moi un époux de sang!"}, {"numero": 26, "texto": "Et l''''Eternel le laissa. C''''est alors qu''''elle dit: Epoux de sang! à cause de la circoncision."}, {"numero": 27, "texto": "L''''Eternel dit à Aaron: Va dans le désert au-devant de Moïse. Aaron partit; il rencontra Moïse à la montagne de Dieu, et il le baisa."}, {"numero": 28, "texto": "Moïse fit connaître à Aaron toutes les paroles de l''''Eternel qui l''''avait envoyé, et tous les signes qu''''il lui avait ordonné de faire."}, {"numero": 29, "texto": "Moïse et Aaron poursuivirent leur chemin, et ils assemblèrent tous les anciens des enfants d''''Israël."}, {"numero": 30, "texto": "Aaron rapporta toutes les paroles que l''''Eternel avait dites à Moïse, et il exécuta les signes aux yeux du peuple."}, {"numero": 31, "texto": "Et le peuple crut. Ils apprirent que l''''Eternel avait visité les enfants d''''Israël, qu''''il avait vu leur souffrance; et ils s''''inclinèrent et se prosternèrent."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 4, 'es', '[{"numero": 1, "texto": "ENTONCES Moisés respondió, y dijo: He aquí que ellos no me creerán, ni oirán mi voz; porque dirán: No te ha aparecido Jehová."}, {"numero": 2, "texto": "Y Jehová dijo: ¿Qué es eso que tienes en tu mano? Y él respondió: Una vara."}, {"numero": 3, "texto": "Y él le dijo: Échala en tierra. Y él la echó en tierra, y tornóse una culebra: y Moisés huía de ella."}, {"numero": 4, "texto": "Entonces dijo Jehová á Moisés: Extiende tu mano, y tómala por la cola. Y él extendió su mano, y tomóla, y tornóse vara en su mano."}, {"numero": 5, "texto": "Por esto creerán que se te ha aparecido Jehová, el Dios de tus padres, el Dios de Abraham, Dios de Isaac y Dios de Jacob."}, {"numero": 6, "texto": "Y díjole más Jehová: Mete ahora tu mano en tu seno. Y él metió la mano en su seno; y como la sacó, he aquí que su mano estaba leprosa como la nieve."}, {"numero": 7, "texto": "Y dijo: Vuelve á meter tu mano en tu seno: y él volvió á meter su mano en su seno; y volviéndola á sacar del seno, he aquí que se había vuelto como la otra carne."}, {"numero": 8, "texto": "Sí aconteciere, que no te creyeren, ni obedecieren á la voz de la primera señal, creerán á la voz de la postrera."}, {"numero": 9, "texto": "Y si aun no creyeren á estas dos señales, ni oyeren tu voz, tomarás de las aguas del río, y derrámalas en tierra; y volverse han aquellas aguas que tomarás del río, se volverán sangre en la tierra."}, {"numero": 10, "texto": "Entonces dijo Moisés á Jehová: ¡Ay Señor! yo no soy hombre de palabras de ayer ni de anteayer, ni aun desde que tú hablas á tu siervo; porque soy tardo en el habla y torpe de lengua."}, {"numero": 11, "texto": "Y Jehová le respondió: ¿Quién dió la boca al hombre? ¿ó quién hizo al mudo y al sordo, al que ve y al ciego? ¿no soy yo Jehová?"}, {"numero": 12, "texto": "Ahora pues, ve, que yo seré en tu boca, y te enseñaré lo que hayas de hablar."}, {"numero": 13, "texto": "Y él dijo: ¡Ay Señor! envía por mano del que has de enviar."}, {"numero": 14, "texto": "Entonces Jehová se enojó contra Moisés, y dijo: ¿No conozco yo á tu hermano Aarón, Levita, y que él hablará? Y aun he aquí que él te saldrá á recibir, y en viéndote, se alegrará en su corazón."}, {"numero": 15, "texto": "Tú hablarás á él, y pondrás en su boca las palabras, y yo seré en tu boca y en la suya, y os enseñaré lo que hayáis de hacer."}, {"numero": 16, "texto": "Y él hablará por ti al pueblo; y él te será á ti en lugar de boca, y tú serás para él en lugar de Dios."}, {"numero": 17, "texto": "Y tomarás esta vara en tu mano, con la cual harás las señales."}, {"numero": 18, "texto": "Así se fué Moisés, y volviendo á su suegro Jethro, díjole: Iré ahora, y volveré á mis hermanos que están en Egipto, para ver si aun viven. Y Jethro dijo á Moisés: Ve en paz."}, {"numero": 19, "texto": "Dijo también Jehová á Moisés en Madián: Ve, y vuélvete á Egipto, porque han muerto todos los que procuraban tu muerte."}, {"numero": 20, "texto": "Entonces Moisés tomó su mujer y sus hijos, y púsolos sobre un asno, y volvióse á tierra de Egipto: tomó también Moisés la vara de Dios en su mano."}, {"numero": 21, "texto": "Y dijo Jehová á Moisés: Cuando hubiereis vuelto á Egipto, mira que hagas delante de Faraón todas las maravillas que he puesto en tu mano: yo empero endureceré su corazón, de modo que no dejará ir al pueblo."}, {"numero": 22, "texto": "Y dirás á Faraón: Jehová ha dicho así: Israel es mi hijo, mi primogénito."}, {"numero": 23, "texto": "Ya te he dicho que dejes ir á mi hijo, para que me sirva, mas no has querido dejarlo ir: he aquí yo voy á matar á tu hijo, tu primogénito."}, {"numero": 24, "texto": "Y aconteció en el camino, que en una posada le salió al encuentro Jehová, y quiso matarlo."}, {"numero": 25, "texto": "Entonces Séphora cogió un afilado pedernal, y cortó el prepucio de su hijo, y echólo á sus pies, diciendo: A la verdad tú me eres un esposo de sangre."}, {"numero": 26, "texto": "Así le dejó luego ir. Y ella dijo: Esposo de sangre, á causa de la circuncisión."}, {"numero": 27, "texto": "Y Jehová dijo á Aarón: Ve á recibir á Moisés al desierto. Y él fué, y encontrólo en el monte de Dios, y besóle."}, {"numero": 28, "texto": "Entonces contó Moisés á Aarón todas las palabras de Jehová que le enviaba, y todas las señales que le había dado."}, {"numero": 29, "texto": "Y fueron Moisés y Aarón, y juntaron todos los ancianos de los hijos de Israel:"}, {"numero": 30, "texto": "Y habló Aarón todas las palabras que Jehová había dicho á Moisés, é hizo las señales delante de los ojos del pueblo."}, {"numero": 31, "texto": "Y el pueblo creyó: y oyendo que Jehová había visitado los hijos de Israel, y que había visto su aflicción, inclináronse y adoraron."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 5, 'pt', '[{"numero": 1, "texto": "Depois entraram Moisés e Arão a Faraó, e lhe disseram: O SENHOR, o Deus de Israel, disse assim: Deixa ir meu povo a celebrar-me festa no deserto."}, {"numero": 2, "texto": "E Faraó respondeu: Quem é o SENHOR, para que eu ouça sua voz e deixe ir a Israel? Não conheço o SENHOR, nem tampouco deixarei Israel ir."}, {"numero": 3, "texto": "E eles disseram: O Deus dos hebreus nos encontrou: iremos, pois, agora caminho de três dias pelo deserto, e sacrificaremos ao SENHOR nosso Deus; para que não venha sobre nós com pestilência ou com espada."}, {"numero": 4, "texto": "Então o rei do Egito lhes disse: Moisés e Arão, por que fazeis cessar ao povo de sua obra? Ide a vossas cargas."}, {"numero": 5, "texto": "Disse também Faraó: Eis que o povo da terra é agora muito, e vós lhes fazeis cessar de suas cargas."}, {"numero": 6, "texto": "E mandou Faraó aquele mesmo dia aos capatazes do povo que o tinham à sua responsabilidade, e a seus governadores, dizendo:"}, {"numero": 7, "texto": "De aqui adiante não dareis palha ao povo para fazer tijolos, como ontem e antes de ontem; vão eles e recolham por si mesmos a palha;"}, {"numero": 8, "texto": "E haveis de pôr-lhes a tarefa dos tijolos que faziam antes, e não lhes diminuireis nada; porque estão ociosos, e por isso levantam a voz dizendo: Vamos e sacrificaremos a nosso Deus."}, {"numero": 9, "texto": "Agrave-se a servidão sobre eles, para que se ocupem nela, e não atendam a palavras de mentira."}, {"numero": 10, "texto": "E saindo os capatazes do povo e seus governadores, falaram ao povo, dizendo: Assim disse Faraó: Eu não vos dou palha."}, {"numero": 11, "texto": "Ide vós, e recolhei palha de onde a achardes; que nada se diminuirá de vossa tarefa."}, {"numero": 12, "texto": "Então o povo se espalhou por toda a terra do Egito a colher restolho em lugar de palha."}, {"numero": 13, "texto": "E os capatazes os apressavam, dizendo: Acabai vossa obra, a tarefa do dia em seu dia, como quando se vos dava palha."}, {"numero": 14, "texto": "E açoitavam aos supervisores dos filhos de Israel, que os capatazes de Faraó haviam posto sobre eles, dizendo: Por que não cumpristes vossa tarefa de tijolos nem ontem nem hoje, como antes?"}, {"numero": 15, "texto": "E os supervisores dos filhos de Israel vieram a Faraó, e se queixaram a ele, dizendo: Por que o fazes assim com teus servos?"}, {"numero": 16, "texto": "Não se dá palha a teus servos, e, contudo, nos dizem: Fazei os tijolos. E eis que teus servos são açoitados, e teu povo cai em falta."}, {"numero": 17, "texto": "E ele respondeu: Estais ociosos, sim, ociosos, e por isso dizeis: Vamos e sacrifiquemos ao SENHOR."}, {"numero": 18, "texto": "Ide, pois, agora, e trabalhai. Não se vos dará palha, e haveis de dar a tarefa dos tijolos."}, {"numero": 19, "texto": "Então os supervisores dos filhos de Israel se viram em aflição, tendo lhes dito: Não se diminuirá nada de vossos tijolos, da tarefa de cada dia."}, {"numero": 20, "texto": "E encontrando a Moisés e a Arão, que estavam à vista deles quando saíam de Faraó,"}, {"numero": 21, "texto": "Disseram-lhes: Olhe o SENHOR sobre vós, e julgue; pois nos fizestes repulsivos diante de Faraó e de seus servos, dando-lhes a espada nas mãos para que nos matem."}, {"numero": 22, "texto": "Então Moisés se voltou ao SENHOR, e disse: Senhor, por que afliges a este povo? para que me enviaste?"}, {"numero": 23, "texto": "Porque desde que vim a Faraó para falar-lhe em teu nome, afligiu a este povo; e tu tampouco livraste a teu povo."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 5, 'en', '[{"numero": 1, "texto": "And afterward Moses and Aaron went in, and told Pharaoh, Thus saith the Lord God of Israel, Let my people go, that they may hold a feast unto me in the wilderness."}, {"numero": 2, "texto": "And Pharaoh said, Who is the Lord, that I should obey his voice to let Israel go? I know not the Lord, neither will I let Israel go."}, {"numero": 3, "texto": "And they said, The God of the Hebrews hath met with us: let us go, we pray thee, three days'' journey into the desert, and sacrifice unto the Lord our God; lest he fall upon us with pestilence, or with the sword."}, {"numero": 4, "texto": "And the king of Egypt said unto them, Wherefore do ye, Moses and Aaron, let the people from their works? get you unto your burdens."}, {"numero": 5, "texto": "And Pharaoh said, Behold, the people of the land now are many, and ye make them rest from their burdens."}, {"numero": 6, "texto": "And Pharaoh commanded the same day the taskmasters of the people, and their officers, saying,"}, {"numero": 7, "texto": "Ye shall no more give the people straw to make brick, as heretofore: let them go and gather straw for themselves."}, {"numero": 8, "texto": "And the tale of the bricks, which they did make heretofore, ye shall lay upon them; ye shall not diminish ought thereof: for they be idle; therefore they cry, saying, Let us go and sacrifice to our God."}, {"numero": 9, "texto": "Let there more work be laid upon the men, that they may labour therein; and let them not regard vain words."}, {"numero": 10, "texto": "And the taskmasters of the people went out, and their officers, and they spake to the people, saying, Thus saith Pharaoh, I will not give you straw."}, {"numero": 11, "texto": "Go ye, get you straw where ye can find it: yet not ought of your work shall be diminished."}, {"numero": 12, "texto": "So the people were scattered abroad throughout all the land of Egypt to gather stubble instead of straw."}, {"numero": 13, "texto": "And the taskmasters hasted them, saying, Fulfil your works, your daily tasks, as when there was straw."}, {"numero": 14, "texto": "And the officers of the children of Israel, which Pharaoh''s taskmasters had set over them, were beaten, and demanded, Wherefore have ye not fulfilled your task in making brick both yesterday and to day, as heretofore?"}, {"numero": 15, "texto": "Then the officers of the children of Israel came and cried unto Pharaoh, saying, Wherefore dealest thou thus with thy servants?"}, {"numero": 16, "texto": "There is no straw given unto thy servants, and they say to us, Make brick: and, behold, thy servants are beaten; but the fault is in thine own people."}, {"numero": 17, "texto": "But he said, Ye are idle, ye are idle: therefore ye say, Let us go and do sacrifice to the Lord."}, {"numero": 18, "texto": "Go therefore now, and work; for there shall no straw be given you, yet shall ye deliver the tale of bricks."}, {"numero": 19, "texto": "And the officers of the children of Israel did see that they were in evil case, after it was said, Ye shall not minish ought from your bricks of your daily task."}, {"numero": 20, "texto": "And they met Moses and Aaron, who stood in the way, as they came forth from Pharaoh:"}, {"numero": 21, "texto": "And they said unto them, The Lord look upon you, and judge; because ye have made our savour to be abhorred in the eyes of Pharaoh, and in the eyes of his servants, to put a sword in their hand to slay us."}, {"numero": 22, "texto": "And Moses returned unto the Lord, and said, Lord, wherefore hast thou so evil entreated this people? why is it that thou hast sent me?"}, {"numero": 23, "texto": "For since I came to Pharaoh to speak in thy name, he hath done evil to this people; neither hast thou delivered thy people at all."}]'::jsonb, 'King James Version'),
  ('Ex', 5, 'fr', '[{"numero": 1, "texto": "Moïse et Aaron se rendirent ensuite auprès de Pharaon, et lui dirent: Ainsi parle l''''Eternel, le Dieu d''''Israël: Laisse aller mon peuple, pour qu''''il célèbre au désert une fête en mon honneur."}, {"numero": 2, "texto": "Pharaon répondit: Qui est l''''Eternel, pour que j''''obéisse à sa voix, en laissant aller Israël? Je ne connais point l''''Eternel, et je ne laisserai point aller Israël."}, {"numero": 3, "texto": "Ils dirent: Le Dieu des Hébreux nous est apparu. Permets-nous de faire trois journées de marche dans le désert, pour offrir des sacrifices à l''''Eternel, afin qu''''il ne nous frappe pas de la peste ou de l''''épée."}, {"numero": 4, "texto": "Et le roi d''''Egypte leur dit: Moïse et Aaron, pourquoi détournez-vous le peuple de son ouvrage? Allez à vos travaux."}, {"numero": 5, "texto": "Pharaon dit: Voici, ce peuple est maintenant nombreux dans le pays, et vous lui feriez interrompre ses travaux!"}, {"numero": 6, "texto": "Et ce jour même, Pharaon donna cet ordre aux inspecteurs du peuple et aux commissaires:"}, {"numero": 7, "texto": "Vous ne donnerez plus comme auparavant de la paille au peuple pour faire des briques; qu''''ils aillent eux-mêmes se ramasser de la paille."}, {"numero": 8, "texto": "Vous leur imposerez néanmoins la quantité de briques qu''''ils faisaient auparavant, vous n''''en retrancherez rien; car ce sont des paresseux; voilà pourquoi ils crient, en disant: Allons offrir des sacrifices à notre Dieu!"}, {"numero": 9, "texto": "Que l''''on charge de travail ces gens, qu''''ils s''''en occupent, et ils ne prendront plus garde à des paroles de mensonge."}, {"numero": 10, "texto": "Les inspecteurs du peuple et les commissaires vinrent dire au peuple: Ainsi parle Pharaon: Je ne vous donne plus de paille;"}, {"numero": 11, "texto": "allez vous-mêmes vous procurer de la paille où vous en trouverez, car l''''on ne retranche rien de votre travail."}, {"numero": 12, "texto": "Le peuple se répandit dans tout le pays d''''Egypte, pour ramasser du chaume au lieu de paille."}, {"numero": 13, "texto": "Les inspecteurs les pressaient, en disant: Achevez votre tâche, jour par jour, comme quand il y avait de la paille."}, {"numero": 14, "texto": "On battit même les commissaires des enfants d''''Israël, établis sur eux par les inspecteurs de Pharaon: Pourquoi, disait-on, n''''avez-vous pas achevé hier et aujourd''''hui, comme auparavant, la quantité de briques qui vous avait été fixée?"}, {"numero": 15, "texto": "Les commissaires des enfants d''''Israël allèrent se plaindre à Pharaon, et lui dirent: Pourquoi traites-tu ainsi tes serviteurs?"}, {"numero": 16, "texto": "On ne donne point de paille à tes serviteurs, et l''''on nous dit: Faites des briques! Et voici, tes serviteurs sont battus, comme si ton peuple était coupable."}, {"numero": 17, "texto": "Pharaon répondit: Vous êtes des paresseux, des paresseux! Voilà pourquoi vous dites: Allons offrir des sacrifices à l''''Eternel!"}, {"numero": 18, "texto": "Maintenant, allez travailler; on ne vous donnera point de paille, et vous livrerez la même quantité de briques."}, {"numero": 19, "texto": "Les commissaires des enfants d''''Israël virent qu''''on les rendait malheureux, en disant: Vous ne retrancherez rien de vos briques; chaque jour la tâche du jour."}, {"numero": 20, "texto": "En sortant de chez Pharaon, ils rencontrèrent Moïse et Aaron qui les attendaient."}, {"numero": 21, "texto": "Ils leur dirent: Que l''''Eternel vous regarde, et qu''''il juge! Vous nous avez rendus odieux à Pharaon et à ses serviteurs, vous avez mis une épée dans leurs mains pour nous faire périr."}, {"numero": 22, "texto": "Moïse retourna vers l''''Eternel, et dit: Seigneur, pourquoi as-tu fait du mal à ce peuple? pourquoi m''''as-tu envoyé?"}, {"numero": 23, "texto": "Depuis que je suis allé vers Pharaon pour parler en ton nom, il fait du mal à ce peuple, et tu n''''as point délivré ton peuple."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 5, 'es', '[{"numero": 1, "texto": "DESPUÉS entraron Moisés y Aarón á Faraón, y le dijeron: Jehová, el Dios de Israel, dice así: Deja ir á mi pueblo á celebrarme fiesta en el desierto."}, {"numero": 2, "texto": "Y Faraón respondió: ¿Quién es Jehová, para que yo oiga su voz y deje ir á Israel? Yo no conozco á Jehová, ni tampoco dejaré ir á Israel."}, {"numero": 3, "texto": "Y ellos dijeron: El Dios de los Hebreos nos ha encontrado: iremos, pues, ahora camino de tres días por el desierto, y sacrificaremos á Jehová nuestro Dios; porque no venga sobre nosotros con pestilencia ó con espada."}, {"numero": 4, "texto": "Entonces el rey de Egipto les dijo: Moisés y Aarón, ¿por qué hacéis cesar al pueblo de su obra? idos á vuestros cargos."}, {"numero": 5, "texto": "Dijo también Faraón: He aquí el pueblo de la tierra es ahora mucho, y vosotros les hacéis cesar de sus cargos."}, {"numero": 6, "texto": "Y mandó Faraón aquel mismo día á los cuadrilleros del pueblo que le tenían á su cargo, y á sus gobernadores, diciendo:"}, {"numero": 7, "texto": "De aquí adelante no daréis paja al pueblo para hacer ladrillo, como ayer y antes de ayer; vayan ellos y recojan por sí mismos la paja:"}, {"numero": 8, "texto": "Y habéis de ponerles la tarea del ladrillo que hacían antes, y no les disminuiréis nada; porque están ociosos, y por eso levantan la voz diciendo: Vamos y sacrificaremos á nuestro Dios."}, {"numero": 9, "texto": "Agrávese la servidumbre sobre ellos, para que se ocupen en ella, y no atiendan á palabras de mentira."}, {"numero": 10, "texto": "Y saliendo los cuadrilleros del pueblo y sus gobernadores, hablaron al pueblo, diciendo: Así ha dicho Faraón: Yo no os doy paja."}, {"numero": 11, "texto": "Id vosotros, y recoged paja donde la hallareis; que nada se disminuirá de vuestra tarea."}, {"numero": 12, "texto": "Entonces el pueblo se derramó por toda la tierra de Egipto á coger rastrojo en lugar de paja."}, {"numero": 13, "texto": "Y los cuadrilleros los apremiaban, diciendo: Acabad vuestra obra, la tarea del día en su día, como cuando se os daba paja."}, {"numero": 14, "texto": "Y azotaban á los capataces de los hijos de Israel, que los cuadrilleros de Faraón habían puesto sobre ellos, diciendo: ¿Por qué no habéis cumplido vuestra tarea de ladrillo ni ayer ni hoy, como antes?"}, {"numero": 15, "texto": "Y los capataces de los hijos de Israel vinieron á Faraón, y se quejaron á él, diciendo: ¿Por qué lo haces así con tus siervos?"}, {"numero": 16, "texto": "No se da paja á tus siervos, y con todo nos dicen: Haced el ladrillo. Y he aquí tus siervos son azotados, y tu pueblo cae en falta."}, {"numero": 17, "texto": "Y él respondió: Estáis ociosos, sí, ociosos, y por eso decís: Vamos y sacrifiquemos á Jehová."}, {"numero": 18, "texto": "Id pues ahora, y trabajad. No se os dará paja, y habéis de dar la tarea del ladrillo."}, {"numero": 19, "texto": "Entonces los capataces de los hijos de Israel se vieron en aflicción, habiéndoseles dicho: No se disminuirá nada de vuestro ladrillo, de la tarea de cada día."}, {"numero": 20, "texto": "Y encontrando á Moisés y á Aarón, que estaban á la vista de ellos cuando salían de Faraón,"}, {"numero": 21, "texto": "Dijéronles: Mire Jehová sobre vosotros, y juzgue; pues habéis hecho heder nuestro olor delante de Faraón y de sus siervos, dándoles el cuchillo en las manos para que nos maten."}, {"numero": 22, "texto": "Entonces Moisés se volvió á Jehová, y dijo: Señor, ¿por qué afliges á este pueblo? ¿para qué me enviaste?"}, {"numero": 23, "texto": "Porque desde que yo vine á Faraón para hablarle en tu nombre, ha afligido á este pueblo; y tú tampoco has librado á tu pueblo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 7, 'pt', '[{"numero": 1, "texto": "O SENHOR disse a Moisés: Olha, eu te constituí como um deus para Faraó, e teu irmão Arão será teu profeta."}, {"numero": 2, "texto": "Tu dirás todas as coisas que eu te mandarei, e Arão teu irmão falará a Faraó, para que deixe os filhos de Israel saírem de sua terra."}, {"numero": 3, "texto": "E eu endurecerei o coração de Faraó, e multiplicarei na terra do Egito meus sinais e minhas maravilhas."}, {"numero": 4, "texto": "E Faraó não vos ouvirá; mas eu porei minha mão sobre o Egito, e tirarei meus exércitos, meu povo, os filhos de Israel, da terra do Egito, com grandes juízos."}, {"numero": 5, "texto": "E os egípcios saberão que eu sou o SENHOR, quando eu estender minha mão sobre o Egito, e tirar os filhos de Israel do meio deles."}, {"numero": 6, "texto": "E fez Moisés e Arão como o SENHOR lhes mandou; fizeram-no assim."}, {"numero": 7, "texto": "E era Moisés de idade de oitenta anos, e Arão de idade de oitenta e três, quando falaram a Faraó."}, {"numero": 8, "texto": "E falou o SENHOR a Moisés e a Arão, dizendo:"}, {"numero": 9, "texto": "Se Faraó vos responder dizendo, Mostrai milagre; dirás a Arão: Toma tua vara, e lança-a diante de Faraó, para que se torne cobra."}, {"numero": 10, "texto": "Vieram, pois, Moisés e Arão a Faraó, e fizeram como o SENHOR o havia mandado; e Arão lançou sua vara diante de Faraó e de seus servos, e tornou-se cobra."}, {"numero": 11, "texto": "Então Faraó chamou também sábios e encantadores; e os encantadores do Egito com seus encantamentos fizeram também o mesmo;"}, {"numero": 12, "texto": "Pois lançou cada um sua vara, as quais se tornaram cobras; mas a vara de Arão devorou as varas deles."}, {"numero": 13, "texto": "E o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito."}, {"numero": 14, "texto": "Então o SENHOR disse a Moisés: O coração de Faraó está endurecido, que não quer deixar o povo ir."}, {"numero": 15, "texto": "Vai pela manhã a Faraó, eis que ele estará saindo às águas; e põe-te à beira do rio diante dele, e toma em tua mão a vara que se tornou cobra,"}, {"numero": 16, "texto": "E dize-lhe: O SENHOR, o Deus dos hebreus, me enviou a ti, dizendo: Deixa meu povo ir, para que me sirvam no deserto; e eis que até agora não quiseste ouvir."}, {"numero": 17, "texto": "Assim disse o SENHOR: Nisto conhecerás que eu sou o SENHOR: eis que ferirei com a vara que tenho em minha mão a água que está no rio, e se converterá em sangue:"}, {"numero": 18, "texto": "E os peixes que há no rio morrerão, e federá o rio, e os egípcios terão asco de beber a água do rio."}, {"numero": 19, "texto": "E o SENHOR disse a Moisés: Dize a Arão: Toma tua vara, e estende tua mão sobre as águas do Egito, sobre seus rios, sobre seus ribeiros e sobre seus tanques, e sobre todos os seus depósitos de águas, para que se convertam em sangue, e haja sangue por toda a região do Egito, tanto nos vasos de madeira como nos de pedra."}, {"numero": 20, "texto": "E Moisés e Arão fizeram como o SENHOR havia mandado; e levantando a vara feriu as águas que havia no rio, em presença de Faraó e de seus servos; e todas as águas que havia no rio se converteram em sangue."}, {"numero": 21, "texto": "Assim os peixes que havia no rio morreram; e o rio se contaminou, que os egípcios não podiam beber dele; e houve sangue por toda a terra do Egito."}, {"numero": 22, "texto": "E os encantadores do Egito fizeram o mesmo com seus encantamentos: e o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito."}, {"numero": 23, "texto": "E Faraó, tornando, voltou-se a sua casa, e não pôs seu coração ainda nisto."}, {"numero": 24, "texto": "E por todo o Egito fizeram poços ao redor do rio para beber, porque não podiam beber das águas do rio."}, {"numero": 25, "texto": "E cumpriram-se sete dias depois que o SENHOR feriu o rio."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 7, 'en', '[{"numero": 1, "texto": "And the Lord said unto Moses, See, I have made thee a god to Pharaoh: and Aaron thy brother shall be thy prophet."}, {"numero": 2, "texto": "Thou shalt speak all that I command thee: and Aaron thy brother shall speak unto Pharaoh, that he send the children of Israel out of his land."}, {"numero": 3, "texto": "And I will harden Pharaoh''s heart, and multiply my signs and my wonders in the land of Egypt."}, {"numero": 4, "texto": "But Pharaoh shall not hearken unto you, that I may lay my hand upon Egypt, and bring forth mine armies, and my people the children of Israel, out of the land of Egypt by great judgments."}, {"numero": 5, "texto": "And the Egyptians shall know that I am the Lord, when I stretch forth mine hand upon Egypt, and bring out the children of Israel from among them."}, {"numero": 6, "texto": "And Moses and Aaron did as the Lord commanded them, so did they."}, {"numero": 7, "texto": "And Moses was fourscore years old, and Aaron fourscore and three years old, when they spake unto Pharaoh."}, {"numero": 8, "texto": "And the Lord spake unto Moses and unto Aaron, saying,"}, {"numero": 9, "texto": "When Pharaoh shall speak unto you, saying, Shew a miracle for you: then thou shalt say unto Aaron, Take thy rod, and cast it before Pharaoh, and it shall become a serpent."}, {"numero": 10, "texto": "And Moses and Aaron went in unto Pharaoh, and they did so as the Lord had commanded: and Aaron cast down his rod before Pharaoh, and before his servants, and it became a serpent."}, {"numero": 11, "texto": "Then Pharaoh also called the wise men and the sorcerers: now the magicians of Egypt, they also did in like manner with their enchantments."}, {"numero": 12, "texto": "For they cast down every man his rod, and they became serpents: but Aaron''s rod swallowed up their rods."}, {"numero": 13, "texto": "And he hardened Pharaoh''s heart, that he hearkened not unto them; as the Lord had said."}, {"numero": 14, "texto": "And the Lord said unto Moses, Pharaoh''s heart is hardened, he refuseth to let the people go."}, {"numero": 15, "texto": "Get thee unto Pharaoh in the morning; lo, he goeth out unto the water; and thou shalt stand by the river''s brink against he come; and the rod which was turned to a serpent shalt thou take in thine hand."}, {"numero": 16, "texto": "And thou shalt say unto him, The Lord God of the Hebrews hath sent me unto thee, saying, Let my people go, that they may serve me in the wilderness: and, behold, hitherto thou wouldest not hear."}, {"numero": 17, "texto": "Thus saith the Lord, In this thou shalt know that I am the Lord: behold, I will smite with the rod that is in mine hand upon the waters which are in the river, and they shall be turned to blood."}, {"numero": 18, "texto": "And the fish that is in the river shall die, and the river shall stink; and the Egyptians shall lothe to drink of the water of the river."}, {"numero": 19, "texto": "And the Lord spake unto Moses, Say unto Aaron, Take thy rod, and stretch out thine hand upon the waters of Egypt, upon their streams, upon their rivers, and upon their ponds, and upon all their pools of water, that they may become blood; and that there may be blood throughout all the land of Egypt, both in vessels of wood, and in vessels of stone."}, {"numero": 20, "texto": "And Moses and Aaron did so, as the Lord commanded; and he lifted up the rod, and smote the waters that were in the river, in the sight of Pharaoh, and in the sight of his servants; and all the waters that were in the river were turned to blood."}, {"numero": 21, "texto": "And the fish that was in the river died; and the river stank, and the Egyptians could not drink of the water of the river; and there was blood throughout all the land of Egypt."}, {"numero": 22, "texto": "And the magicians of Egypt did so with their enchantments: and Pharaoh''s heart was hardened, neither did he hearken unto them; as the Lord had said."}, {"numero": 23, "texto": "And Pharaoh turned and went into his house, neither did he set his heart to this also."}, {"numero": 24, "texto": "And all the Egyptians digged round about the river for water to drink; for they could not drink of the water of the river."}, {"numero": 25, "texto": "And seven days were fulfilled, after that the Lord had smitten the river."}]'::jsonb, 'King James Version'),
  ('Ex', 7, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse: Vois, je te fais Dieu pour Pharaon: et Aaron, ton frère, sera ton prophète."}, {"numero": 2, "texto": "Toi, tu diras tout ce que je t''''ordonnerai; et Aaron, ton frère, parlera à Pharaon, pour qu''''il laisse aller les enfants d''''Israël hors de son pays."}, {"numero": 3, "texto": "Et moi, j''''endurcirai le coeur de Pharaon, et je multiplierai mes signes et mes miracles dans le pays d''''Egypte."}, {"numero": 4, "texto": "Pharaon ne vous écoutera point. Je mettrai ma main sur l''''Egypte, et je ferai sortir du pays d''''Egypte mes armées, mon peuple, les enfants d''''Israël, par de grands jugements."}, {"numero": 5, "texto": "Les Egyptiens connaîtront que je suis l''''Eternel, lorsque j''''étendrai ma main sur l''''Egypte, et que je ferai sortir du milieu d''''eux les enfants d''''Israël."}, {"numero": 6, "texto": "Moïse et Aaron firent ce que l''''Eternel leur avait ordonné; ils firent ainsi."}, {"numero": 7, "texto": "Moïse était âgé de quatre-vingts ans, et Aaron de quatre-vingt-trois ans, lorsqu''''ils parlèrent à Pharaon."}, {"numero": 8, "texto": "L''''Eternel dit à Moïse et à Aaron:"}, {"numero": 9, "texto": "Si Pharaon vous parle, et vous dit: Faites un miracle! tu diras à Aaron: Prends ta verge, et jette-la devant Pharaon. Elle deviendra un serpent."}, {"numero": 10, "texto": "Moïse et Aaron allèrent auprès de Pharaon, et ils firent ce que l''''Eternel avait ordonné. Aaron jeta sa verge devant Pharaon et devant ses serviteurs; et elle devint un serpent."}, {"numero": 11, "texto": "Mais Pharaon appela des sages et des enchanteurs; et les magiciens d''''Egypte, eux aussi, en firent autant par leurs enchantements."}, {"numero": 12, "texto": "Ils jetèrent tous leurs verges, et elles devinrent des serpents. Et la verge d''''Aaron engloutit leurs verges."}, {"numero": 13, "texto": "Le coeur de Pharaon s''''endurcit, et il n''''écouta point Moïse et Aaron selon ce que l''''Eternel avait dit."}, {"numero": 14, "texto": "L''''Eternel dit à Moïse: Pharaon a le coeur endurci; il refuse de laisser aller le peuple."}, {"numero": 15, "texto": "Va vers Pharaon dès le matin; il sortira pour aller près de l''''eau, et tu te présenteras devant lui au bord du fleuve. Tu prendras à ta main la verge qui a été changée en serpent,"}, {"numero": 16, "texto": "et tu diras à Pharaon: L''''Eternel, le Dieu des Hébreux, m''''a envoyé auprès de toi, pour te dire: Laisse aller mon peuple, afin qu''''il me serve dans le désert. Et voici, jusqu''''à présent tu n''''as point écouté."}, {"numero": 17, "texto": "Ainsi parle l''''Eternel: A ceci tu connaîtras que je suis l''''Eternel. Je vais frapper les eaux du fleuve avec la verge qui est dans ma main; et elles seront changées en sang."}, {"numero": 18, "texto": "Les poissons qui sont dans le fleuve périront, le fleuve se corrompra, et les Egyptiens s''''efforceront en vain de boire l''''eau du fleuve."}, {"numero": 19, "texto": "L''''Eternel dit à Moïse: Dis à Aaron: Prends ta verge, et étends ta main sur les eaux des Egyptiens, sur leurs rivières, sur leurs ruisseaux, sur leurs étangs, et sur tous leurs amas d''''eaux. Elles deviendront du sang: et il y aura du sang dans tout le pays d''''Egypte, dans les vases de bois et dans les vases de pierre."}, {"numero": 20, "texto": "Moïse et Aaron firent ce que l''''Eternel avait ordonné. Aaron leva la verge, et il frappa les eaux qui étaient dans le fleuve, sous les yeux de Pharaon et sous les yeux de ses serviteurs; et toutes les eaux du fleuve furent changées en sang."}, {"numero": 21, "texto": "Les poissons qui étaient dans le fleuve périrent, le fleuve se corrompit, les Egyptiens ne pouvaient plus boire l''''eau du fleuve, et il y eut du sang dans tout le pays d''''Egypte."}, {"numero": 22, "texto": "Mais les magiciens d''''Egypte en firent autant par leurs enchantements. Le coeur de Pharaon s''''endurcit, et il n''''écouta point Moïse et Aaron, selon ce que l''''Eternel avait dit."}, {"numero": 23, "texto": "Pharaon s''''en retourna, et alla dans sa maison; et il ne prit pas même à coeur ces choses."}, {"numero": 24, "texto": "Tous les Egyptiens creusèrent aux environs du fleuve, pour trouver de l''''eau à boire; car ils ne pouvaient boire de l''''eau du fleuve."}, {"numero": 25, "texto": "Il s''''écoula sept jours, après que l''''Eternel eut frappé le fleuve."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 7, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ dijo á Moisés: Mira, yo te he constituído dios para Faraón, y tu hermano Aarón será tu profeta."}, {"numero": 2, "texto": "Tú dirás todas las cosas que yo te mandaré, y Aarón tu hermano hablará á Faraón, para que deje ir de su tierra á los hijos de Israel."}, {"numero": 3, "texto": "Y yo endureceré el corazón de Faraón, y multiplicaré en la tierra de Egipto mis señales y mis maravillas."}, {"numero": 4, "texto": "Y Faraón no os oirá; mas yo pondré mi mano sobre Egipto, y sacaré á mis ejércitos, mi pueblo, los hijos de Israel, de la tierra de Egipto, con grandes juicios."}, {"numero": 5, "texto": "Y sabrán los Egipcios que yo soy Jehová, cuando extenderé mi mano sobre Egipto, y sacaré los hijos de Israel de en medio de ellos."}, {"numero": 6, "texto": "E hizo Moisés y Aarón como Jehová les mandó: hiciéronlo así."}, {"numero": 7, "texto": "Y era Moisés de edad de ochenta años, y Aarón de edad de ochenta y tres, cuando hablaron á Faraón."}, {"numero": 8, "texto": "Y habló Jehová á Moisés y á Aarón, diciendo:"}, {"numero": 9, "texto": "Si Faraón os respondiere diciendo, Mostrad milagro; dirás á Aarón: Toma tu vara, y échala delante de Faraón, para que se torne culebra."}, {"numero": 10, "texto": "Vinieron, pues, Moisés y Aarón á Faraón, é hicieron como Jehová lo había mandado: y echó Aarón su vara delante de Faraón y de sus siervos, y tornóse culebra."}, {"numero": 11, "texto": "Entonces llamó también Faraón sabios y encantadores; é hicieron también lo mismo los encantadores de Egipto con sus encantamientos;"}, {"numero": 12, "texto": "Pues echó cada uno su vara, las cuales se volvieron culebras: mas la vara de Aarón devoró las varas de ellos."}, {"numero": 13, "texto": "Y el corazón de Faraón se endureció, y no los escuchó; como Jehová lo había dicho."}, {"numero": 14, "texto": "Entonces Jehová dijo á Moisés: El corazón de Faraón está agravado, que no quiere dejar ir al pueblo."}, {"numero": 15, "texto": "Ve por la mañana á Faraón, he aquí que él sale á las aguas; y tú ponte á la orilla del río delante de él, y toma en tu mano la vara que se volvió culebra,"}, {"numero": 16, "texto": "Y dile: Jehová el Dios de los Hebreos me ha enviado á ti, diciendo: Deja ir á mi pueblo, para que me sirvan en el desierto; y he aquí que hasta ahora no has querido oir."}, {"numero": 17, "texto": "Así ha dicho Jehová: En esto conocerás que yo soy Jehová: he aquí, yo heriré con la vara que tengo en mi mano el agua que está en el río, y se convertirá en sangre:"}, {"numero": 18, "texto": "Y los peces que hay en el río morirán, y hederá el río, y tendrán asco los Egipcios de beber el agua del río."}, {"numero": 19, "texto": "Y Jehová dijo á Moisés: Di á Aarón: Toma tu vara, y extiende tu mano sobre las aguas de Egipto, sobre sus ríos, sobre sus arroyos y sobre sus estanques, y sobre todos sus depósitos de aguas, para que se conviertan en sangre, y haya sangre por toda la región de Egipto, así en los vasos de madera como en los de piedra."}, {"numero": 20, "texto": "Y Moisés y Aarón hicieron como Jehová lo mandó; y alzando la vara hirió las aguas que había en el río, en presencia de Faraón y de sus siervos; y todas las aguas que había en el río se convirtieron en sangre."}, {"numero": 21, "texto": "Asimismo los peces que había en el río murieron; y el río se corrompió, que los Egipcios no podían beber de él: y hubo sangre por toda la tierra de Egipto."}, {"numero": 22, "texto": "Y los encantadores de Egipto hicieron lo mismo con sus encantamientos: y el corazón de Faraón se endureció, y no los escuchó; como Jehová lo había dicho."}, {"numero": 23, "texto": "Y tornando Faraón volvióse á su casa, y no puso su corazón aun en esto."}, {"numero": 24, "texto": "Y en todo Egipto hicieron pozos alrededor del río para beber, porque no podían beber de las aguas del río."}, {"numero": 25, "texto": "Y cumpliéronse siete días después que Jehová hirió el río."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 8, 'pt', '[{"numero": 1, "texto": "Então o SENHOR disse a Moisés: Entra à presença de Faraó, e dize-lhe: O SENHOR disse assim: Deixa meu povo ir, para que me sirvam."}, {"numero": 2, "texto": "E se não o quiseres deixar ir, eis que ferirei com rãs todo os teu território;"}, {"numero": 3, "texto": "E o rio criará rãs, que subirão, e entrarão em tua casa, e no teu quarto, e sobre tua cama, e nas casas de teus servos, e em teu povo, e em teus fornos, e em tuas amassadeiras;"}, {"numero": 4, "texto": "E as rãs subirão sobre ti, e sobre teu povo, e sobre todos os teus servos."}, {"numero": 5, "texto": "E o SENHOR disse a Moisés: Dize a Arão: Estende tua mão com tua vara sobre os rios, ribeiros, e tanques, para que faça vir rãs sobre a terra do Egito."}, {"numero": 6, "texto": "Então Arão estendeu sua mão sobre as águas do Egito, e subiram rãs que cobriram a terra do Egito."}, {"numero": 7, "texto": "E os encantadores fizeram o mesmo com seus encantamentos, e fizeram vir rãs sobre a terra do Egito."}, {"numero": 8, "texto": "Então Faraó chamou Moisés e Arão, e disse-lhes: Orai ao SENHOR que tire as rãs de mim e de meu povo; e deixarei ir ao povo, para que sacrifique ao SENHOR."}, {"numero": 9, "texto": "E disse Moisés a Faraó: Tem a honra em meu lugar [de dizer] quando orarei por ti, e por teus servos, e por teu povo, para que as rãs sejam tiradas de ti, e de tuas casas, e que somente se restem no rio."}, {"numero": 10, "texto": "E ele disse: Amanhã. E Moisés respondeu: Será feito conforme tua palavra, para que conheças que não há ninguém como o SENHOR nosso Deus;"}, {"numero": 11, "texto": "E as rãs se irão de ti, e de tuas casas, e de teus servos, e de teu povo, e somente se ficarão no rio."}, {"numero": 12, "texto": "Então saíram Moisés e Arão da presença de Faraó, e clamou Moisés ao SENHOR acerca das rãs que havia posto a Faraó."}, {"numero": 13, "texto": "E o SENHOR fez conforme a palavra de Moisés, e morreram as rãs das casas, dos pátios, e dos campos."}, {"numero": 14, "texto": "E as juntaram em amontoados, e faziam cheirar mal a terra."}, {"numero": 15, "texto": "E vendo Faraó que lhe haviam dado repouso, agravou seu coração, e não os escutou; como o SENHOR o havia dito."}, {"numero": 16, "texto": "Então o SENHOR disse a Moisés: Dize a Arão: Estende a tua vara, e fere o pó da terra, para que se voltem piolhos por toda a terra do Egito."}, {"numero": 17, "texto": "E eles o fizeram assim; e Arão estendeu sua mão com sua vara, e feriu o pó da terra, o qual se tornou piolhos, tanto nos homens como nos animais; todo o pó da terra se tornou piolhos em toda a terra do Egito."}, {"numero": 18, "texto": "E os encantadores tentaram fizeram assim também, para tirar piolhos com seus encantamentos; mas não puderam. E havia piolhos tanto nos homens como nos animais."}, {"numero": 19, "texto": "Então os magos disseram a Faraó: Dedo de Deus é este. Mas o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito."}, {"numero": 20, "texto": "E o SENHOR disse a Moisés: Levanta-te de manhã e põe-te diante de Faraó, eis que ele estará saindo às águas; e dize-lhe: o SENHOR disse assim: Deixa meu povo ir, para que me sirva."}, {"numero": 21, "texto": "Porque se não deixares meu povo ir, eis que enviarei sobre ti, e sobre teus servos, e sobre teu povo, e sobre tuas casas toda variedade de moscas; e as casas dos egípcios se encherão de toda variedade de moscas, e também a terra onde eles estiverem."}, {"numero": 22, "texto": "E naquele dia separarei a terra de Gósen, na qual meu povo habita, para que nenhuma variedade de moscas haja nela; a fim de que saibas que eu sou o SENHOR no meio da terra."}, {"numero": 23, "texto": "E eu porei remissão entre meu povo e o teu. Amanhã será este sinal."}, {"numero": 24, "texto": "E o SENHOR o fez assim: veio toda variedade de moscas incômodas sobre a casa de Faraó, e sobre as casas de seus servos, e sobre toda a terra do Egito; e a terra foi contaminada por causa delas."}, {"numero": 25, "texto": "Então Faraó chamou a Moisés e a Arão, e disse-lhes: Andai, sacrificai a vosso Deus nesta terra."}, {"numero": 26, "texto": "E Moisés respondeu: Não convém que façamos assim, porque sacrificaríamos ao SENHOR nosso Deus a abominação dos egípcios. Eis que, se sacrificássemos a abominação dos egípcios diante deles, não nos apedrejariam?"}, {"numero": 27, "texto": "Caminho de três dias iremos pelo deserto, e sacrificaremos ao SENHOR nosso Deus, como ele nos dirá."}, {"numero": 28, "texto": "E disse Faraó: Eu vos deixarei ir para que sacrifiqueis ao SENHOR vosso Deus no deserto, contanto que não vades mais longe; orai por mim."}, {"numero": 29, "texto": "E respondeu Moisés: Eis que, quando eu sair de tua presença, rogarei ao SENHOR que as diversas variedades de moscas se afastem de Faraó, e de seus servos, e de seu povo amanhã; contanto que Faraó não falte mais, não deixando o povo ir sacrificar ao SENHOR."}, {"numero": 30, "texto": "Então Moisés saiu da presença de Faraó, e orou ao SENHOR."}, {"numero": 31, "texto": "E o SENHOR fez conforme a palavra de Moisés; e tirou todas aquelas moscas de Faraó, e de seus servos, e de seu povo, sem que restasse uma."}, {"numero": 32, "texto": "Mas Faraó agravou ainda esta vez seu coração, e não deixou o povo ir."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 8, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses, Go unto Pharaoh, and say unto him, Thus saith the Lord, Let my people go, that they may serve me."}, {"numero": 2, "texto": "And if thou refuse to let them go, behold, I will smite all thy borders with frogs:"}, {"numero": 3, "texto": "And the river shall bring forth frogs abundantly, which shall go up and come into thine house, and into thy bedchamber, and upon thy bed, and into the house of thy servants, and upon thy people, and into thine ovens, and into thy kneadingtroughs:"}, {"numero": 4, "texto": "And the frogs shall come up both on thee, and upon thy people, and upon all thy servants."}, {"numero": 5, "texto": "And the Lord spake unto Moses, Say unto Aaron, Stretch forth thine hand with thy rod over the streams, over the rivers, and over the ponds, and cause frogs to come up upon the land of Egypt."}, {"numero": 6, "texto": "And Aaron stretched out his hand over the waters of Egypt; and the frogs came up, and covered the land of Egypt."}, {"numero": 7, "texto": "And the magicians did so with their enchantments, and brought up frogs upon the land of Egypt."}, {"numero": 8, "texto": "Then Pharaoh called for Moses and Aaron, and said, Intreat the Lord, that he may take away the frogs from me, and from my people; and I will let the people go, that they may do sacrifice unto the Lord."}, {"numero": 9, "texto": "And Moses said unto Pharaoh, Glory over me: when shall I intreat for thee, and for thy servants, and for thy people, to destroy the frogs from thee and thy houses, that they may remain in the river only?"}, {"numero": 10, "texto": "And he said, To morrow. And he said, Be it according to thy word: that thou mayest know that there is none like unto the Lord our God."}, {"numero": 11, "texto": "And the frogs shall depart from thee, and from thy houses, and from thy servants, and from thy people; they shall remain in the river only."}, {"numero": 12, "texto": "And Moses and Aaron went out from Pharaoh: and Moses cried unto the Lord because of the frogs which he had brought against Pharaoh."}, {"numero": 13, "texto": "And the Lord did according to the word of Moses; and the frogs died out of the houses, out of the villages, and out of the fields."}, {"numero": 14, "texto": "And they gathered them together upon heaps: and the land stank."}, {"numero": 15, "texto": "But when Pharaoh saw that there was respite, he hardened his heart, and hearkened not unto them; as the Lord had said."}, {"numero": 16, "texto": "And the Lord said unto Moses, Say unto Aaron, Stretch out thy rod, and smite the dust of the land, that it may become lice throughout all the land of Egypt."}, {"numero": 17, "texto": "And they did so; for Aaron stretched out his hand with his rod, and smote the dust of the earth, and it became lice in man, and in beast; all the dust of the land became lice throughout all the land of Egypt."}, {"numero": 18, "texto": "And the magicians did so with their enchantments to bring forth lice, but they could not: so there were lice upon man, and upon beast."}, {"numero": 19, "texto": "Then the magicians said unto Pharaoh, This is the finger of God: and Pharaoh''s heart was hardened, and he hearkened not unto them; as the Lord had said."}, {"numero": 20, "texto": "And the Lord said unto Moses, Rise up early in the morning, and stand before Pharaoh; lo, he cometh forth to the water; and say unto him, Thus saith the Lord, Let my people go, that they may serve me."}, {"numero": 21, "texto": "Else, if thou wilt not let my people go, behold, I will send swarms of flies upon thee, and upon thy servants, and upon thy people, and into thy houses: and the houses of the Egyptians shall be full of swarms of flies, and also the ground whereon they are."}, {"numero": 22, "texto": "And I will sever in that day the land of Goshen, in which my people dwell, that no swarms of flies shall be there; to the end thou mayest know that I am the Lord in the midst of the earth."}, {"numero": 23, "texto": "And I will put a division between my people and thy people: to morrow shall this sign be."}, {"numero": 24, "texto": "And the Lord did so; and there came a grievous swarm of flies into the house of Pharaoh, and into his servants'' houses, and into all the land of Egypt: the land was corrupted by reason of the swarm of flies."}, {"numero": 25, "texto": "And Pharaoh called for Moses and for Aaron, and said, Go ye, sacrifice to your God in the land."}, {"numero": 26, "texto": "And Moses said, It is not meet so to do; for we shall sacrifice the abomination of the Egyptians to the Lord our God: lo, shall we sacrifice the abomination of the Egyptians before their eyes, and will they not stone us?"}, {"numero": 27, "texto": "We will go three days'' journey into the wilderness, and sacrifice to the Lord our God, as he shall command us."}, {"numero": 28, "texto": "And Pharaoh said, I will let you go, that ye may sacrifice to the Lord your God in the wilderness; only ye shall not go very far away: intreat for me."}, {"numero": 29, "texto": "And Moses said, Behold, I go out from thee, and I will intreat the Lord that the swarms of flies may depart from Pharaoh, from his servants, and from his people, to morrow: but let not Pharaoh deal deceitfully any more in not letting the people go to sacrifice to the Lord."}, {"numero": 30, "texto": "And Moses went out from Pharaoh, and intreated the Lord."}, {"numero": 31, "texto": "And the Lord did according to the word of Moses; and he removed the swarms of flies from Pharaoh, from his servants, and from his people; there remained not one."}, {"numero": 32, "texto": "And Pharaoh hardened his heart at this time also, neither would he let the people go."}]'::jsonb, 'King James Version'),
  ('Ex', 8, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse: Va vers Pharaon, et tu lui diras: Ainsi parle l''''Eternel: Laisse aller mon peuple, afin qu''''il me serve."}, {"numero": 2, "texto": "Si tu refuses de le laisser aller, je vais frapper par des grenouilles toute l''''étendue de ton pays."}, {"numero": 3, "texto": "Le fleuve fourmillera de grenouilles; elles monteront, et elles entreront dans ta maison, dans ta chambre à coucher et dans ton lit, dans la maison de tes serviteurs et dans celles de ton peuple, dans tes fours et dans tes pétrins."}, {"numero": 4, "texto": "Les grenouilles monteront sur toi, sur ton peuple, et sur tous tes serviteurs."}, {"numero": 5, "texto": "L''''Eternel dit à Moïse: Dis à Aaron: Etends ta main avec ta verge sur les rivières, sur les ruisseaux et sur les étangs, et fais monter les grenouilles sur le pays d''''Egypte."}, {"numero": 6, "texto": "Aaron étendit sa main sur les eaux de l''''Egypte; et les grenouilles montèrent et couvrirent le pays d''''Egypte."}, {"numero": 7, "texto": "Mais les magiciens en firent autant par leurs enchantements. Ils firent monter les grenouilles sur le pays d''''Egypte."}, {"numero": 8, "texto": "Pharaon appela Moïse et Aaron, et dit: Priez l''''Eternel, afin qu''''il éloigne les grenouilles de moi et de mon peuple; et je laisserai aller le peuple, pour qu''''il offre des sacrifices à l''''Eternel."}, {"numero": 9, "texto": "Moïse dit à Pharaon: Glorifie-toi sur moi! Pour quand prierai-je l''''Eternel en ta faveur, en faveur de tes serviteurs et de ton peuple, afin qu''''il retire les grenouilles loin de toi et de tes maisons? Il n''''en restera que dans le fleuve."}, {"numero": 10, "texto": "Il répondit: Pour demain. Et Moïse dit: Il en sera ainsi, afin que tu saches que nul n''''est semblable à l''''Eternel, notre Dieu."}, {"numero": 11, "texto": "Les grenouilles s''''éloigneront de toi et de tes maisons, de tes serviteurs et de ton peuple; il n''''en restera que dans le fleuve."}, {"numero": 12, "texto": "Moïse et Aaron sortirent de chez Pharaon. Et Moïse cria à l''''Eternel au sujet des grenouilles dont il avait frappé Pharaon."}, {"numero": 13, "texto": "L''''Eternel fit ce que demandait Moïse; et les grenouilles périrent dans les maisons, dans les cours et dans les champs."}, {"numero": 14, "texto": "On les entassa par monceaux, et le pays fut infecté."}, {"numero": 15, "texto": "Pharaon, voyant qu''''il y avait du relâche, endurcit son coeur, et il n''''écouta point Moïse et Aaron, selon ce que l''''Eternel avait dit."}, {"numero": 16, "texto": "L''''Eternel dit à Moïse: Dis à Aaron: Etends ta verge, et frappe la poussière de la terre. Elle se changera en poux, dans tout le pays d''''Egypte."}, {"numero": 17, "texto": "Ils firent ainsi. Aaron étendit sa main, avec sa verge, et il frappa la poussière de la terre; et elle fut changée en poux sur les hommes et sur les animaux. Toute la poussière de la terre fut changée en poux, dans tout le pays d''''Egypte."}, {"numero": 18, "texto": "Les magiciens employèrent leurs enchantements pour produire les poux; mais ils ne purent pas. Les poux étaient sur les hommes et sur les animaux."}, {"numero": 19, "texto": "Et les magiciens dirent à Pharaon: C''''est le doigt de Dieu! Le coeur de Pharaon s''''endurcit, et il n''''écouta point Moïse et Aaron, selon ce que l''''Eternel avait dit."}, {"numero": 20, "texto": "L''''Eternel dit à Moïse: Lève-toi de bon matin, et présente-toi devant Pharaon; il sortira pour aller près de l''''eau. Tu lui diras: Ainsi parle l''''Eternel: Laisse aller mon peuple, afin qu''''il me serve."}, {"numero": 21, "texto": "Si tu ne laisses pas aller mon peuple, je vais envoyer les mouches venimeuses contre toi, contre tes serviteurs, contre ton peuple et contre tes maisons; les maisons des Egyptiens seront remplies de mouches, et le sol en sera couvert."}, {"numero": 22, "texto": "Mais, en ce jour-là, je distinguerai le pays de Gosen où habite mon peuple, et là il n''''y aura point de mouches, afin que tu saches que moi, l''''Eternel, je suis au milieu de ce pays."}, {"numero": 23, "texto": "J''''établirai une distinction entre mon peuple et ton peuple. Ce signe sera pour demain."}, {"numero": 24, "texto": "L''''Eternel fit ainsi. Il vint une quantité de mouches venimeuses dans la maison de Pharaon et de ses serviteurs, et tout le pays d''''Egypte fut dévasté par les mouches."}, {"numero": 25, "texto": "Pharaon appela Moïse et Aaron et dit: Allez, offrez des sacrifices à votre Dieu dans le pays."}, {"numero": 26, "texto": "Moïse répondit: Il n''''est point convenable de faire ainsi; car nous offririons à l''''Eternel, notre Dieu, des sacrifices qui sont en abomination aux Egyptiens. Et si nous offrons, sous leurs yeux, des sacrifices qui sont en abomination aux Egyptiens, ne nous lapideront-ils pas?"}, {"numero": 27, "texto": "Nous ferons trois journées de marche dans le désert, et nous offrirons des sacrifices à l''''Eternel, notre Dieu, selon ce qu''''il nous dira."}, {"numero": 28, "texto": "Pharaon dit: Je vous laisserai aller, pour offrir à l''''Eternel, votre Dieu, des sacrifices dans le désert: seulement, vous ne vous éloignerez pas, en y allant. Priez pour moi."}, {"numero": 29, "texto": "Moïse répondit: Je vais sortir de chez toi, et je prierai l''''Eternel. Demain, les mouches s''''éloigneront de Pharaon, de ses serviteurs et de son peuple. Mais, que Pharaon ne trompe plus, en refusant de laisser aller le peuple, pour offrir des sacrifices à l''''Eternel."}, {"numero": 30, "texto": "Moïse sortit de chez Pharaon, et il pria l''''Eternel."}, {"numero": 31, "texto": "L''''Eternel fit ce que demandait Moïse; et les mouches s''''éloignèrent de Pharaon, de ses serviteurs et de son peuple. Il n''''en resta pas une."}, {"numero": 32, "texto": "Mais Pharaon, cette fois encore, endurcit son coeur, et il ne laissa point aller le peuple."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 8, 'es', '[{"numero": 1, "texto": "ENTONCES Jehová dijo á Moisés: Entra á Faraón, y dile: Jehová ha dicho así: Deja ir á mi pueblo, para que me sirvan."}, {"numero": 2, "texto": "Y si no lo quisieres dejar ir, he aquí yo heriré con ranas todos tus términos:"}, {"numero": 3, "texto": "Y el río criará ranas, las cuales subirán, y entrarán en tu casa, y en la cámara de tu cama, y sobre tu cama, y en las casas de tus siervos, y en tu pueblo, y en tus hornos, y en tus artesas:"}, {"numero": 4, "texto": "Y las ranas subirán sobre ti, y sobre tu pueblo, y sobre todos tus siervos."}, {"numero": 5, "texto": "Y Jehová dijo á Moisés: Di á Aarón: Extiende tu mano con tu vara sobre los ríos, arroyos, y estanques, para que haga venir ranas sobre la tierra de Egipto."}, {"numero": 6, "texto": "Entonces Aarón extendió su mano sobre las aguas de Egipto, y subieron ranas que cubrieron la tierra de Egipto."}, {"numero": 7, "texto": "Y los encantadores hicieron lo mismo con sus encantamientos, é hicieron venir ranas sobre la tierra de Egipto."}, {"numero": 8, "texto": "Entonces Faraón llamó á Moisés y á Aarón, y díjoles: Orad á Jehová que quite las ranas de mí y de mi pueblo; y dejaré ir al pueblo, para que sacrifique á Jehová."}, {"numero": 9, "texto": "Y dijo Moisés á Faraón: Gloríate sobre mí: ¿cuándo oraré por ti, y por tus siervos, y por tu pueblo, para que las ranas sean quitadas de ti, y de tus casas, y que solamente se queden en el río?"}, {"numero": 10, "texto": "Y él dijo: Mañana. Y Moisés respondió: Se hará conforme á tu palabra, para que conozcas que no hay como Jehová nuestro Dios:"}, {"numero": 11, "texto": "Y las ranas se irán de ti, y de tus casas, y de tus siervos, y de tu pueblo, y solamente se quedarán en el río."}, {"numero": 12, "texto": "Entonces salieron Moisés y Aarón de con Faraón, y clamó Moisés á Jehová sobre el negocio de las ranas que había puesto á Faraón."}, {"numero": 13, "texto": "E hizo Jehová conforme á la palabra de Moisés, y murieron las ranas de las casas, de los cortijos, y de los campos."}, {"numero": 14, "texto": "Y las juntaron en montones, y apestaban la tierra."}, {"numero": 15, "texto": "Y viendo Faraón que le habían dado reposo, agravó su corazón, y no los escuchó; como Jehová lo había dicho."}, {"numero": 16, "texto": "Entonces Jehová dijo á Moisés: Di á Aarón: Extiende tu vara, y hiere el polvo de la tierra, para que se vuelva piojos por todo el país de Egipto."}, {"numero": 17, "texto": "Y ellos lo hicieron así; y Aarón extendió su mano con su vara, é hirió el polvo de la tierra, el cual se volvió piojos, así en los hombres como en las bestias: todo el polvo de la tierra se volvió piojos en todo el país de Egipto."}, {"numero": 18, "texto": "Y los encantadores hicieron así también, para sacar piojos con sus encantamientos; mas no pudieron. Y había piojos así en los hombres como en las bestias."}, {"numero": 19, "texto": "Entonces los magos dijeron á Faraón: Dedo de Dios es este. Mas el corazón de Faraón se endureció, y no los escuchó; como Jehová lo había dicho."}, {"numero": 20, "texto": "Y Jehová dijo á Moisés: Levántate de mañana y ponte delante de Faraón, he aquí él sale á las aguas; y dile: Jehová ha dicho así: Deja ir á mi pueblo, para que me sirva."}, {"numero": 21, "texto": "Porque si no dejares ir á mi pueblo, he aquí yo enviaré sobre ti, y sobre tus siervos, y sobre tu pueblo, y sobre tus casas toda suerte de moscas; y las casas de los Egipcios se henchirán de toda suerte de moscas, y asimismo la tierra donde ellos estuvieren."}, {"numero": 22, "texto": "Y aquel día yo apartaré la tierra de Gosén, en la cual mi pueblo habita, para que ninguna suerte de moscas haya en ella; á fin de que sepas que yo soy Jehová en medio de la tierra."}, {"numero": 23, "texto": "Y yo pondré redención entre mi pueblo y el tuyo. Mañana será esta señal."}, {"numero": 24, "texto": "Y Jehová lo hizo así: que vino toda suerte de moscas molestísimas sobre la casa de Faraón, y sobre las casas de sus siervos, y sobre todo el país de Egipto; y la tierra fué corrompida á causa de ellas."}, {"numero": 25, "texto": "Entonces Faraón llamó á Moisés y á Aarón, y díjoles: Andad, sacrificad á vuestro Dios en la tierra."}, {"numero": 26, "texto": "Y Moisés respondió: No conviene que hagamos así, porque sacrificaríamos á Jehová nuestro Dios la abominación de los Egipcios. He aquí, si sacrificáramos la abominación de los Egipcios delante de ellos, ¿no nos apedrearían?"}, {"numero": 27, "texto": "Camino de tres días iremos por el desierto, y sacrificaremos á Jehová nuestro Dios, como él nos dirá."}, {"numero": 28, "texto": "Y dijo Faraón: Yo os dejaré ir para que sacrifiquéis á Jehová vuestro Dios en el desierto, con tal que no vayáis más lejos: orad por mí."}, {"numero": 29, "texto": "Y respondió Moisés: He aquí, en saliendo yo de contigo, rogaré á Jehová que las diversas suertes de moscas se vayan de Faraón, y de sus siervos, y de su pueblo mañana; con tal que Faraón no falte más, no dejando ir al pueblo á sacrificar á Jehová."}, {"numero": 30, "texto": "Entonces Moisés salió de con Faraón, y oró á Jehová."}, {"numero": 31, "texto": "Y Jehová hizo conforme á la palabra de Moisés; y quitó todas aquellas moscas de Faraón, y de sus siervos, y de su pueblo, sin que quedara una."}, {"numero": 32, "texto": "Mas Faraón agravó aún esta vez su corazón, y no dejó ir al pueblo."}]'::jsonb, 'Reina-Valera 1909')
